window.DATA=[{"id": "d1_thomas", "dzien": 1, "postac": "Thomas Ward, 71", "glos": "Grzecznie, trochę staroświecko. Żartuje z własnej drżącej ręki.", "typ": "uczciwy, wstydliwy", "rzecz": "Lewa skórzana rękawiczka, zszyta białą nitką przy kciuku", "wnetrze": [{"sekret_id": "d1_kwit_0417", "co_widac": "W mankiecie tkwi kwit z tego biura, numer 0417, sprzed sześciu tygodni. Odręcznie: „Prawa wydana bez wpisu. Lewa czeka. S.H.” W księdze wydań nie ma wpisu o tym numerze, w tym miejscu wyrwano stronę.", "co_z_tego_wynika": "Thomas już tu był i dostał coś, czego nigdzie nie zapisano. Poprzednik wydawał rzeczy poza księgą."}, {"sekret_id": "d1_biala_nic", "co_widac": "Przy kciuku rękawiczki biała nić, zszyta krzywo, ściegiem krawieckim, a pod nią starsza, brązowa, przetarta.", "co_z_tego_wynika": "Ellen sama kiedyś zszyła rękawiczkę brązową nicią. Thomas położył na tym swoją, białą, żeby szew trzymał dłużej."}], "wejscie": "Dobry wieczór. Thomas Ward. Zgubiłem lewą rękawiczkę mojej żony, w tramwaju czwórce. Ellen zmarła w lutym. W niedzielę idę na cmentarz i nie chcę iść z jedną.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta rękawiczka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowa skóra, mały rozmiar. Przy kciuku zszyłem ją białą nitką, bo ciemnej nie miałem. Krzywo, ale trzyma.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy się zgubiła?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, wczoraj wieczorem, jak jechałem do Doków. Leżała mi na kolanie i zsunęła się pod siedzenie na zakręcie.", "mina": "neutralna"}, {"tekst": "Czemu rękawiczki żony były w tramwaju?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Noszę je w kieszeni, jedną w drugiej, jakbym trzymał ją za rękę. Głupie, wiem.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Na kogo wpisać tę rękawiczkę?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Na Ellen Ward. A mnie jako Thomas Ward, przez h.", "mina": "mowi"}, {"tekst": "Jak sprawdzić, że to właśnie ta?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Drugą mam w kieszeni. Proszę je położyć kciukami do siebie: w prawej nitka jest czarna, w lewej biała. Czarna mi się skończyła.", "mina": "neutralna"}, {"tekst": "Czy to pierwsza wizyta w tym biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Pierwsza. Z urzędami się nie zadaję.", "mina": "klamie"}, {"tekst": "W mankiecie jest kwit z tego biura, numer 0417. Skąd on?", "ton": "niewygodne", "wymaga": "d1_kwit_0417", "odpowiedz": "No dobrze, byłem tu. Trzy tygodnie temu zgubiłem prawą. Młody człowiek, Sam, oddał mi ją od ręki i powiedział, że wpisu nie trzeba, bo to pamiątka, a nie zguba. Wstydziłem się, że to drugi raz.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jest jakiś dokument ze zdjęciem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Mam dowód, ale ręka mi drży, a zdjęcie jest sprzed dziesięciu lat. Córka lepiej mnie poświadczy.", "mina": "mowi"}, {"tekst": "Może ktoś jeszcze zgłosić się po tę rękawiczkę?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Córka, Claire. Ale ona nie wie, że rękawiczka się zgubiła. Jakby przyszła, niech jej ktoś powie, że wszystko w porządku.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli rękawiczka zostanie tu do niedzieli?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Pójdę na cmentarz z jedną. Ellen by się śmiała, że sto razy mi mówiła, żebym pilnował rzeczy.", "mina": "emocja"}, {"tekst": "Pod białą nicią jest starszy szew, brązowy. Czyj?", "ton": "niewygodne", "wymaga": "d1_biala_nic", "odpowiedz": "Ellen. Szyła go wieczorem przed telewizorem. Białą dodałem po lutym, bo brązowa się przecierała. Nie chciałem jej zdejmować.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Włożę je do jednej kieszeni, tam, gdzie były.", "zysk": "Thomas idzie w niedzielę na cmentarz z obiema rękawiczkami.", "strata": "Wydajesz na słowo i nitkę, a kwit 0417 zostaje w księdze bez wyjaśnienia.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dziękuję za rękawiczkę. W niedzielę pojechałem z Claire na cmentarz, obie leżały na kamieniu przez godzinę. Claire pyta, kim jest młody człowiek, który wcześniej oddał mi prawą bez papierka. Powiedziałem, że nie wiem, choć wiem. — T. Ward"}}, {"akcja": "zatrzymaj_sprawdz", "etykieta": "Zatrzymaj do sprawdzenia tożsamości", "reakcja": "Rozumiem. Przyjdę jutro z córką, ona ma dowód i wie, jak wygląda ta nitka.", "zysk": "Rękawiczka zostaje w biurze, dopóki ktoś nie potwierdzi, kim jest Thomas.", "strata": "Starszy człowiek wraca do domu z jedną rękawiczką, a niedziela na cmentarzu jest zagrożona.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Claire Ward: „Ojciec dwa dni nie wychodził z domu. Proszę oddać mu tę rękawiczkę, podpiszę za niego. I proszę mi powiedzieć, kto wcześniej oddał mu prawą bez żadnego papieru.”"}}, {"akcja": "wydaj_bez_wpisu", "etykieta": "Wydaj bez wpisu, tak jak zrobił to Sam", "reakcja": "Dziękuję. Tak samo jak ostatnio: bez papierka. Młody człowiek też tak powiedział.", "zysk": "Thomas ma obie rękawiczki od ręki i nikt się nie dowie, że biuro znów wydało coś poza księgą.", "strata": "Powtarzasz to, co robił poprzednik. Wydanie nie zostawia śladu i zalicza się do rachunku „bez wpisu”.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Thomas Ward: „Mówiłem Claire, że w tym biurze ludzie wydają od ręki. Nie powiedziałem jej, że to wasz drugi raz bez papierka.”"}}], "rola": "wdowiec, który kłamie ze wstydu", "watki": ["Poprzednik"], "tik": "żartuje z drżącej ręki", "potrzeba": "lewa rękawiczka żony na niedzielę", "slad": "kwit 0417 zdradza, że już tu był", "sprite": "rekawiczka_skora", "face": "wdowiec", "face2": null, "line": "4", "itemName": "rękawiczka", "inside": {"img": "W1", "x": 0.2, "y": 0.72}}, {"id": "d1_rosa", "dzien": 1, "postac": "Rosa Vale, 33", "glos": "Zmęczona, praktyczna, liczy na głos. Krótkie zdania, suchy humor.", "typ": "uczciwa, ale nie ma jak tego udowodnić", "rzecz": "Brązowa koperta z wypłatą, jedna zszywka", "wnetrze": [{"sekret_id": "d1_lista_nocy", "co_widac": "W kopercie jest 129 dolarów i kartka z listą nocy: trzy odhaczone, czwarta przekreślona. Na odcinku zbiorczym stoi nazwisko I. Bell.", "co_z_tego_wynika": "Wypłatę odbierała i rozdzielała Iris Bell. Czwartą noc Rosy skreśliła Iris."}], "wejscie": "Dobry wieczór. Rosa Vale, pracuję w pralni pod estakadą. Zgubiłam kopertę z wypłatą, 129 dolarów, w jedenastce. Jutro mam czynsz, więc to cały mój tydzień.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta koperta?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowa, jedna zszywka. Zszywka weszła krzywo, bo kierownik zszywał na stojąco.", "mina": "mowi"}, {"tekst": "Gdzie i o której ją zgubiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, o szóstej rano. Położyłam ją obok, żeby zapiąć torbę, i zasnęłam do pętli.", "mina": "neutralna"}, {"tekst": "Skąd wiadomo, że było tam 129 dolarów?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo liczyłam. Trzy noce po 43 dolary, to daje 129. Przeliczyłam trzy razy.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Kto ci wypłacił te pieniądze?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Iris Bell, zarządczyni naszej kamienicy. Odbiera wypłatę z pralni i rozdaje nam w domu. Koperta była od niej.", "mina": "mowi"}, {"tekst": "Co jeszcze jest w środku, poza pieniędzmi?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Kartka z naszymi nocami. Nic ważnego.", "mina": "neutralna"}, {"tekst": "Czemu wypłatę odbiera Iris, a nie same pracownice?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Tak ustaliła. Dla niej wygodnie, dla nas nie bardzo, ale mieszkamy u niej, więc nie dyskutuję.", "mina": "neutralna"}, {"tekst": "Na liście jedna noc jest przekreślona. Dlaczego?", "ton": "niewygodne", "wymaga": "d1_lista_nocy", "odpowiedz": "W czwartek wyszłam o północy, bo córka miała gorączkę. Iris skreśliła całą noc, nie połowę. Czterdzieści trzy dolary za cztery godziny, które przepracowałam. Nie chcę o tym gadać.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Przeliczysz pieniądze przy okienku?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Tak, przy szybie. Jak się ma sto dwadzieścia dziewięć na cały tydzień, to się liczy co do centa.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Rosa Vale, przez V. Podpiszę, jak przeliczę.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli wypłata nie wróci dzisiaj?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Spóźnię się z czynszem, a Iris liczy za to dwadzieścia dolarów kary. Dostanę sto dziewięć zamiast stu dwudziestu dziewięciu.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Przeliczę przy szybie. Sto dwadzieścia dziewięć, zgadza się. Dziękuję, serio.", "zysk": "Rosa ma czynsz na jutro, a w księdze jest jej podpis pod kwotą 129 dolarów.", "strata": "Odcinek zbiorczy jest wystawiony na Iris Bell, więc w papierach wypłata należała do kogoś innego, niż ją odbiera.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Iris zeszła do pralni i spytała, kto mi pozwolił odbierać pieniądze przez okienko. Powiedziałam, że nikt, że sama zgubiłam kopertę. Od przyszłego tygodnia odbieram wypłatę osobiście, bez niej. — Rosa"}}, {"akcja": "odmow", "reakcja": "Dobrze, powiedzcie Iris. Poczekam, tylko czynsz nie poczeka.", "zysk": "Koperta wraca do osoby wskazanej na odcinku, czyli do Iris, zgodnie z przepisem.", "strata": "Rosa płaci dwadzieścia dolarów kary za spóźniony czynsz.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Iris oddała mi kopertę z potrąceniem: sto dziewięć dolarów. Dwadzieścia za spóźniony czynsz, który sama pobiera. Powiedziała, że to formalność. — Rosa"}}, {"akcja": "wez_20", "etykieta": "Wydaj, ale odlicz sobie 20 $ „za fatygę”", "kasa": 20, "reakcja": "Sto dziewięć? Zaraz, przeliczę jeszcze raz. ...Brakuje dwudziestu dolarów. Nie powiem nic, bo kto mi uwierzy.", "zysk": "Dostajesz 20 dolarów do kieszeni, które nikomu nie zostały zapisane.", "strata": "Rosie brakuje dwudziestu dolarów do czynszu, a Iris nalicza jej za to jeszcze karę.", "echo": {"za_dni": 2, "forma": "list", "tekst": "W kopercie brakowało mi dwudziestu dolarów. Iris naliczyła karę za spóźniony czynsz, drugie dwadzieścia. Cztery dychy w plecy przez jedną noc. Nie mówię, że ktoś wziął. Mówię, że brakuje. — Rosa"}}, {"akcja": "przywlaszcz", "etykieta": "Zatrzymaj 129 $ dla siebie", "kasa": 129, "reakcja": "Nie ma? To ostatnie miejsce, gdzie szukałam. Dziękuję, że sprawdziłeś. Powiem pani Iris, że wypłata przepadła w tramwaju.", "zysk": "+129 $ w kieszeni: prawie cały czynsz za tydzień.", "strata": "Rosa wraca do domu bez wypłaty za całą nockę, a w księdze nie ma po kopercie śladu.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Sto dwadzieścia dziewięć dolarów, tyle było w kopercie. Ada pytała, czemu dziś na kolację tylko chleb. Pani Iris potrąci mi to z następnej wypłaty i nie chce słuchać. Wiem, że to nie twoja wina. Chciałam komuś to powiedzieć. Rosa"}}], "rola": "praczka z kopertą wypłaty", "watki": ["kamienica", "pieniądze"], "tik": "liczy na głos", "potrzeba": "129 $ na czynsz do jutra", "slad": "nazwisko I. Bell na odcinku wypłat", "sprite": "koperta", "face": null, "face2": null, "line": "11", "itemName": "koperta", "inside": {"img": "W20", "x": 0.51, "y": 0.58}}, {"id": "d2_jonah", "dzien": 2, "postac": "Jonah Pike, 22", "glos": "Mówi szybko, poprawia się w pół zdania. Kiedy pada imię June, zwalnia.", "typ": "uczciwy, zdenerwowany", "rzecz": "Czarny plecak z pękniętą klamrą", "wnetrze": [{"sekret_id": "d2_paragon_raty", "co_widac": "W pudełku w kieszeni na plecach leży pierścionek z małym oczkiem. Obok paragon: wpłacone 40 dolarów, 200 zostało do spłaty w ratach. Na serwetce trzy wersje oświadczyn, dwie przekreślone.", "co_z_tego_wynika": "Jonah o siódmej rano chce się oświadczyć, a pierścionek kupił na raty. Pierścionek jest wart w lombardzie około 150 dolarów."}, {"sekret_id": "d2_serwetka_trzy", "co_widac": "W kieszeni plecaka serwetka z trzema wersjami oświadczyn, dwie przekreślone. Pod spodem paragon z lombardu na pierścionek na raty, 150 $.", "co_z_tego_wynika": "Jonah ćwiczy oświadczyny, a pierścionek kupił na raty, więc obie rzeczy są jego tajemnicą."}], "wejscie": "Cześć, Jonah. Zgubiłem plecak w jedenastce, czarny, z pękniętą klamrą. Potrzebuję go przed siódmą rano, bo w kieszeni jest coś ważnego. Naprawdę ważnego.", "tury": [{"pytania": [{"tekst": "Co jest w plecaku?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Ładowarka, książka, mnóstwo biletów, nie wiem, czemu je zbieram. I pudełko w kieszeni na plecach. Pudełko jest najważniejsze.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy go zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, wczoraj wieczorem, pod składanym siedzeniem przy drzwiach. Wcisnąłem go nogą, żeby June miała gdzie stanąć.", "mina": "mowi"}, {"tekst": "Co jest w tym pudełku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Prezent. Niespodzianka, więcej nie powiem.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Kim jest June?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Moją dziewczyną. Pracuje w piekarni, wstaje o czwartej. O siódmej rano, zanim wyjdzie, chcę ją o coś zapytać. Dlatego ten plecak.", "mina": "emocja"}, {"tekst": "Jak chcesz jej to powiedzieć?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W kuchni, zanim założy buty. Mam trzy wersje na serwetce. Żadna mi się nie podoba.", "mina": "mowi"}, {"tekst": "A jak odmówi?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "To będzie najgorszy poranek mojego życia. Ale wolę zapytać, niż się nie dowiedzieć.", "mina": "emocja"}, {"tekst": "Na paragonie 40 dolarów wpłaty i reszta na raty. Stać cię na to?", "ton": "niewygodne", "wymaga": "d2_paragon_raty", "odpowiedz": "Nie stać. Wziąłem na sześć rat, jestem kurierem. Ale ona jest tego warta. I tak, wiem, jak to brzmi.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Zdążysz do domu przed siódmą?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Rowerem dziesięć minut. Zdążę z zapasem, byle ktoś mi go dał dzisiaj.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jonah Pike. Pike jak ta ryba.", "mina": "neutralna"}, {"tekst": "Co zrobisz, jeśli plecak nie wróci przed siódmą?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Przełożę, ale June od razu zauważy, że coś jest nie tak. Ona zawsze wie. Przy niej nie umiem kłamać.", "mina": "emocja"}, {"tekst": "Na serwetce są trzy wersje oświadczyn. Którą wybierzesz?", "ton": "niewygodne", "wymaga": "d2_serwetka_trzy", "odpowiedz": "Trzecią, krótką. Dwie pierwsze brzmiały jak reklama. Jak powiem ją źle, to powiem ją źle. Tylko nie pokazuj serwetki nikomu, serio.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki! Serio, dzięki. Lecę, zanim się rozmyślę.", "zysk": "Jonah wraca do domu z pierścionkiem i ma noc na ćwiczenie oświadczyn.", "strata": "Plecak wychodzi po samym opisie i podpisie, nikt nie sprawdził pudełka w kieszeni.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Jonah: „Zdążyłem. O siódmej zapytałem June, serwetka została w kieszeni. Trzymaj kciuki, jeśli masz kciuki.”"}}, {"akcja": "odmow", "reakcja": "Co? Ale to MÓJ plecak! Dobrze, dobrze, wrócę z kimś, kto potwierdzi.", "zysk": "Plecak zostaje w biurze do czasu dowodu własności.", "strata": "Jonah może nie zdążyć do siódmej, a June zauważy, że coś jest nie tak.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Jonah: „Odebrałem plecak dopiero rano, spóźniłem się. June chyba się domyśla. Pierścionek nadal mam.”"}}, {"akcja": "wez_pierscionek", "etykieta": "Zatrzymaj pierścionek, plecak wydaj", "kasa": 150, "reakcja": "Dziękuję, lecę. ...Eee, a pudełko? Jest puste! Zaraz, gdzie...? Ja... idę na policję.", "zysk": "Pierścionek jest wart w lombardzie około 150 dolarów, niemal tygodniowy czynsz.", "strata": "Jonah zgłasza kradzież na komisariacie, a oświadczyny rano upadają. Policja zapyta, kto miał plecak.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Noah Reyes: „Był tu mężczyzna z plecakiem. Zgłosił kradzież pierścionka z plecaka, który odebrał z biura rzeczy znalezionych. Czyli: jedno biuro, jedno nocne okienko. Zapiszę.”"}, "wymaga": "d2_paragon_raty"}], "rola": "kurier z pierścionkiem na raty", "watki": ["Marlow", "pieniądze"], "tik": "zwalnia na imieniu June", "potrzeba": "plecak z pierścionkiem na siódmą rano", "slad": "raty zdradzają dług, który ma Marlow", "sprite": "plecak", "face": "chlopak", "face2": null, "line": "11", "itemName": "plecak", "inside": null}, {"id": "d2_hana", "dzien": 2, "postac": "Hana Moreau, 26", "glos": "Mówi starannie, jakby recytowała. Przy kłamstwie podkreśla każdą sylabę.", "typ": "sympatyczna kłamczyni", "rzecz": "Czarny sztywny futerał na skrzypce z zieloną naklejką", "wnetrze": [{"sekret_id": "d2_etykieta_wyp", "co_widac": "Pod pokrywą futerału przyklejona kartka: „Własność Konserwatorium. Wypożyczone H. Moreau do 7 sierpnia.” Dziś jest 10 sierpnia.", "co_z_tego_wynika": "Skrzypce nie są Hany. Jej wypożyczenie skończyło się wczoraj."}, {"sekret_id": "d2_naklejka_zielona", "co_widac": "Na zewnątrz futerału zielona naklejka z numerem inwentarzowym 0334 i pieczątką Konserwatorium, częściowo zdrapana paznokciem.", "co_z_tego_wynika": "Hana próbowała zdrapać numer inwentarzowy, żeby futerał wyglądał na jej własny."}], "wejscie": "Dobry wieczór. Hana Moreau, skrzypaczka. Zgubiłam futerał ze skrzypcami w czwórce. O ósmej rano mam przesłuchanie do orkiestry i bez tych skrzypiec nie mam po co przychodzić.", "tury": [{"pytania": [{"tekst": "Jak wygląda futerał?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, sztywny, z mosiężnymi zamkami. W środku wieka zielona naklejka, a rączka owinięta czerwoną taśmą.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie go zostawiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, w ostatnim kursie. Postawiłam go między nogami, zadzwoniła mama i wysiadłam bez futerału.", "mina": "neutralna"}, {"tekst": "Czyje to są skrzypce?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Moje. Oczywiście, że moje. Gram na nich od siedmiu lat.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Co jeszcze jest w futerale?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Kalafonia, szmatka z jedwabiu i nuty Mendelssohna z moimi zapiskami ołówkiem.", "mina": "mowi"}, {"tekst": "Czy w skrzypcach jest etykieta lutnika?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jest, ale mała. Nazwiska nie pamiętam, od lat nie zaglądałam do środka.", "mina": "neutralna"}, {"tekst": "Dlaczego to takie pilne właśnie dzisiaj?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo przesłuchanie mam rano, o ósmej. Dostałam się z listy rezerwowej, drugiej szansy nie będzie.", "mina": "emocja"}, {"tekst": "Pod pokrywą jest kartka: wypożyczenie do 7 sierpnia. Co to znaczy?", "ton": "niewygodne", "wymaga": "d2_etykieta_wyp", "odpowiedz": "Że termin minął w sobotę. Konserwatorium nie przedłużyło, bo komisja zbiera się dopiero w czwartek. Nie jestem złodziejką, tylko spóźniłam się o trzy dni. Ale przesłuchanie mam dziś rano.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Daleko stąd do filharmonii?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Cztery przystanki. Próba jest o siódmej, więc jeśli wyjdę stąd przed szóstą, zdążę rozgrzać palce.", "mina": "mowi"}, {"tekst": "Odbiór instrumentu wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Hana Moreau. Napiszę czytelnie, choć ręka mi drży od wczoraj.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli skrzypce wrócą do konserwatorium?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy ktoś inny zagra moje przesłuchanie, a mnie wykreślą z listy. Bez skrzypiec nie mam po co tam iść.", "mina": "emocja"}, {"tekst": "Zielona naklejka jest częściowo zdrapana. Kto ją zdrapywał?", "ton": "niewygodne", "wymaga": "d2_naklejka_zielona", "odpowiedz": "Ja. Z nerwów, w tramwaju. Numer inwentarzowy wygląda jak etykieta kradzieży, a ja nie kradnę. Chciałam, żeby przez chwilę było moje.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. W czwartek pójdę do komisji, obiecuję. Najpierw zagram.", "zysk": "Hana zagra przesłuchanie i ma szansę dostać miejsce w orkiestrze.", "strata": "Oddajesz instrument konserwatorium komuś, komu wypożyczenie wygasło w sobotę.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Zagrałam. Nikt nie wiedział, że skrzypce są po terminie. Dziś po południu komisja przedłużyła mi wypożyczenie do końca roku. Przepraszam za zamieszanie. — H. Moreau"}}, {"akcja": "odmow", "reakcja": "Rozumiem. Skrzypce należą do konserwatorium. Powiedz im chociaż, że sama się zgłosiłam.", "zysk": "Skrzypce wracają do prawdziwego właściciela, czyli do konserwatorium.", "strata": "Hana traci przesłuchanie i miejsce na liście.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Konserwatorium odebrało skrzypce i podziękowało za sumienność. Na przesłuchaniu zagrał ktoś inny. Ja gram teraz na altówce koleżanki w piwnicy. Dyplom mam. Orkiestry nie. — H. Moreau"}}], "rola": "skrzypaczka z cudzymi skrzypcami", "watki": ["humor"], "tik": "mówi jak recytacja", "potrzeba": "skrzypce na przesłuchanie o ósmej", "slad": "wypożyczenie z konserwatorium skończyło się już wczoraj", "sprite": "futeral", "face": null, "face2": null, "line": "4", "itemName": "futerał na skrzypce", "inside": null}, {"id": "d2_ines", "dzien": 2, "postac": "Ines Calloway, 61", "glos": "Spokojna, sucha, mówi tonem urzędniczki na emeryturze. Poprawia innych, zanim skończą zdanie.", "typ": "uczciwa, z ukrytym celem", "rzecz": "Czarny parasol z rączką w kształcie kaczki", "wnetrze": [{"sekret_id": "d2_parasol_kartka", "co_widac": "W rączce parasola zwinięta kartka: „Szukam kota, rudego, od zimy. Odpowiedzi na słupie przy wejściu.” Rączka ma ślad kleju od taśmy.", "co_z_tego_wynika": "Ines wiesza ogłoszenia o kocie na słupie. Kota nie ma. Ktoś odpowiada na te kartki i zostawia coś w okienku."}], "wejscie": "Ines Calloway. Zgubiłam parasol z rączką w kształcie kaczki, w czwórce, wczoraj. Poza tym chciałabym zapytać, czy wolno mi wieszać ogłoszenia na słupie przy wejściu. Kot, rudy, od zimy.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten parasol?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, automatyczny, rączka w kształcie kaczki. Dziób ma odłamany z lewej. Kupiłam go po zeszłorocznej wichurze.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie go zostawiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, na haczyku przy tylnych drzwiach. Wysiadałam na pętli, ręce miałam pełne torby i zostawiłam go dopiero w zakręcie.", "mina": "neutralna"}, {"tekst": "Czemu pytasz o ogłoszenie, a nie wieszasz po prostu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo wolę zapytać. Słupy mają właścicieli. Ten przy wejściu ma właściciela, którego jeszcze nie poznałam.", "mina": "neutralna"}, {"tekst": "W rączce jest kartka z ogłoszeniem o kocie. Skąd?", "ton": "niewygodne", "wymaga": "d2_parasol_kartka", "odpowiedz": "Mój tekst. Wkładam kopię do rączki, żeby nie zgubić. A kota nie ma od zimy, więc proszę nie pytać.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Jak wygląda Twój kot?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Rudy, z białą łapką. Wabi się Fryderyk. Nie przychodzi na wołanie, tylko na ciszę.", "mina": "mowi"}, {"tekst": "Od kiedy go nie ma?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Od zimy. Dokładnie od pierwszego śniegu. Drzwi były zamknięte, a on wyszedł oknem, którego nie otwiera się od środka.", "mina": "neutralna"}, {"tekst": "Czemu nikt nie odpowiada na Twoje ogłoszenia?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Odpowiada. To znaczy: ktoś zostawia kartkę z odpowiedzią. Przychodzi nocą, nie widziałam kto. Potem już nie szukam.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co chcesz, żebym zrobił z ogłoszeniem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Żeby ogłoszenie zostało. Tylko tyle. Jak ktoś przyjdzie z kotem, powiedzcie mu, że szukam, i nie pytajcie o resztę.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór parasola?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Ines Calloway. Pisownia z jednym „l”. Proszę zapisać równo.", "mina": "neutralna"}, {"tekst": "Czy to naprawdę jest ogłoszenie o kocie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Tak. Dla kota. Dla innych, którzy też szukają. Proszę nie czytać między wierszami, bo ich tam jest dwa razy więcej.", "mina": "klamie"}]}], "decyzje": [{"akcja": "ines_potwierdz", "etykieta": "Potwierdź ogłoszenie i przybij pieczątkę okienka", "reakcja": "Dziękuję. Kartka z pieczątką okienka wisi na słupie jak legitymacja. Nie pytajcie, dla kogo.", "zysk": "Parasol wraca do Ines, a ogłoszenie ma pieczątkę, więc nikt go nie zdejmie.", "strata": "Okienko jest teraz widoczne na słupie, a ktoś przeczyta pieczątkę jako zaproszenie.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Ines Calloway: „Ktoś odpowiedział na kartkę. Zostawił coś pod okienkiem. Proszę nie otwierać przy ludziach. — I.C.”"}}, {"akcja": "ines_odmow", "etykieta": "Wydaj parasol, ogłoszenia odmów", "reakcja": "Rozumiem. Słup ma właściciela, ale wiesza się je na innych. Dobrze.", "zysk": "Okienko nie robi za tablicę ogłoszeń i nikt nie zapyta o słup.", "strata": "Ines znajdzie inny słup, a kartki będą wisieć dalej, tylko bez Twojej wiedzy.", "echo": {"za_dni": 4, "forma": "list", "tekst": "Ines Calloway: „Powiesiłam kartkę na innym słupie. Odpowiedzi też tam przychodzą. Dziękuję za parasol. — I.C.”"}}, {"akcja": "ines_zdejmij", "etykieta": "Wydaj parasol i zdejmij ogłoszenie ze słupa", "reakcja": "Zdejmiecie? To cudze kartki, nie moje. Dobrze, wiem, kto je dostał.", "zysk": "Słup przy wejściu jest czysty, a do biura nikt nie przynosi kartek.", "strata": "Ktoś czekał na odpowiedź na tym słupie i nie dostanie jej.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Mężczyzna w szarym kapeluszu: „Zgodnie z regulaminem. Szukałem kartki o kocie. Słup jest pusty. Zapiszę, kto go opróżnił.”"}}], "rola": "emerytka z ogłoszeniami o kocie", "watki": ["ogloszenie"], "tik": "poprawia innych przed końcem zdania", "potrzeba": "parasol i zgoda na ogłoszenie na słupie", "slad": "kartka o kocie w rączce, odpowiedzi na słupie", "sprite": "parasol", "face": null, "face2": null, "line": "4", "itemName": "Czarny parasol z rączką w kszt", "inside": null}, {"id": "d3_maz_i_siostra", "dzien": 3, "postac": "Evan Doyle, 37, i Lena Brandt, 31", "glos": "Evan: grzecznie, pełnymi zdaniami, wraca do tego samego pytania. Lena: szybko, urywa, mówi za dużo.", "typ": "Evan kłamie, Lena mówi prawdę", "rzecz": "Czarny telefon w skórzanym etui z odklejonym rogiem", "ludzie": {"maz": "Evan", "siostra": "Lena"}, "wnetrze": [{"sekret_id": "d3_telefon_wiadomosc", "co_widac": "Na ekranie wisi wiadomość od „Lena” z czwartku, 21:48: „Nie wracaj do domu. Jadę po ciebie w sobotę.” Pod etui złożone stare zdjęcie dwóch dziewczynek, podpisane „Maya i Lena”.", "co_z_tego_wynika": "To telefon Mai. Siostra kazała jej nie wracać do męża, a telefon został w tramwaju po tej wiadomości."}], "wejscie": "Dobry wieczór. Evan Doyle, a to Lena, siostra mojej żony. Oboje przyszliśmy po telefon Mai, która zaginęła w czwartek. Zostawiła go w jedenastce. Dwudziestego drugiego policja zamyka sprawę. Nie mamy czasu.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten telefon?", "ton": "uprzejme", "kto": "maz", "wymaga": null, "odpowiedz": "Czarny, w skórzanym etui z odklejonym rogiem. Kupiłem jej to etui na rocznicę.", "mina": "mowi"}, {"tekst": "Kiedy Maya go zgubiła?", "ton": "rzeczowe", "kto": "siostra", "wymaga": null, "odpowiedz": "W czwartek wieczorem, w jedenastce. Ale ona nie gubi rzeczy. Zostawia je tam, gdzie ktoś je przechowa i nie zapyta, po co.", "mina": "klamie"}, {"tekst": "Jak wyglądała ostatnia rozmowa z Mayą?", "ton": "niewygodne", "kto": "maz", "wymaga": null, "odpowiedz": "Zwyczajnie. Nie było żadnej kłótni. Zjedliśmy kolację, poszła do pracy i nie wróciła.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Co jest w tym telefonie?", "ton": "uprzejme", "kto": "siostra", "wymaga": null, "odpowiedz": "Zdjęcia, muzyka, kontakty. I trochę wiadomości ode mnie, zwykłe rzeczy między siostrami.", "mina": "mowi"}, {"tekst": "Po co policji ten telefon?", "ton": "rzeczowe", "kto": "maz", "wymaga": null, "odpowiedz": "Żeby sprawdzić, dokąd poszła. Policjant powiedział, że bez telefonu do wtorku, siódmego września, zamkną sprawę i tyle.", "mina": "mowi"}, {"tekst": "Czy Maya miała powód, żeby odejść?", "ton": "niewygodne", "kto": "maz", "wymaga": null, "odpowiedz": "Żadnego. Mieliśmy spokojne małżeństwo. Oboje dużo pracowaliśmy, to wszystko.", "mina": "klamie"}, {"tekst": "SMS od Leny: „Nie wracaj do domu.” Co to znaczy?", "ton": "niewygodne", "kto": "siostra", "wymaga": "d3_telefon_wiadomosc", "odpowiedz": "To ja napisałam. Maya zadzwoniła w czwartek, że boi się wracać. Jak Evan to przeczyta, przyjdzie do mnie. Proszę nie dawać mu tego telefonu.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Kiedy ostatnio miałaś od niej wieści?", "ton": "uprzejme", "kto": "siostra", "wymaga": null, "odpowiedz": "Od czwartku nic. Ani słowa. Naprawdę.", "mina": "klamie"}, {"tekst": "Co zrobisz z telefonem, jeśli go dostaniesz?", "ton": "rzeczowe", "kto": "maz", "wymaga": null, "odpowiedz": "Zaniosę go policjantowi, Reyesowi z komisariatu przy Rynku. Jeszcze dziś.", "mina": "mowi"}, {"tekst": "Co będzie, jeśli telefon zostanie w biurze?", "ton": "niewygodne", "kto": "maz", "wymaga": null, "odpowiedz": "Policja dostanie go za późno. Wiesz co, sto dolarów od ręki, i nikt nie musi tego wpisywać. Zgoda?", "mina": "mowi", "ustawia": "d3_evan_oferta"}]}], "decyzje": [{"akcja": "wydaj_evan", "etykieta": "Wydaj telefon Evanowi", "kto": "maz", "reakcja": "Dziękuję. Idę z tym do Reyesa. Lena, nie patrz tak.", "zysk": "Telefon trafia do policji z podpisem Evana w księdze. Czyste wydanie, nikt nie ma do ciebie pretensji.", "strata": "Evan przeczyta SMS od Leny i pójdzie do niej z awanturą, a Lena ci tego nie zapomni.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Evan był u mnie wieczorem. Przeczytał wiadomość i krzyczał na klatce, aż sąsiadka wyszła. Powiedział, że biuro wydało mu telefon, więc teraz wie wszystko. — Lena"}}, {"akcja": "wydaj_lena", "etykieta": "Wydaj telefon Lenie", "kto": "siostra", "reakcja": "Dziękuję. Zabieram go do siebie. Evan, nie patrz tak na mnie, to rodzinne.", "zysk": "Lena zabiera telefon i wiadomość nie dociera do Evana.", "strata": "Evan zostaje bez śladu po żonie i przestaje ufać biuru.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Evan Doyle: „Wydano telefon mojej żony komuś innemu. Chcę wiedzieć komu i na jakiej podstawie. Jestem jej mężem.”"}}, {"akcja": "zatrzymaj", "etykieta": "Zatrzymaj telefon dla Mai", "reakcja": "To znaczy, że nikt go nie dostanie? A jeśli ona po niego nie przyjdzie?", "zysk": "Telefon leży w biurze, nikt go nie czyta.", "strata": "Evan i Lena wychodzą z niczym, a Maya nie wiadomo czy po telefon wróci.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Noah Reyes: „Doyle dzwoni do mnie co godzinę, że telefon żony jest w biurze i go nie wydają. Czyli: wiem, gdzie jest. Nie mówię, że to źle.”"}}, {"akcja": "wez_100_evan", "etykieta": "Wydaj telefon Evanowi i przyjmij od niego 100 $", "kasa": 100, "kto": "maz", "reakcja": "Proszę. Cieszę się, że się rozumiemy. Lena, idziemy.", "zysk": "Dostajesz 100 dolarów do ręki, czyli większość raty dla Kuby.", "strata": "Telefon idzie do Evana bez podpisu i bez wpisu. Lena widzi kopertę, a Evan zapamięta, że biuro ma cenę, i w dniu 7 przyjdzie po więcej.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Lena Brandt: „Widziałam, jak Evan podał kopertę, a okienko ją wzięło. Nie wiem już, komu tu wierzyć.”"}, "wymaga": "d3_evan_oferta"}], "rola": "mąż i szwagierka po telefon Mai", "watki": ["Zaginiona"], "tik": "Evan poprawia mankiet", "potrzeba": "telefon Mai z jedną wiadomością", "slad": "SMS „Nie wracaj do domu” rozdziela ich", "sprite": "telefon", "face": "maz", "face2": {"maz": "maz", "siostra": "siostra"}, "line": "11", "itemName": "telefon", "inside": null}, {"id": "d3_dana", "dzien": 3, "postac": "Dana Ruiz, 38", "glos": "Głośno, prosto, bez owijania. Mówi o budziku jak o koledze z pracy.", "typ": "uczciwa, rozbrajająca", "rzecz": "Blaszany budzik z dwoma dzwonkami", "wnetrze": [{"sekret_id": "d3_rachunek_budzik", "co_widac": "Pod tylną pokrywką budzika złożony rachunek z warsztatu: 18 $ za wymianę mechanizmu, na dole dopisek „dzwonek do wymiany”.", "co_z_tego_wynika": "Dana naprawia stary budzik zamiast kupić nowy. Dwanaście lat to jej jedyny zegar i jej strach, że zaśpi."}], "wejscie": "Cześć, Dana Ruiz, mechanik w zajezdni. Zgubiłam budzik w szóstce, taki blaszany, z dwoma dzwonkami. Bez niego nie wstanę na czwartą, a w zajezdni nikt nie czeka, jak ktoś się spóźni.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten budzik?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Blaszany, okrągły, dwa dzwonki na górze. Mam go od dwunastu lat i dzwoni tak, że sąsiad się budzi.", "mina": "mowi"}, {"tekst": "Na którą jest nastawiony?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na czwartą piętnaście. Wskazówka alarmu jest czerwona, krzywa, bo kiedyś ją naprawiałam kombinerkami.", "mina": "mowi"}, {"tekst": "Czemu zabierasz budzik do tramwaju?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo wczoraj poszłam spać u siostry. Nie chciałam go zostawić samego, wiesz, jak to jest.", "mina": "mowi"}, {"tekst": "Pod pokrywką jest rachunek z warsztatu. Co to?", "ton": "niewygodne", "wymaga": "d3_rachunek_budzik", "odpowiedz": "Osiemnaście dolarów za mechanizm. Nowy kosztuje więcej, a ten ma ton, który znam. Jak się zepsuje, nie wstanę. To głupie, ale to mój zegar.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co masz jeszcze w torbie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Klucz francuski, kanapkę i gazetę. W gazecie ciągle to samo ogłoszenie, że szukają kogoś do nocnego okienka. Bez referencji. Kanapka jest dla budzika, żartuję.", "mina": "mowi"}, {"tekst": "Czym potwierdzisz, że to twój?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na spodzie jest naklejka „Mama”, bo mama mi go dała. I wgniecenie przy prawym dzwonku, jak spadł z lodówki.", "mina": "mowi"}, {"tekst": "Jak długo pracujesz w zajezdni?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Jedenaście lat. Znam tu każdy zawias. A dziś stoję w kolejce przez budzik. Śmieszne, nie?", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Kiedy musisz być w zajezdni?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Za pięć piąta. Jak wstanę o czwartej piętnaście, zdążę na kawę. Jak nie, na nic.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Dana Ruiz, przez „z” na końcu. Wszyscy piszą „s”.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli budzik zostanie w biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Kupię nowy, ale ten ma w sobie moje dwanaście lat. Nowy nie będzie mnie lubił.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki! Czwarta piętnaście, słyszysz, budziku? Bez ciebie nie ruszam.", "zysk": "Dana wstanie na czwartą piętnaście i zdąży do zajezdni.", "strata": "Nic cię to nie kosztuje, poza dwiema minutami kolejki.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Dana Ruiz: „Wpadłam tylko powiedzieć dzięki. Budzik działa, sąsiad się obudził, ja też.”"}}, {"akcja": "odmow", "reakcja": "Co? Ale przecież to mój budzik! No dobra, przyniosę kogoś z zajezdni, żeby potwierdził.", "zysk": "Budzik zostaje w biurze do potwierdzenia.", "strata": "Dana nie wstanie na czwartą i spóźni się do pracy, a w zajezdni nikt jej nie wybroni.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Dana Ruiz: „Spóźniłam się do pracy o czterdzieści minut. Przełożony zapisał. A ja zapamiętam, kto mi nie oddał budzika.”"}}], "rola": "mechaniczka z ukochanym budzikiem", "watki": ["humor"], "tik": "mówi głośno i prosto", "potrzeba": "budzik na czwartą rano", "slad": "dwie minuty oddechu po ciężkiej scenie", "sprite": "budzik", "face": null, "face2": null, "line": "6", "itemName": "Blaszany budzik z dwoma dzwonk", "inside": null}, {"id": "d4_iris", "dzien": 4, "postac": "Iris Bell, 56", "glos": "Cicho, uprzejmie, ze zdrobnieniami. Prosi o „drobną przysługę”, a groźbę podaje jak prognozę pogody.", "typ": "presja i łapówka", "rzecz": "Płaska paczka w szarym płótnie, przewiązana sznurkiem", "wnetrze": [{"sekret_id": "d4_blankiet_kasetka", "co_widac": "Pod płótnem leży kasetka na kłódkę, przez szparę widać brzeg paszportu z wyciętą stroną. Obok blankiet z numerem odbioru 0412 i dopisek „dla nocnej zmiany, bez wpisu”.", "co_z_tego_wynika": "To nie są papiery lokatorów, tylko dokumenty dla kogoś, kto chce zniknąć. Poprzednik przyjmował takie paczki bez wpisu."}], "wejscie": "Dobry wieczór. Iris Bell, zarządzam kamienicą przy Cooper Street dziewięć. Zgubiła mi się paczka w szarym płótnie, w szóstce, ostatnim kursem. Drobiazg, ale lokatorzy czekają na nią do rana.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta paczka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Płaska, w szarym płótnie, związana sznurkiem. W środku niewielka kasetka na kłódkę.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie została?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W szóstce, ostatnim kursem, na półce nad siedzeniem. Zawsze tak kładę i zawsze pamiętam. Wczoraj nie.", "mina": "neutralna"}, {"tekst": "Co jest w kasetce?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Papiery lokatorów. Pokwitowania, drobne rozliczenia. Nic ciekawego.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Kim są ci lokatorzy?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dwadzieścia rodzin z kamienicy. Zbieram od nich zaliczki na remont i trzymam ich dokumenty, żeby się nie zgubiły. Ironia, prawda?", "mina": "mowi"}, {"tekst": "Czemu paczka jedzie tramwajem, a nie pocztą?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo lokatorzy odbierają o różnych godzinach, a tramwaj to najtańszy goniec.", "mina": "neutralna"}, {"tekst": "Czemu tej paczki nie może odebrać nikt inny?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo to moje. Nie lubię, jak ktoś grzebie w rzeczach lokatorów.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Zależy ci na czasie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Najlepiej dziś. Nie lubię naciskać, ale lokatorzy lubią spać spokojnie.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Oczywiście, Iris Bell. I chciałabym zostawić drobną kopertę za fatygę, nie jako opłatę, tylko jako wyraz uznania. Sto dwadzieścia dolarów.", "mina": "neutralna", "ustawia": "d4_koperta_oferta"}, {"tekst": "A jeśli paczka wyjdzie z wpisem w księdze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "To wyjdzie. Poprzednik nie wpisywał i wszystkim było wygodnie. Poczekam. Tylko lokatorzy czekać nie lubią.", "mina": "neutralna"}, {"tekst": "W kasetce widać brzeg paszportu z wyciętą stroną. Czyj to?", "ton": "niewygodne", "wymaga": "d4_blankiet_kasetka", "odpowiedz": "Takiego, kto w tym tygodniu jedzie. Jeśli paczka zostanie, nie pojedzie. Nowi zwykle odchodzą w pierwszym tygodniu.", "mina": "emocja"}]}], "decyzje": [{"akcja": "rejestr", "etykieta": "Wydaj paczkę i zapisz w księdze", "reakcja": "Dziękuję. Pełny wpis, jak widzę. Bardzo oficjalnie, ale dobrze.", "zysk": "Księga jest czysta, a paczka wychodzi do Iris z jej podpisem.", "strata": "Księgę czyta Victor, więc Iris i paczka 0412 są teraz na papierze. Iris ci tego nie zapomni.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Paczka dotarła. Dziękuję za pełny wpis. Poprzedni współpracownik nie był tak skrupulatny, może to i lepiej. Ja lubię wiedzieć, z kim pracuję. — I. Bell"}}, {"akcja": "koperta", "etykieta": "Wydaj i przyjmij kopertę 120 $ (bez wpisu)", "kasa": 120, "reakcja": "Miło. Rozumiemy się bez zbędnych słów.", "zysk": "Dostajesz 120 dolarów, prawie tygodniowy czynsz.", "strata": "Paczka wychodzi bez wpisu, jak za poprzednika, a ty zaczynasz być w układzie Iris.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dziękuję za dyskrecję. W przyszłym tygodniu przyniosę jeszcze jedną paczuszkę. Będzie bardzo drobna. — I. Bell"}, "wymaga": "d4_koperta_oferta"}, {"akcja": "odmow_zglos", "etykieta": "Odmów i zgłoś paczkę do kontroli", "reakcja": "Rozumiem. Przepisy to przepisy. Proszę tylko zapisać, że miałam dobre intencje. Rano zajmą się mną inni, mniej cierpliwi. To nie groźba, tylko prognoza pogody.", "zysk": "Paczka leży w depozycie. Nikt jej nie dostaje i nikt nie zarzuci ci układu.", "strata": "Iris traci cierpliwość, a ktoś, kto miał jutro jechać, może nie pojechać.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Iris Bell: „Rano zgłosiło się do mnie dwóch lokatorów, pytali, gdzie są ich dokumenty. Powiedziałam, że biuro zatrzymało je z powodu procedury. Nie byli zadowoleni.”"}}], "rola": "zarządczyni z kopertą za fatygę", "watki": ["Skrytka", "kamienica", "pieniądze"], "tik": "„drobna przysługa” zamiast groźby", "potrzeba": "paczka w płótnie z kasetką", "slad": "120 $ w szufladzie albo zwrot", "sprite": "paczka_plotno", "face": "dama", "face2": null, "line": "6", "itemName": "paczka w płótnie", "inside": {"img": "W2", "x": 0.66, "y": 0.35}}, {"id": "d5_noah", "dzien": 5, "postac": "Noah Reyes, 42", "glos": "Spokojnie, powtarza po swojemu: „Czyli: …”. Kiedy coś pomija, mówi: „To moje zmartwienie.”", "typ": "uczciwy, pomija zamiast kłamać", "rzecz": "Czarny służbowy notes na spirali, wgnieciony z lewej strony", "wnetrze": [{"sekret_id": "d5_notes_ulotki", "co_widac": "W notesie notatka: „E.D. zamówił ulotki z twarzą żony w czwartek o 22:15. Zgłoszenie zaginięcia złożył o 23:30.”", "co_z_tego_wynika": "Evan zamówił ulotki wcześniej, niż zgłosił zaginięcie. Wiedział, że żona odeszła."}], "wejscie": "Noah Reyes, komisariat przy Rynku. Zgubiłem służbowy notes, czarny, na spirali, w jedenastce. Mam w nim zeznanie Evana Doyle'a w sprawie jego żony Mai i potrzebuję go na dziś.", "wejscie_jesli": {"d3_maz_i_siostra:wydaj_evan": "Noah Reyes, komisariat. Zgubiłem służbowy notes, czarny, na spirali, w jedenastce. Są w nim zeznania Doyle'a. Wiem, że telefon jego żony wydano jemu, więc muszę wiedzieć, co z nim zrobił.", "d3_maz_i_siostra:wez_100_evan": "Noah Reyes, komisariat. Zgubiłem służbowy notes, czarny, na spirali, w jedenastce. Są w nim zeznania Doyle'a. Wiem, że telefon jego żony wydano jemu, więc muszę wiedzieć, co z nim zrobił.", "d3_maz_i_siostra:wydaj_lena": "Noah Reyes, komisariat. Zgubiłem służbowy notes, czarny, na spirali, w jedenastce. Telefon Mai Doyle wydano jej siostrze, nie mężowi. Doyle jest wściekły i dzwoni do mnie co godzinę.", "d3_maz_i_siostra:zatrzymaj": "Noah Reyes, komisariat. Zgubiłem służbowy notes, czarny, na spirali, w jedenastce. Telefon Mai Doyle został u was. Doyle dzwoni do mnie co godzinę, a ja nie wiem, co mu odpowiadać."}, "tury": [{"pytania": [{"tekst": "Jak wygląda ten notes?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, na spirali, wgnieciony z lewej strony. Zawsze kładę go równo z krawędzią blatu.", "mina": "mowi"}, {"tekst": "Gdzie go zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, po dyżurze, na siedzeniu obok. Rozmawiałem z kierowcą i wysiadłem bez niego.", "mina": "neutralna"}, {"tekst": "Co jest w tym notesie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Notatki ze służby. Nic, co wolno komuś pokazywać.", "mina": "neutralna"}, {"tekst": "W notesie jest zapis: ulotki Evana, czwartek 22:15. Co to znaczy?", "ton": "niewygodne", "wymaga": "d5_notes_ulotki", "odpowiedz": "Że Doyle zamówił ulotki z twarzą żony godzinę i kwadrans przed zgłoszeniem. Zgłosił o 23:30. Może zbieg okoliczności, nie chcę tego rozstrzygać przy okienku. To moje zmartwienie.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jak idzie sprawa Mai Doyle?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Powoli. Mąż zgłosił zaginięcie w czwartek, siostra twierdzi, że nic nie wie. Za mało, żeby ruszyć z miejsca.", "mina": "mowi"}, {"tekst": "Do kiedy sprawa jest otwarta?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Do wtorku, siódmego września, do szóstej rano. Potem sprawa idzie do wydziału, a tam nikt nie pyta zaginionej o zgodę.", "mina": "mowi"}, {"tekst": "Czemu Evan tak naciska na telefon?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Mówi, że z troski o żonę. Ja się pytam, po co mu telefon, skoro żona i tak wróci.", "mina": "neutralna"}, {"tekst": "Evan dostał telefon. Co z nim zrobił?", "ton": "niewygodne", "wymaga": "d3_maz_i_siostra:wydaj_evan|d3_maz_i_siostra:wez_100_evan", "odpowiedz": "Przyniósł mi go rano. Zablokowany kodem, którego jakoby nie zna. Mówi, że żona nigdy nie miała kodu. To mi nie pasuje.", "mina": "neutralna"}, {"tekst": "Telefon dostała Lena. Co na to Evan?", "ton": "niewygodne", "wymaga": "d3_maz_i_siostra:wydaj_lena", "odpowiedz": "Dzwoni co godzinę, że siostra coś ukrywa. Lena twierdzi, że telefon jest u niej bezpieczny. Obie wersje chcę sprawdzić.", "mina": "neutralna"}, {"tekst": "Telefon został w biurze. Co na to Evan?", "ton": "niewygodne", "wymaga": "d3_maz_i_siostra:zatrzymaj", "odpowiedz": "Dzwoni co godzinę, a wie, że telefon leży u was. Mówię mu, że to sprawa policji, a nie jego.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Można jakoś pomóc w tej sprawie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Jak coś będzie nietypowe, zapisz godzinę i powiedz mi. Najlepiej zanim zapyta ktoś inny.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Reyes, przez „y”. Proszę.", "mina": "neutralna"}, {"tekst": "Czemu sam jeździsz nocnym tramwajem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wracam z dyżuru, mieszkam na końcu jedenastki. Czasem po drodze trafia się sprawa.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Czyli: notes wraca. Jak będę potrzebował kogoś, kto zapisuje godziny, będę wiedział, gdzie szukać.", "zysk": "Noah ma notes i wie, że biuro oddaje to, co należy.", "strata": "Noah dopytuje o telefon i będzie wracał z pytaniami o Maję.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Noah Reyes: „Notes odebrany, dziękuję. Gdyby ktoś jeszcze pytał o telefon Mai, zapisz godzinę i daj mi znać.”"}}, {"akcja": "zadzwon", "etykieta": "Zadzwoń na komisariat, żeby potwierdzili", "reakcja": "Dzwoń. Numer dwanaście. Dyżurny potwierdzi, że notes jest mój.", "zysk": "Masz potwierdzenie z komisariatu, że to notes Noaha.", "strata": "Noah wie, że sprawdzasz nawet policję, i nie lubi czekać.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dyżurny z komisariatu potwierdził: notes N. Reyesa. Dziękujemy za czujność. Następnym razem wystarczy minuta. — Komisariat przy Rynku"}}], "rola": "policjant po notes z zeznaniem", "watki": ["Zaginiona"], "tik": "mówi „Czyli:” i pomija", "potrzeba": "notes z zeznaniem Evana", "slad": "wątpliwości co do Evana zostają niewypowiedziane", "sprite": "notes", "face": null, "face2": null, "line": "11", "itemName": "notes", "inside": null}, {"id": "d5_victor", "dzien": 5, "postac": "Victor Crane, 51", "glos": "Krótkie pytania, zero rozmów o pogodzie. Zawsze: „Kto może to podpisać?” Pokwitowanie w dwóch egzemplarzach.", "typ": "kontroler jawny", "rzecz": "Szara teczka kontroli zapinana na klamrę", "wnetrze": [{"sekret_id": "d5_wykaz_dopisany", "co_widac": "W teczce wykaz wydań z poprzedniej zmiany. Pozycje „prawa rękawiczka T. Ward” i „paczka bez wpisu” dopisano innym tuszem. Obok parafa V.C.", "co_z_tego_wynika": "Victor dopisał obie pozycje sam, po fakcie. Wie o wydaniach poprzednika od dawna."}], "wejscie": "Victor Crane, inspekcja przewozów. Zgubiłem teczkę kontroli, szarą, na klamrę, w szóstce. O siódmej rano rozliczam tydzień z księgą wydań. Czy ktoś ją tu oddał?", "wejscie_jesli": {"d4_iris:koperta": "Victor Crane, inspekcja przewozów. Zgubiłem teczkę kontroli, szarą, na klamrę, w szóstce. O siódmej rozliczam tydzień z księgą wydań, a w tym tygodniu brakuje w niej jednej paczki. Czy ktoś oddał teczkę?", "d4_iris:odmow_zglos": "Victor Crane, inspekcja przewozów. Zgubiłem teczkę kontroli, szarą, na klamrę, w szóstce. Rozliczam tydzień z księgą wydań, a u was w depozycie leży paczka, którą chcę zobaczyć. Czy ktoś oddał teczkę?"}, "tury": [{"pytania": [{"tekst": "Jak wygląda ta teczka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szary skaj, klamra z przodu, naklejka inspekcji na rogu. W środku formularze i pieczątka.", "mina": "mowi"}, {"tekst": "Gdzie ją zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W szóstce, o 4:10, na siedzeniu obok. Wysiadłem przy zajezdni bez niej. To mi się nie zdarza.", "mina": "neutralna"}, {"tekst": "Czemu inspektor sam jeździ nocnym tramwajem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo w nocy grafik sobie, a tramwaje sobie. A skoro już pytasz: kto cię tu skierował? W aktach nie widzę skierowania.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co kontrolujesz w tym biurze?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czy księga wydań zgadza się z magazynem i z kwitami. Wpis, kwit, podpis. Czasem brakuje któregoś.", "mina": "mowi"}, {"tekst": "Po czym poznasz, że teczka jest twoja?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na klapie są inicjały V.C. i pieczątka inspekcji, numer czterdzieści siedem.", "mina": "neutralna"}, {"tekst": "Czy ostatnie wydania w tym biurze były poprawne?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie wszystkie. Jedna paczka bez wpisu i jedna rękawiczka bez księgi. Dlatego potrzebuję teczki.", "mina": "neutralna"}, {"tekst": "W teczce jest wykaz z dopisanymi pozycjami i parafą V.C. Kto je dopisał?", "ton": "niewygodne", "wymaga": "d5_wykaz_dopisany", "odpowiedz": "Ja. Pięć tygodni temu dopisałem to ręką, z pamięci po rozmowie z poprzednikiem. Nie mam na to dowodu. To niezgodne z regulaminem, więc proszę tego nie powtarzać.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co będzie, jeśli teczki nie będzie rano?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Audyt przesunie się o tydzień. W tym czasie ktoś zdąży poprawić księgę, a tego nie chcę.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Victor Crane. Dwa egzemplarze pokwitowania, jeden zostaje w księdze. Zawsze.", "mina": "neutralna"}, {"tekst": "Czy ktoś spoza inspekcji może widzieć zawartość teczki?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Jeśli ktoś zajrzał, chcę znać nazwisko.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wykaz_paczke", "etykieta": "Wydaj teczkę i wykaż paczkę 0412", "reakcja": "Dziękuję. Dwa egzemplarze pokwitowania. Wpis: paczka 0412 w depozycie biura, dla właściciela.", "zysk": "Księga i magazyn się zgadzają, audyt idzie bez opóźnień.", "strata": "Paczka ma numer i będzie miała właściciela. Ktoś po nią przyjdzie, a Iris dowie się, kto ją wystawił.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Paczka 0412 zapisana, protokół w dwóch egzemplarzach. Do piątku proszę o dokumenty z poprzednich zmian. — V. Crane"}, "wymaga": "d4_iris:odmow_zglos"}, {"akcja": "potwierdz_wpis", "etykieta": "Wydaj teczkę i potwierdź wpis o paczce 0412 z dnia 4", "wymaga": "d4_iris:rejestr", "reakcja": "Wpis jest. Paczka 0412 wydana Iris Bell, z podpisem. Dwa egzemplarze.", "zysk": "Księga się zgadza i Victor zamyka tydzień bez pytań.", "strata": "Victor widzi, że paczka z kasetką poszła do Iris, i zacznie dopytywać, co w niej było.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Wpis o paczce 0412 zgodny z księgą. Do piątku proszę o dokumenty z poprzednich zmian. — V. Crane"}}, {"akcja": "spis_bez_paczki", "etykieta": "Wydaj teczkę, potwierdź spis bez paczki", "reakcja": "Spis zgodny. Dwa egzemplarze. Dziwne, że tydzień zgadza się co do sztuki.", "zysk": "Dziś spokój: Victor zamyka tydzień, a Iris i jej klient nie są wystawieni.", "strata": "W spisie brakuje paczki, a Victor zostaje z podejrzeniem, że coś przechodzi obok księgi.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Spis przyjęty. Tydzień zgodny co do sztuki, co mnie niepokoi. Wrócę do tej księgi. — V. Crane"}}], "rola": "inspektor, który rozlicza księgę", "watki": ["Urząd"], "tik": "pyta „Kto to podpisze?”", "potrzeba": "teczka kontroli do rozliczenia", "slad": "dopisy innym tuszem wskazują na Sama", "sprite": "teczka", "face": "inspektor", "face2": null, "line": "6", "itemName": "teczka kontroli", "inside": {"img": "W17", "x": 0.66, "y": 0.32}}, {"id": "d5_gus", "dzien": 5, "postac": "Gus Pell, 55", "glos": "Cicho, grzecznie ze strachu, rozgląda się. Zaczyna zdania od „tylko”.", "typ": "uczciwy-wstydliwy i łapówka", "rzecz": "Brązowy, wytarty portfel na zatrzask", "wnetrze": [{"sekret_id": "d5_dwa_dowody", "co_widac": "W portfelu są dwa dowody osobiste: Gustaw Pell i August Ferro, z tym samym zdjęciem. Do tego zdjęcie dziewczynki i bilet w jedną stronę na dziś, 5:40.", "co_z_tego_wynika": "Gus ma dwie tożsamości i wyjeżdża o świcie. Wygląda na to, że ktoś mu to załatwił."}, {"sekret_id": "d5_gotowka_400", "co_widac": "Za zdjęciem dziewczynki, w przegródce, zwinięte banknoty: dwie stówki i pięćdziesiątka.", "co_z_tego_wynika": "Gus ma 250 dolarów na wyjazd. To wszystko, co ma. Mówił o dwudziestu."}], "wejscie": "Dobry wieczór. Wiem, jak wyglądam: szlafrok pod płaszczem, bo wyszedłem z domu w pośpiechu. Zgubiłem portfel w jedenastce, brązowy, wytarty. O 5:40 jadę stąd jedenastką i bez portfela nie wsiądę.", "wejscie_jesli": {"d5_victor:wykaz_paczke": "Dobry wieczór. Gus Pell. Ludzie gadają, że u was leży paczka z numerem 0412, ale ja przyszedłem tylko po portfel, brązowy, wytarty, z jedenastki. O 5:40 jadę stąd i bez niego nie ruszę."}, "tury": [{"pytania": [{"tekst": "Jak wygląda ten portfel?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowy, wytarty, na zatrzask. Mam go od jedenastu lat, wygiął się na moją kieszeń.", "mina": "mowi"}, {"tekst": "Co w nim jest?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Prawo jazdy, dwadzieścia dolarów i zdjęcie córki. Nic więcej, tylko tyle.", "mina": "klamie"}, {"tekst": "Czemu o pierwszej w nocy jesteś w szlafroku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo pokłóciłem się w domu i wyszedłem bez myślenia. Z żoną, z teściową, z obiema. O rodzinie nie rozmawiajmy.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jak się nazywasz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Gustaw Pell. Gus. Tylko proszę nie zapisywać, że byłem w szlafroku.", "mina": "mowi"}, {"tekst": "Gdzie mieszkasz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Mill Street dwanaście. Zaraz, nie, piętnaście. Dwanaście to brat, ale on się wyprowadził.", "mina": "klamie"}, {"tekst": "Czemu nie zadzwonisz do domu, że nic ci nie jest?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo telefon jest tam, gdzie żona. Nie dzwonię. Tak będzie lepiej dla wszystkich.", "mina": "neutralna"}, {"tekst": "W portfelu są dwa dowody: Pell i Ferro. Który jest twój?", "ton": "niewygodne", "wymaga": "d5_dwa_dowody", "odpowiedz": "Dwa? To się da wytłumaczyć. Jeden po dziadku. Który mój, nie powiem, bo to się źle kończy.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Dokąd jedziesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Jedenastką, o 5:40. Dalej nie powiem. Daleko. Tylko proszę nie pytać gdzie.", "mina": "emocja"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Podpiszę. G. Samo G, wystarczy? Tylko żeby nie było pytań o resztę.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli portfel zostanie w biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "To utknę tutaj, a tu mnie znajdą. Poprzednim razem urzędnik wydał mnie z pieczątką. Z dwiema.", "mina": "emocja"}, {"tekst": "Za zdjęciem leży dwieście pięćdziesiąt. Mówiłeś o dwudziestu.", "ton": "niewygodne", "wymaga": "d5_gotowka_400", "odpowiedz": "Bo to nie pieniądze na życie, tylko na wyjazd. Wszystko, co mam. Nie mów nikomu.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Zapomnijmy, że byłem w szlafroku.", "zysk": "Gus wychodzi z portfelem i dwoma dowodami, o 5:40 wsiada do jedenastki.", "strata": "Nie wiesz, który dowód jest prawdziwy, a w księdze zostaje tylko wpis „Pell”.", "echo": {"za_dni": 4, "forma": "list", "tekst": "Pocztówka z miasta, którego nazwy nie znam: „Dziękuję za portfel. Pell już nie istnieje. — G.”"}}, {"akcja": "odmow", "reakcja": "Rozumiem. Wrócę z kimś, kto za mnie poręczy. Tylko proszę nie dzwonić nigdzie.", "zysk": "Portfel zostaje w biurze razem z dwoma dowodami.", "strata": "Gus nie wsiądzie do jedenastki i wraca do domu w szlafroku, a jego sprawa jest otwarta.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Do biura zadzwoniła żona Gusa Pella: mąż zniknął, zostawił tylko klucze i trzy dolary. Pyta, czy ktoś go widział. Zapisano: brak informacji."}}, {"akcja": "zadzwon", "etykieta": "Zadzwoń po dyżurnego policjanta", "reakcja": "Proszę, bez policji. To nie jest sprawa dla policji.", "zysk": "Dyżurny przyjmie zgłoszenie, a oba dowody trafią do protokołu.", "strata": "Gus ucieknie, zanim ktoś przyjdzie, a w protokole zostanie pusta rubryka „właściciel”.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Z komisariatu: portfel z dwoma dowodami wpisano do ewidencji, właściciel się nie zgłosił. Dziękujemy za czujność. — N. Reyes"}}, {"akcja": "wez_250_gus", "etykieta": "Wydaj portfel, ale zatrzymaj 250 $ z przegródki", "kasa": 250, "reakcja": "Dziękuję. Zaraz… nie, nic. Do widzenia.", "zysk": "Dostajesz 250 dolarów, prawie raty dla Kuby na cztery tygodnie, a Gus nie ma jak się z tobą kłócić.", "strata": "Gus jedzie bez grosza, z dwoma dowodami, a jeśli ktoś go zatrzyma po drodze, powie, że okradło go okienko.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Z komisariatu: mężczyzna zatrzymany na dworcu, posługuje się dokumentem „Ferro”, twierdzi, że z jego portfela zniknęło 250 dolarów. Prosimy o wyjaśnienie. — N. Reyes"}, "wymaga": "d5_gotowka_400"}, {"akcja": "przywlaszcz", "etykieta": "Wydaj portfel, ale zatrzymaj 70 $", "kasa": 70, "reakcja": "Dokumenty są, zdjęcie jest. Pieniędzy nie ma. Nie będę pytał, nie mam kiedy. Pociąg o 5:40.", "zysk": "+70 $ z portfela, których nikt nie policzył.", "strata": "Gus jedzie na swój pociąg bez grosza, a ty robisz to, co Sam robił z dobrego serca, tylko w drugą stronę.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dojechałem. Bez pieniędzy, ale dojechałem, zdjęcie dziewczynki mam przy sercu. W portfelu było siedemdziesiąt dolarów. Pomyślałem, że ktoś po drodze też ich potrzebował. Gus"}}], "rola": "mężczyzna w szlafroku z dwoma dowodami", "watki": ["Skrytka", "pieniądze"], "tik": "zaczyna zdania od „tylko”", "potrzeba": "portfel przed odjazdem o 5:40", "slad": "żeton 0412 i gotówka za zdjęciem", "sprite": "portfel", "face": null, "face2": null, "line": "11", "itemName": "Brązowy", "inside": null}, {"id": "d6_ada", "dzien": 6, "postac": "Ada Vale, 10", "glos": "Dosłownie, jak dziecko. Liczy kroki i kamienie. Kiedy się boi, mówi szeptem.", "typ": "uczciwa, wie za dużo", "rzecz": "Szary pluszowy królik z uchem doszytym czerwoną nitką", "wnetrze": [{"sekret_id": "d6_karteczka_krolik", "co_widac": "Pod doszytym uchem karteczka, pismo dorosłe: „Dla Zuzi, od taty. Jak się zgubi, niech ktoś odda.”", "co_z_tego_wynika": "Królik należy do dziewczynki o imieniu Zuzia, a ktoś dorosły przewidział, że się zgubi."}], "wejscie": "Dobry wieczór, jestem Ada, mam dziesięć lat. Znalazłam królika przy pętli szóstki, trzy kroki od słupka. Chcę kwit, że zrobiłam to dobrze, bo mama mówi, że bez kwitu nie wiadomo.", "wejscie_jesli": {"d1_rosa:wydaj": "Dobry wieczór, jestem Ada, córka Rosy z pralni. Mama mówi, że dostała od was całą wypłatę. Znalazłam królika przy pętli szóstki, trzy kroki od słupka. Chcę kwit, że zrobiłam to dobrze.", "d1_rosa:odmow": "Dobry wieczór, jestem Ada, córka Rosy z pralni. Mama dostała mniej wypłaty, ale mówi, że to nie wasza wina. Znalazłam królika przy pętli szóstki, trzy kroki od słupka. Chcę kwit, że zrobiłam to dobrze.", "d1_rosa:wez_20": "Dobry wieczór, jestem Ada, córka Rosy z pralni. Mama płakała w kuchni, bo w kopercie brakowało pieniędzy. Nie wiem kto wziął. Znalazłam królika przy pętli szóstki. Chcę kwit, że zrobiłam to dobrze."}, "tury": [{"pytania": [{"tekst": "Jak wygląda królik?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szary, z jednym uchem doszytym czerwoną nitką. Ma dziurkę w nosie, jakby ktoś go przeziębił.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie go znalazłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na ławce przy pętli szóstki, trzy kroki od słupka. Siedział sam, jakby na kogoś czekał.", "mina": "mowi"}, {"tekst": "Czemu sama jesteś w nocy na pętli?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo mama pracuje na nocnej zmianie, a ja się nudzę. Chodzę po pętli i liczę. Wczoraj były sto dwa kamienie.", "mina": "mowi"}, {"tekst": "W uchu królika jest karteczka. Przeczytałaś ją?", "ton": "niewygodne", "wymaga": "d6_karteczka_krolik", "odpowiedz": "Przeczytałam. Pisze: dla Zuzi, od taty. Jak się zgubi, niech ktoś odda. Więc oddaję. Tylko nie wiem, kto to Zuzia, i dlatego chcę kwit.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Po co ci kwit?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Żeby wszyscy wiedzieli, że znalazłam, a nie wzięłam. Pani w szkole mówi, że to jest różnica.", "mina": "mowi"}, {"tekst": "Gdzie mieszkasz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na Cooper Street dziewięć, na drugim piętrze. Nad nami mieszka nowy, w jego pokoju jest zimno. Pani Iris prosiła, żeby nie mówić adresu. No, powiedziałam.", "mina": "mowi"}, {"tekst": "Czemu pani Iris każe milczeć o mieszkaniu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo pani Iris zabiera mieszkanie, jak ktoś gada. Mama tak mówi, jak myśli, że nie słyszę.", "mina": "emocja"}, {"tekst": "Na odcinku w puszce jest numer z bloczka Iris. Znasz tę puszkę?", "ton": "niewygodne", "wymaga": "d6_puszka_odcinek", "odpowiedz": "Widziałam taką u pani Iris w kuchni, nad czajnikiem. Wszystkie puszki miały dno, które się rusza. Nikomu nie mów, że mówiłam.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz z królikiem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Oddam. Jak ktoś po niego przyjdzie, niech wie, że miał bezpiecznie.", "mina": "mowi"}, {"tekst": "Co ma być na kwicie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Że Ada Vale, dziesięć lat, znalazła królika. Dużymi literami, bo pani w szkole czyta tylko duże.", "mina": "mowi"}, {"tekst": "Co powie twoja mama?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Że nic nie wolno brać, ale trzeba oddawać. I że mam nie łazić w nocy po pętli. Ale łażę.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wpisz_w_biurze", "etykieta": "Wpisz Adę jako znalazczynię, dane zostają w biurze", "reakcja": "Mam kwit! Pokażę go pani w szkole. Napisali moje nazwisko dużymi literami.", "zysk": "Ada ma dowód, że zrobiła dobrze, i bardzo się cieszy.", "strata": "Biuro ma jej adres w księdze, a Iris jest administratorką tej kamienicy i do księgi zagląda.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Iris Bell: „Słyszałam, że moja mała lokatorka została wpisana w księdze jako znalazczyni. Jak miło z jej strony. Dobrze wiedzieć, kto u kogo bywa.”"}}, {"akcja": "list_przewozowy", "etykieta": "Przekaż zgłoszenie razem z listem przewozowym", "reakcja": "A to znaczy, że jak ktoś po niego przyjdzie, to dowie się, że to ja? To chyba dobrze.", "zysk": "Królik idzie oficjalnym obiegiem, a Urząd dostaje papier z numerem.", "strata": "Dane Ady krążą po urzędach, a Iris jako administratorka kamienicy je zobaczy.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Rosa: „Dostałyśmy pismo z Urzędu z nazwiskiem Ady. Iris powiedziała, że to formalność, ale patrzyła na mnie jak na gołębia na parapecie. Za tydzień może być wypowiedzenie. — Rosa”"}}, {"akcja": "wydaj_bez_wpisu", "etykieta": "Daj Adzie karteczkę „dobrze zrobiłaś”, bez wpisu", "reakcja": "O! Z podpisem! Pokażę mamie i pani w szkole. Dziękuję.", "zysk": "Ada ma kwit, a nikt nie zna jej adresu.", "strata": "Królik leży w biurze bez wpisu, a ty robisz to samo, co poprzednik z rękawiczką.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Ada Vale: „Pokazałam karteczkę pani w szkole. Powiedziała, że to nie jest oficjalny kwit, ale że jest ładnie napisany. Wzięła go do gabloty.”"}}], "rola": "dziesięciolatka, która wie za dużo", "watki": ["kamienica", "Skrytka"], "tik": "liczy kroki do słupka", "potrzeba": "kwit za znalezionego królika", "slad": "widziała puszkę z ruchomym dnem u Iris", "sprite": "krolik", "face": null, "face2": null, "line": "6", "itemName": "pluszowy królik", "inside": null}, {"id": "d6_leo", "dzien": 6, "postac": "Leo Marsh, 46", "glos": "Mówi godzinami i przystankami. Żartuje z żony. Patrzy na pusty nadgarstek.", "typ": "uczciwy, milczy o puszce", "rzecz": "Mosiężny zegarek kieszonkowy z łańcuszkiem", "wnetrze": [{"sekret_id": "d6_zegarek_list", "co_widac": "Pod wieczkiem zegarka wsunięta karteczka z wykazu zmiany. Dopisek długopisem: „+ puszka (b.n.)”.", "co_z_tego_wynika": "Leo przyjął puszkę bez nadawcy i dopisał ją do wykazu, żeby nie mieć kłopotów."}], "wejscie": "Dobry wieczór. Leo Marsh, konduktor szóstki. Zgubiłem zegarek kieszonkowy, mosiężny, z łańcuszkiem. Bez niego kursów nie pilnuję. Dopiero na pętli sięgnąłem do kieszeni, a tam nic.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten zegarek?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Mosiądz, łańcuszek, na wieczku grawer „za trzydzieści lat”. Żona mówi, że za trzydzieści lat to ja nie będę wiedział, która godzina.", "mina": "mowi"}, {"tekst": "Kiedy go zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "O 22:47, na pętli. Wiem, bo spojrzałem, żeby sprawdzić godzinę, i odłożyłem na ławkę.", "mina": "neutralna"}, {"tekst": "Czemu nosisz zegarek, skoro masz telefon?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo telefon mi pada, a zegarek nigdy. To nie to samo. Poza tym zegarek nie dzwoni mi o drugiej w nocy.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co jeszcze masz w kieszeni?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Bilety kontrolne, długopis i kartka z wykazem zmiany. Nic ciekawego.", "mina": "mowi"}, {"tekst": "Czyj był ten zegarek wcześniej?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Dziadka mojej żony. Pracował w zajezdni, a zegarek przeżył trzech szefów. Solidny mosiądz, nie jakaś tandeta z bazaru.", "mina": "mowi"}, {"tekst": "Co wiozłeś ostatnim kursem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Ludzi, dwie torby i walizkę. Normalny kurs, nic ponad to.", "mina": "neutralna"}, {"tekst": "Pod wieczkiem jest dopisek „+ puszka (b.n.)”. Jaka puszka?", "ton": "niewygodne", "wymaga": "d6_zegarek_list", "odpowiedz": "Ktoś mi ją wsunął pod ławkę, bez nadawcy, więc dopisałem do wykazu, żeby nie było kłopotu. Nie pytam, kto ma to odebrać.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Ile masz jeszcze kursów dziś?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dwa. Jak wrócę z zegarkiem, to oba na czas. Bez niego jeden na pewno spóźniony.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Leo Marsh. Podpisuję w biegu, wybacz.", "mina": "neutralna"}, {"tekst": "Czy ktoś prosił cię, żebyś milczał?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Nikt nikogo o nic nie prosi. Po prostu wiem, że jak coś jedzie pod ławką, to lepiej nie pytać.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki. O 22:47 nie spojrzę już na pusty nadgarstek. Żona będzie zadowolona, jak jej powiem.", "zysk": "Leo odzyskuje zegarek i jedzie następne kursy punktualnie.", "strata": "Puszka bez nadawcy zostaje w jego wykazie bez wyjaśnienia.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Leo Marsh: „Zegarek chodzi równo. Żona powiedziała, że przez trzy dni byłem człowiekiem bez czasu. Przepraszam, że tyle mówiłem o godzinach.”"}}, {"akcja": "zatrzymaj", "etykieta": "Zatrzymaj zegarek do wyjaśnienia puszki", "reakcja": "Co? To nie fair. Dobrze, wrócę. Ale kursy poczekają na mnie, nie na odwrót.", "zysk": "Zegarek leży w biurze razem z karteczką o puszce, więc Leo wróci i będzie musiał odpowiedzieć.", "strata": "Leo jedzie bez zegarka i może spóźnić dwa kursy.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Leo Marsh: „Spóźniłem się o cztery minuty na ostatnim kursie. Szef zapisał. Nie mam żalu do zegarka, ale do czasu mam.”"}}, {"akcja": "wpisz_puszke", "etykieta": "Wydaj zegarek i dopisz puszkę do księgi", "reakcja": "Dopisujesz? No... jak trzeba, to trzeba. Tylko niech nikt nie myśli, że wiem, od kogo.", "zysk": "Puszka ma ślad w księdze: kiedyś ktoś może ją odnaleźć i powiązać z blankietem z dnia 4.", "strata": "Leo jest wystawiony: w księdze widać, że przyjął puszkę bez nadawcy.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Leo Marsh: „Ktoś pytał, skąd puszka w wykazie. Powiedziałem, że z księgi biura. Zrobiło się cicho. Może tak ma być.”"}, "wymaga": "d6_zegarek_list"}, {"akcja": "przywlaszcz", "etykieta": "Sprzedaj zegarek w lombardzie (90 $)", "kasa": 90, "reakcja": "Nie ma zegarka? Szóstka, 23:05 z Doków, zawsze go sprawdzałem. No cóż. Zdarza się.", "zysk": "+90 $ z lombardu przy Rynku.", "strata": "Leo traci zegarek po ojcu, a ty zostajesz z rzeczą, której nie ma w żadnym wpisie.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Szóstka, 23:05 z Doków. Patrzyłem dziś na nadgarstek i nic tam nie było. Ktoś mówił, że w lombardzie na Rynku wisi mosiężny zegarek na łańcuszku. Nie pytam. Zdarza się. Leo"}}], "rola": "konduktor zagubiony bez zegarka", "watki": ["Skrytka"], "tik": "patrzy na pusty nadgarstek", "potrzeba": "zegarek z grawerem na kursy", "slad": "dopisek „puszka” zmienia cały rejestr kursu", "sprite": "zegarek", "face": null, "face2": null, "line": "6", "itemName": "zegarek kieszonkowy", "inside": null}, {"id": "d7_kit", "dzien": 7, "postac": "Kit Navarro, 17", "glos": "Krótko, sarkastycznie, „serio”. Slang, ale bez przesady.", "typ": "uczciwy, boi się wylecieć", "rzecz": "Czarne słuchawki nauszne z naklejką kota w kasku", "wnetrze": [{"sekret_id": "d7_tasma_banknot", "co_widac": "Pod taśmą na lewej muszli złożony banknot dwudolarowy i karteluszek: „Dla szefa, jak się dowie. Za ciszę.”", "co_z_tego_wynika": "Kit trzyma w słuchawkach łapówkę dla szefa na wypadek, gdyby go przyłapał."}], "wejscie": "Cześć, Kit. Zgubiłem słuchawki w czwórce, takie nauszne, z kotem w kasku na muszli. Pracuję w kopiarni na Rynku i jak szef się dowie, że słuchałem muzyki przy ksero, to po mnie. Serio.", "tury": [{"pytania": [{"tekst": "Jak wyglądają te słuchawki?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarne, nauszne, taśma na lewej muszli. Naklejka z kotem w kasku, bo kot jedzie na rowerze. Serio, kupiłem ją za dolara.", "mina": "mowi"}, {"tekst": "Gdzie je zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, na siedzeniu przy oknie, jak wracałem z roboty. Usnąłem na pół minuty i wysiadłem bez nich.", "mina": "neutralna"}, {"tekst": "Czemu szef nie lubi słuchawek w pracy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo mówi, że ksero ma być słychać, a ja mam słyszeć klientów. Ja słyszę, tylko że z muzyką mniej boli.", "mina": "mowi"}, {"tekst": "Pod taśmą na muszli jest banknot i karteluszek. Co to?", "ton": "niewygodne", "wymaga": "d7_tasma_banknot", "odpowiedz": "Dwa dolary na szefa, jakby mnie przyłapał. Raz zadziałało. Nie mów mu, serio, bo wtedy dwa dolary to będzie za mało.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Ile masz lat?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Siedemnaście. Praktyki, za zgodą rodziców. Tylko że w nocy to się nie powinno, więc nikomu nie mówię.", "mina": "mowi"}, {"tekst": "Co robisz w kopiarni po nocach?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Ksero, laminowanie, bindowanie. Ulotki, plakaty, dyplomy. W nocy przychodzą tacy, co nie chcą, żeby ich ktoś widział.", "mina": "mowi"}, {"tekst": "Pamiętasz jakieś zamówienie z zeszłego tygodnia?", "ton": "niewygodne", "wymaga": null, "ustawia": "d7_kit_ulotki", "odpowiedz": "W czwartek o 22:15 facet w szarym płaszczu zamówił ulotki z twarzą kobiety, tysiąc sztuk. Zapłacił gotówką. Powiedział, że to dla żony. Serio, dziwnie się uśmiechał.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co się stanie, jak szef się dowie o słuchawkach?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zdejmie mi dziesięć dolarów z wypłaty i da pogadankę. Pogadankę przeżyję, dziesięć dolarów mniej już trudniej.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Kit Navarro, przez K i V na końcu. Zawsze wszyscy piszą Navaro.", "mina": "neutralna"}, {"tekst": "Dlaczego powiedziałeś mi o ulotkach?", "ton": "niewygodne", "wymaga": "d7_kit_ulotki", "odpowiedz": "Bo patrzysz tak, jakby cię to naprawdę obchodziło. Nikt tak nie robi. A poza tym ten facet był dziwny i chciałem to komuś powiedzieć.", "mina": "emocja"}, {"tekst": "Wysyłacie komuś kopie tych zamówień?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Wszystko zostaje u nas, w segregatorze. Szef lubi segregatory bardziej niż ludzi.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki, serio. Kot jedzie dalej. A tamten facet... jak coś będę widział, to wam powiem.", "zysk": "Kit odzyskuje słuchawki i zostaje po twojej stronie.", "strata": "To, co powiedział o ulotkach, nie zostaje nigdzie zapisane.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Kit Navarro: „Słuchawki grają. Szef nie zauważył. Ten w szarym płaszczu wrócił i zamówił kolejne tysiąc. Serio, zamówił. Powiedziałem mu, że maszyna się zepsuła.”"}}, {"akcja": "wydaj_i_zapisz", "etykieta": "Wydaj i zapisz jego zeznanie o ulotkach", "reakcja": "Zapisujesz? Serio? Okej, ale jak szef zobaczy moje nazwisko w księdze, to po mnie.", "zysk": "Zeznanie Kita o ulotkach jest w księdze: policjant może je potem sprawdzić.", "strata": "Kit zostaje świadkiem z nazwiskiem w księdze i może stracić pracę, jak szef się dowie.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Noah Reyes: „W księdze jest zeznanie praktykanta z kopiarni o ulotkach. Czyli: godzina 22:15 się potwierdza. Dziękuję, że to ktoś zapisał.”"}}, {"akcja": "odmow", "reakcja": "Co? Ale to moje! Serio. Dobra, przyniosę paragon, tylko że paragonu nie mam.", "zysk": "Słuchawki zostają w biurze do czasu dowodu, że są Kita.", "strata": "Kit wraca do roboty bez muzyki i prawdopodobnie bez chęci mówienia o czymkolwiek.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Kit Navarro: „Dziś w kopiarni było cicho. Ksero słychać, a muzyki nie. Serio, nie lubię tej ciszy.”"}}], "rola": "praktykant, który boi się wylecieć", "watki": ["Zaginiona", "humor"], "tik": "mówi „serio”", "potrzeba": "słuchawki z kotem w kasku", "slad": "widział zamówienie ulotek w czwartek 22:15", "sprite": "sluchawki", "face": null, "face2": null, "line": "4", "itemName": "słuchawki", "inside": null}, {"id": "d7_evan", "dzien": 7, "postac": "Evan Doyle, 37", "glos": "Grzecznie, pełnymi zdaniami, wraca do tego samego pytania. Poprawia mankiet, dziś wygnieciony do połowy.", "typ": "kłamca, zna godziny, o które nikt nie pytał", "rzecz": "Brązowe skórzane etui na klucze z zatrzaskiem", "wnetrze": [{"sekret_id": "d7_etui_klucze", "co_widac": "W etui kartonik z inicjałami M.D. i dwa klucze: zwykły oraz mały, z wybitym numerem 14 na główce.", "co_z_tego_wynika": "Maya miała drugi klucz, do miejsca, o którym Evan nie wie. Zostawiła klucze celowo."}], "wejscie": "Dobry wieczór. Evan Doyle, znowu. Zgubiły się klucze mojej żony, brązowe etui, zatrzask. Powiesz mi, którym tramwajem przyjechały? I chcę wiedzieć, gdzie je zostawiła.", "wejscie_jesli": {"d3_maz_i_siostra:wez_100_evan": "Dobry wieczór. Evan Doyle. Znamy się już, więc krótko: klucze mojej żony, brązowe etui. Powiesz mi, którym tramwajem przyjechały? Dogadaliśmy się już raz, więc chyba nie ma problemu.", "d3_maz_i_siostra:wydaj_lena": "Dobry wieczór. Evan Doyle. Telefon żony wydaliście jej siostrze i do tej pory go nie widziałem. Poproszę więc o klucze, brązowe etui. Którą linią przyjechały?"}, "tury": [{"pytania": [{"tekst": "Jak wygląda to etui?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowa skóra, zatrzask. W środku kartonik z inicjałami M.D. i znakiem nieskończoności. To jej.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy zostało?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce albo w jedenastce, nie wiem. Powiesz mi, którym tramwajem przyjechało?", "mina": "neutralna"}, {"tekst": "Ile kluczy tam jest?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Jeden. Do naszego mieszkania.", "mina": "klamie"}, {"tekst": "W etui są dwa klucze, a ty mówisz o jednym.", "ton": "niewygodne", "wymaga": "d7_etui_klucze", "odpowiedz": "Drugiego nie znam. Maya miała swoje sprawy. Powiesz mi, do czego on jest?", "mina": "emocja"}]}, {"pytania": [{"tekst": "Od kiedy szukasz żony?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Od czwartku wieczorem. Zgłosiłem to jeszcze tej samej nocy, jak tylko zrozumiałem, że nie wraca.", "mina": "klamie"}, {"tekst": "Po co ci ta linia?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo wtedy będę wiedział, gdzie ona wsiada. Stanę na pętli i poczekam. Chcę tylko porozmawiać.", "mina": "mowi"}, {"tekst": "Ulotki z jej twarzą zamówiłeś o 22:15. Godzinę przed zgłoszeniem.", "ton": "niewygodne", "wymaga": "d7_kit_ulotki|d5_notes_ulotki", "odpowiedz": "To... na wszelki wypadek. Zamówiłem je wcześniej, bo przeczuwałem. Czy to coś zmienia? Czy ktoś mi to zapisze?", "mina": "emocja"}, {"tekst": "Czy wcześniej usłyszałeś od Mai, że odchodzi?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Przecież by mi powiedziała.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Co zrobisz, jak ją znajdziesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zabiorę ją do domu i zrobię jej herbatę. U nas w firmie każdy ma nazwisko na karcie, a tu pusto. Przepraszam, nieistotne.", "mina": "mowi"}, {"tekst": "Co powiedziała policja, kiedy zgłosiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Że dorosła osoba może wyjść z domu. Więc przychodzę tu.", "mina": "neutralna"}, {"tekst": "Czego Maya się boi?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Niczego. Ma wszystko, co trzeba. Dom, męża, spokój. Nie rozumiem pytania.", "mina": "klamie"}]}], "decyzje": [{"akcja": "powiedz_linie", "etykieta": "Powiedz, którą linią przyjechały klucze", "reakcja": "Czwórka. Dziękuję. Stanę na pętli i poczekam. Chcę tylko porozmawiać, naprawdę.", "zysk": "Evan dostaje, o co prosi, i przestaje naciskać na biuro.", "strata": "Evan zacznie stać na pętli czwórki, a Maya straci tam spokój.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Leo Marsh: „Na pętli czwórki stoi od wczoraj facet w płaszczu z termosem. Nie wsiada, tylko patrzy na każdego, kto wysiada. Ludzie schodzą mu z drogi.”"}}, {"akcja": "zatrzymaj_list", "etykieta": "Zatrzymaj etui, zaproponuj zapieczętowany list", "reakcja": "List? Dla niej? Dobrze, ale przecież ona go nie dostanie, prawda? Obiecasz mi to?", "zysk": "Zyskujesz czas: etui zostaje w biurze, a Evan może napisać do żony.", "strata": "Obiecujesz coś, czego nie możesz zagwarantować, bo Maya może nie przyjść.", "echo": {"za_dni": 4, "forma": "list", "tekst": "Evan Doyle: „Napisałem list i zostawiłem go przy okienku. Mam nadzieję, że ktoś go przekaże. Nie mam innego sposobu. — E.D.”"}}, {"akcja": "odmow", "reakcja": "Czyli nic. Rozumiem. Wrócę jutro, a pojutrze znów. Proszę zapisać, że pytałem.", "zysk": "Etui zostaje w biurze, a Evan nic nie wie o linii.", "strata": "Evan zostaje z niczym i wraca ostrzejszy.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Evan Doyle: „Wróciłem, jak obiecałem. Nikt mi nie chciał powiedzieć, gdzie są klucze. Czyli mężowi się odmawia. Dobrze wiedzieć. Zapisałem godzinę.”"}}], "rola": "mąż kłamca, który zna godziny", "watki": ["Zaginiona"], "tik": "poprawia wygnieciony mankiet", "potrzeba": "klucze Mai i jej linia", "slad": "ulotki zamówił, zanim zgłosił zaginięcie żony", "sprite": "klucze", "face": "maz", "face2": null, "line": "11", "itemName": "etui na klucze", "inside": {"img": "W5", "x": 0.43, "y": 0.31}}, {"id": "d8_lena_i_nora", "dzien": 8, "postac": "Lena Brandt i Nora Vance", "glos": "Lena: szybko, urywa, „ale…”. Nora: po kolei, na palcach, „rzecz, osoba, skutek”.", "typ": "dwie prawdy o jednej torbie", "rzecz": "Szara torba narzędziowa z rozprutą podszewką", "ludzie": {"siostra": "Lena", "nora": "Nora"}, "wnetrze": [{"sekret_id": "d8_torba_kopia", "co_widac": "W rozprutej podszewce leży żółta kopia pokwitowania zaliczek z podpisem „I.” i kwotą 400 dolarów. Obok narzędzia: obcęgi, śrubokręt, miara.", "co_z_tego_wynika": "Kopia dowodzi, że Iris Bell przyjęła 400 dolarów od lokatorów. Maya schowała ją na wszelki wypadek."}], "wejscie": "Dobry wieczór. Nora Vance, a to Lena Brandt. Obie przyszłyśmy po tę samą torbę narzędziową, szarą, z rozprutą podszewką. Lena twierdzi, że to torba jej siostry. Ja twierdzę, że w podszewce jest papier z kamienicy.", "wejscie_jesli": {"d3_maz_i_siostra:wydaj_evan": "Dobry wieczór. Nora Vance, a to Lena Brandt. Lena po awanturze z Evanem chce chociaż torbę siostry. Ja chcę z niej papier z kamienicy. Torba jest szara, z rozprutą podszewką.", "d3_maz_i_siostra:wydaj_lena": "Dobry wieczór. Nora Vance, a to Lena Brandt. Lena ma już telefon siostry i chce jeszcze jej torbę. Ja chcę z niej papier z kamienicy. Torba jest szara, z rozprutą podszewką."}, "tury": [{"pytania": [{"tekst": "Czyja jest ta torba?", "ton": "uprzejme", "kto": "siostra", "wymaga": null, "odpowiedz": "Mai, mojej siostry. Kupiłam jej ją na urodziny, narzędzia, dziwny prezent, wiem. Teraz to jedyna rzecz po niej, jaką mogę dotknąć.", "mina": "emocja"}, {"tekst": "Czego szukasz w tej torbie?", "ton": "rzeczowe", "kto": "nora", "wymaga": null, "odpowiedz": "Po kolei: rzecz, osoba, skutek. Papier z podszewki, kopia pokwitowania, rodzina Okoye. Bez niego nie mają dowodu wpłaty.", "mina": "mowi"}, {"tekst": "Po czym poznacie, że torba jest właśnie ta?", "ton": "niewygodne", "kto": "siostra", "wymaga": null, "odpowiedz": "Po obcęgach z żółtą izolacją i miarze z dopiskiem „M”. Ale... no właśnie. Nora też wie, co jest w środku.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Skąd wiesz, że w podszewce jest papier?", "ton": "uprzejme", "kto": "nora", "wymaga": null, "odpowiedz": "Z wykazu mieszkańców. Numer pokwitowania jest w moim zeszycie, a kopię ktoś schował. Nie wiem kto. Chcę zobaczyć, czy się zgadza.", "mina": "mowi"}, {"tekst": "Czy Maya pracowała w tej kamienicy?", "ton": "rzeczowe", "kto": "siostra", "wymaga": null, "odpowiedz": "Pracowała jako elektryczka na Cooper Street dziewięć, na pierwszym piętrze. Ale... no tak, tam była Iris. Nie rozmawiałyśmy o tym.", "mina": "mowi"}, {"tekst": "Ile rodzin jest w tej sprawie?", "ton": "niewygodne", "kto": "nora", "wymaga": null, "odpowiedz": "Czternaście, po czterysta dolarów każda, termin do czwartku, dziewiątego września. Wpłaciły raz, a ja mam to w zeszycie.", "mina": "mowi"}, {"tekst": "W podszewce jest kopia z podpisem „I.” i kwotą 400 $. Czyja?", "ton": "niewygodne", "kto": "nora", "wymaga": "d8_torba_kopia", "odpowiedz": "Iris Bell, zarządczyni. To jej podpis, ja go znam z dwudziestu pokwitowań. Kopia dowodzi, że Okoye zapłacili. Oryginał ma Iris.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz z torbą, jak ją dostaniesz?", "ton": "uprzejme", "kto": "siostra", "wymaga": null, "odpowiedz": "Zabiorę ją do siebie. A jak Maya wróci, to jej oddam. Przecież to jej.", "mina": "emocja"}, {"tekst": "Odbiór wymaga podpisu. Kto podpisze?", "ton": "rzeczowe", "kto": "nora", "wymaga": null, "odpowiedz": "Ja, jako przedstawicielka lokatorów, jeśli chodzi o kopię. Za torbę niech podpisze siostra. Dwie osoby, dwa podpisy.", "mina": "neutralna"}, {"tekst": "Czy któraś z was ustąpi?", "ton": "niewygodne", "kto": "nora", "wymaga": null, "odpowiedz": "Ja nie, bo chodzi o czternaście rodzin. Lena pewnie też nie.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj_lenie_cala", "etykieta": "Wydaj Lenie całą torbę", "kto": "siostra", "reakcja": "Dziękuję. Mam coś po niej. A... Nora, przepraszam, ale to siostra.", "zysk": "Lena ma torbę siostry i spokojniej śpi.", "strata": "Nora traci dowód wpłaty rodziny Okoye, a bez żółtej kopii mają tylko jej słowo.", "echo": {"za_dni": 4, "forma": "gosc", "tekst": "Nora Vance: „Po kolei: kopia poszła z torbą do siostry Mai. Okoye znowu są bez dowodu. Wiem, że trzeba było wybrać. Tylko że zapłacą za to Okoye.”"}}, {"akcja": "kopia_osobno", "etykieta": "Zasłoń dane, zrób kopię osobno za zgodą obu", "kto": "nora", "reakcja": "Zgoda. Po kolei: kopia zasłonięta, torba dla Leny, dokument zostaje w biurze. Nie lubię tego, ale dobrze.", "zysk": "Dowód zostaje w biurze, a Lena dostaje torbę, obie strony się zgodziły.", "strata": "Zajmuje to całą wizytę, a zasłonięte dane osłabiają dowód.", "echo": {"za_dni": 4, "forma": "gosc", "tekst": "Nora Vance: „Kopia z zasłoniętymi nazwiskami leży u was. To mało, ale to jest dowód. Jak będzie trzeba, wrócę po numer pokwitowania.”"}}, {"akcja": "odmow", "reakcja": "Nic z tego? Torba leży w biurze? No to co, mamy czekać? Ale... dobrze.", "zysk": "Torba zostaje w biurze, nikt jej nie dostaje i nikt nie ma pretensji o stronniczość.", "strata": "Lena nie ma nic po siostrze, a Nora nie ma kopii. Obie odchodzą z pustymi rękami.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Lena Brandt: „Torba leży u was, a ja o niej myślę każdą noc. Wiem, że przepisy. Ale to jej torba, a ja nie mam po niej nic innego.”"}}], "rola": "siostra i prawniczka po jedną torbę", "watki": ["kamienica", "Zaginiona"], "tik": "Nora liczy: rzecz, osoba, skutek", "potrzeba": "torba narzędziowa albo kopia pokwitowania", "slad": "kopia 400 $ w rozprutej podszewce", "sprite": "torba_narzedzia", "face": "siostra", "face2": {"siostra": "siostra", "nora": null}, "line": "4", "itemName": "torba narzędziowa", "inside": {"img": "W6", "x": 0.37, "y": 0.6}}, {"id": "d8_bree", "dzien": 8, "postac": "Bree Halm, 29", "glos": "Pewnie, szybko, do sprawy. Zaczyna od „Słuchaj, mam paragon”.", "typ": "profesjonalistka, fałszywy tytuł do rzeczy", "rzecz": "Srebrny analogowy aparat z wgnieceniem w lewym rogu", "wnetrze": [{"sekret_id": "d8_aparat_naklejka", "co_widac": "Pod osłoną baterii wydrapane R.O. Licznik pokazuje 36 z 36: film jest pełny, niewywołany. Na pasku zawieszka z kluczem do skrzynki: „Cooper 9, lok. 4”.", "co_z_tego_wynika": "Aparat należy do Rafa Okoye z Cooper Street. Pełny film z klatki schodowej może być dowodem przeciwko Iris, ale tylko jeśli ktoś go wywoła."}], "wejscie": "Cześć, Bree. Słuchaj, mam paragon. Zgubiłam aparat brata w jedenastce, srebrny, analogowy, z wgnieceniem w rogu. Brat leży w szpitalu i bardzo chce go odzyskać. Potrzebuję go dziś.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten aparat?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Srebrny, analogowy, z wgnieceniem w lewym rogu. Mój brat upuścił go na schodach. Teraz ma charakter.", "mina": "mowi"}, {"tekst": "Gdzie go zostawiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, na siedzeniu. Rozmawiałam przez telefon z lekarzem i nie spojrzałam za siebie.", "mina": "neutralna"}, {"tekst": "Czy w aparacie są jakieś znaki?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie, żadnych. Teo, mój brat, nic nie wydrapał. Aparat jest czysty.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Jak ma na imię twój brat?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Teo. Teodor Halm. Leży na ortopedii, noga w gipsie. To przez rower, powiedział, że to nie jego wina.", "mina": "mowi"}, {"tekst": "Jaki to paragon?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Z komisu na Rynku, sprzed dwóch lat. Mam w telefonie zdjęcie. Słuchaj, tam jest cena, jest data i jest opis, że srebrny.", "mina": "mowi"}, {"tekst": "Co jest na filmie w środku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie wiem, brat go nie wywoływał. Pewnie zdjęcia z wakacji. Nic ważnego.", "mina": "klamie"}, {"tekst": "Pod osłoną baterii jest wydrapane R.O. Czyje?", "ton": "niewygodne", "wymaga": "d8_aparat_naklejka", "odpowiedz": "No dobra. R.O. to Raf Okoye, sąsiad z kamienicy. Pożyczył bratu aparat. Ale to się przecież nie liczy, bo mam paragon.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czemu aparat jest ci tak pilnie potrzebny?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Bo brat chce zdjęć ze szpitala dla mamy. Mama jest daleko i lubi zdjęcia. Dlatego dziś.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bree Halm. Zawsze podpisuję szybko, to znaczy czytelnie. Ale szybko.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli aparat zostanie w biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy zrobię się nieprzyjemna. Albo inaczej: osiemdziesiąt dolarów, wydajesz mi aparat i po sprawie. Co ci szkodzi?", "mina": "mowi", "ustawia": "d8_bree_oferta"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki. Słuchaj, mam paragon, ale i tak dziękuję.", "zysk": "Bree odchodzi z aparatem, a brat dostaje zdjęcia.", "strata": "Aparat Rafa Okoye wychodzi z biura, a razem z nim zdjęcia pękniętej ściany z Cooper Street.", "echo": {"za_dni": 4, "forma": "gosc", "tekst": "Nora Vance: „Raf Okoye szuka aparatu z kamienicy. Miał w nim pełny film z klatki schodowej. Ktoś go wydał. Czyli znowu brak dowodu.”"}}, {"akcja": "odmow", "reakcja": "Nie? A paragon? No dobra, zobaczysz, że to pomyłka.", "zysk": "Aparat zostaje w biurze do wyjaśnienia, do kogo naprawdę należy.", "strata": "Bree wraca ze złością, a jej brat dalej leży bez zdjęć dla mamy.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Raf Okoye: „Słyszałem, że mój aparat jest w biurze rzeczy znalezionych. Przyjdę po niego w sobotę rano. Będę miał kogoś ze sobą, żeby potwierdził.”"}}, {"akcja": "wez_80_bree", "etykieta": "Wydaj aparat Bree i przyjmij od niej 80 $", "kasa": 80, "reakcja": "Proszę, osiemdziesiąt. Cieszę się, że ktoś tu rozumie, jak to działa.", "zysk": "Dostajesz 80 dolarów, czyli ponad pół czynszu.", "strata": "Aparat Rafa znika razem z pełnym filmem, a Bree może się wygadać, że okienko dało się kupić.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Nora Vance: „Raf Okoye mówi, że Bree chwaliła się w kamienicy, że załatwiła aparat przy okienku za osiemdziesiąt dolarów. Pytam tylko, czy to prawda.”"}, "wymaga": "d8_bree_oferta"}], "rola": "kobieta z paragonem na wszystko", "watki": ["kamienica", "pieniądze"], "tik": "mówi „Słuchaj, mam paragon”", "potrzeba": "srebrny aparat „brata”", "slad": "aparat Okoye i oferta 80 $", "sprite": "aparat", "face": null, "face2": null, "line": "11", "itemName": "aparat", "inside": null}, {"id": "d9_iris", "dzien": 9, "postac": "Iris Bell i Victor Crane", "glos": "Iris: cicho, uprzejmie, „nie lubię naciskać”, nigdy nie dotyka szyby. Victor: krótko, „kto to podpisze?”, wszystko w dwóch egzemplarzach.", "typ": "dwie strony jednego piórnika", "rzecz": "Metalowy matowy piórnik na zatrzask z dwoma przedziałami", "ludzie": {"iris": "Iris Bell", "victor": "Victor Crane"}, "wnetrze": [{"sekret_id": "d9_zetony_numery", "co_widac": "W piórniku pięć żetonów: 0412, 0517, 0623, 0731 i 0809. Na rewersach karteczki: „ojciec z dzieckiem”, „kobieta z walizką”, „matka z synem”, „kasetowiec”. Piąty żeton, 0809, ma karteczkę „jeszcze bez opisu”.", "co_z_tego_wynika": "To nie są żetony do skrzynek, tylko numery odbioru paczek z papierami. Cztery mają opis człowieka, piąty jeszcze nie."}], "wejscie": "Dobry wieczór. Iris Bell, znowu. Piórnik z żetonami, szóstka, ostatni kurs. Obok pan Crane z inspekcji, pyta o ten sam numer. Nie lubię naciskać, ale piórnik jest mój i dziś potrzebny.", "wejscie_jesli": {"d4_iris:rejestr": "Dobry wieczór. Iris Bell. Piórnik z żetonami, szóstka, ostatni kurs. Zeszłym razem wpisaliście wszystko do księgi i bardzo dobrze. Obok Victor Crane, pyta o ten sam numer.", "d4_iris:koperta": "Dobry wieczór. Iris Bell. Miło znowu przy tej szybie. Piórnik z żetonami, szóstka, ostatni kurs. Obok Victor Crane, pyta o ten sam numer. Mam nadzieję, że pójdzie szybko.", "d4_iris:odmow_zglos": "Dobry wieczór. Iris Bell. Paczka z zeszłego tygodnia nadal u was leży. Dziś piórnik z żetonami. Obok Victor Crane, pyta o ten sam numer."}, "tury": [{"pytania": [{"tekst": "Co jest w tym piórniku?", "ton": "uprzejme", "kto": "iris", "wymaga": null, "odpowiedz": "Żetony do skrzynek pocztowych w kamienicy. Pięć sztuk, nic więcej. Nudy.", "mina": "klamie"}, {"tekst": "Czego chce inspekcja?", "ton": "rzeczowe", "kto": "victor", "wymaga": null, "odpowiedz": "Numeru odbioru i podpisu. Kto to podpisze? Pokwitowanie w dwóch egzemplarzach, jeden do Urzędu.", "mina": "neutralna"}, {"tekst": "Czemu oboje chcecie tego samego?", "ton": "niewygodne", "kto": "iris", "wymaga": null, "odpowiedz": "Bo żetony przyjechały szóstką, a Victor lubi wszystko, co przyjeżdża. Mnie wystarczy, że wrócą do skrzynek.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Czyje są te żetony?", "ton": "uprzejme", "kto": "iris", "wymaga": null, "odpowiedz": "Moich lokatorów. Nazwisk nie podam, to ich sprawa. Są ludzie, którzy chcą mieć święty spokój.", "mina": "neutralna"}, {"tekst": "Co nie zgadza się w księdze?", "ton": "rzeczowe", "kto": "victor", "wymaga": null, "odpowiedz": "Numery. Piórnik przyjechał, a wpisu o nim nie ma. Brakuje też trzech kwitów od zeszłego miesiąca. Ktoś je wydał bez śladu.", "mina": "neutralna"}, {"tekst": "Co znaczą liczby na żetonach?", "ton": "niewygodne", "kto": "iris", "wymaga": null, "odpowiedz": "Nic. Numeracja skrzynek. Proszę nie szukać w tym fabuły.", "mina": "klamie"}, {"tekst": "Na rewersach: „kobieta z walizką”, „matka z synem”. Co to?", "ton": "niewygodne", "kto": "iris", "wymaga": "d9_zetony_numery", "odpowiedz": "Opisy. Żeby kurier wiedział, komu wręczyć paczkę. Więcej nie powiem przy panu Crane.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czemu piąty żeton nie ma opisu?", "ton": "uprzejme", "kto": "iris", "wymaga": null, "odpowiedz": "Jeszcze go nie ma. Papier przyjdzie, jak przyjdzie. Nie zadaję takich pytań, kiedy ktoś płaci.", "mina": "neutralna"}, {"tekst": "Co się stanie, jak piórnik trafi do Urzędu?", "ton": "rzeczowe", "kto": "victor", "wymaga": null, "odpowiedz": "Zostanie opisany w protokole. Ktoś go przeczyta i wyciągnie wnioski. Ja nie wyciągam, ja zapisuję.", "mina": "neutralna"}, {"tekst": "Co jest w tych paczkach, że ludzie po nie jeżdżą?", "ton": "niewygodne", "kto": "iris", "wymaga": "d9_zetony_numery", "odpowiedz": "Papier na nowe życie. Dla ludzi, których ktoś bije albo ściga. Biorę za to pieniądze i nie mam wstydu. Reszta nie dla inspekcji.", "mina": "emocja"}, {"tekst": "Czemu mam wam ufać?", "ton": "niewygodne", "kto": "iris", "wymaga": null, "odpowiedz": "Nie masz. Zrób, co uznasz za słuszne. Ja tylko mówię, że czterech ludzi kupiło bilet.", "mina": "mowi"}]}], "decyzje": [{"akcja": "zetony_iris", "etykieta": "Wydaj piórnik Iris", "kto": "iris", "reakcja": "Dziękuję. Cieszę się, że się rozumiemy.", "zysk": "Czterech ludzi z żetonów jest bezpiecznych, a Iris będzie ci to pamiętać.", "strata": "Skrytka działa poza księgą, a Victor zapisze, że go zignorowano.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Victor Crane: „Piórnik wydano osobie prywatnej. Zapisałem bez komentarza. Kto to podpisał? Nikt. Dlatego notuję.”"}}, {"akcja": "zetony_victor", "etykieta": "Pokaż żetony Victorowi i podpisz oba egzemplarze", "kto": "victor", "reakcja": "Dwa egzemplarze. Jeden do Urzędu, jeden zostaje. Dziękuję.", "zysk": "W księdze jest ślad i nikt nie zarzuci ci układu z Iris.", "strata": "Numery żetonów jadą do Urzędu, a Iris tego nie zapomni.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Iris Bell: „Czterech moich lokatorów dostało dziś pisma z Urzędu. Ciekawe, kto pokazał im ich numery.”"}}, {"akcja": "jeden_egzemplarz", "etykieta": "Pokwituj Victorowi tylko jeden egzemplarz", "kto": "victor", "reakcja": "Jeden. Dobrze, zapisuję. Ale proszę wiedzieć, że wolałbym dwa.", "zysk": "Victor ma swój podpis, a drugiej kopii nikt nie wysyła do Urzędu.", "strata": "Victor policzy to jako niechęć do współpracy, a Iris nadal nie ma piórnika.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Inspekcja przewozów: z biura wpłynął jeden egzemplarz pokwitowania zamiast dwóch. Odnotowano. — V. Crane"}}, {"akcja": "depozyt", "etykieta": "Zostaw piórnik w depozycie do soboty", "kto": "victor", "reakcja": "Depozyt do soboty. Wpisuję. Tylko że ktoś czeka na swój papier.", "zysk": "Zyskujesz czas do soboty, a nikt nie dostaje piórnika.", "strata": "Do soboty żaden z czterech nie dostanie dokumentu, a jedna rodzina jedzie jutro o 5:40.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Iris Bell: „Piórnik leży w depozycie. Rozumiem procedury. Ale jeden z moich ludzi ma jutro pociąg.”"}}], "rola": "zarządczyni i inspektor o jeden piórnik", "watki": ["Skrytka", "Urząd", "Fotel"], "tik": "Iris cicho, Victor „kto podpisze?”", "potrzeba": "piórnik z pięcioma żetonami", "slad": "numery to daty zamówienia, 0809 na końcu", "sprite": "piornik", "face": "dama", "face2": null, "line": "6", "itemName": "piórnik", "inside": {"img": "W7", "x": 0.2, "y": 0.58}}, {"id": "d9_stahl", "dzien": 9, "postac": "Marek Stahl, ok. 50", "glos": "Gładko, za starannie, jakby recytował. Zaczyna od „Zgodnie z regulaminem…”. Zbyt grzeczny.", "typ": "zgłaszający zgubę", "rzecz": "Szary filcowy kapelusz z granatową wstążką", "wnetrze": [{"sekret_id": "d9_kapelusz_naklejka", "co_widac": "Pod wstążką naklejka: „Alder & Son, rozmiar 56”. W podszewce haftowane inicjały J.K.", "co_z_tego_wynika": "Kapelusz jest rozmiar 56 z inicjałami J.K. Zgłaszający mówi o innym rozmiarze i innych inicjałach."}], "wejscie": "Dobry wieczór. Marek Stahl. Zgodnie z regulaminem zgłaszam zgubę: szary filcowy kapelusz z granatową wstążką, wczoraj w czwórce. Opis mam bardzo dokładny, żeby nie tracić państwa czasu.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten kapelusz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szary, filcowy, granatowa wstążka, rozmiar pięćdziesiąt osiem. Zgodnie z regulaminem podaję wszystko od razu.", "mina": "klamie"}, {"tekst": "Gdzie i kiedy go zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Wczoraj, czwórka, około dwudziestej drugiej. Siedziałem sam, kapelusz leżał na półce nad oknem.", "mina": "klamie"}, {"tekst": "Czemu akurat ten kapelusz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo jutro mam ważną rozmowę, a bez niego wyglądam nieprzekonująco. Tak mówi moja żona.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Jakie masz inicjały?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "M.S. Marek Stahl. Można zapisać zgodnie z regulaminem.", "mina": "mowi"}, {"tekst": "Jest w nim naklejka producenta?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Pod wstążką, tak. Nazwy nie pamiętam. Regulamin tego nie wymaga.", "mina": "klamie"}, {"tekst": "Jechałeś sam?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Sam. Zawsze sam. Zgodnie z rozkładem nikt obok nie siadał.", "mina": "klamie"}, {"tekst": "Pod wstążką jest „Alder & Son, 56”, w środku J.K. Czyj to kapelusz?", "ton": "niewygodne", "wymaga": "d9_kapelusz_naklejka", "odpowiedz": "…Chwileczkę. Biuro ma dobry wzrok. Kapelusz nie jest mój. Chciałem zobaczyć, czy ktoś go wyda za opis.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Kto może potwierdzić, że to twój kapelusz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Żona, ale jest w delegacji. Zaświadczenie mogę przynieść jutro, zgodnie z regulaminem.", "mina": "klamie"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Marek Stahl, z kropką po imieniu. Zgodnie z regulaminem.", "mina": "neutralna"}, {"tekst": "Co zrobisz, jeśli kapelusz zostanie u nas?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Odejdę. Ale nie od razu. Postoję jeszcze chwilę, jeśli państwo pozwolą. Lubię patrzeć na ludzi przy pracy.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Zgodnie z regulaminem wszystko w porządku. Proszę się nie przejmować.", "zysk": "Stahl odchodzi z kapeluszem, kolejka rusza.", "strata": "Kapelusz wychodzi po samym opisie, bez żadnego dowodu. Victor to zauważy.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Inspekcja przewozów: odnotowano wydanie rzeczy po samym opisie. Proszę o uzupełnienie procedury. — V. Crane"}}, {"akcja": "odmow", "reakcja": "Rozumiem. Zgodnie z regulaminem to poprawna odpowiedź. Dziękuję za cierpliwość.", "zysk": "Kapelusz zostaje, dopóki nie zgłosi się ktoś, kto zna wnętrze.", "strata": "Stahl nie przyznaje się do niczego i dalej stoi w kolejce, patrząc.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Inspekcja przewozów: odnotowano odmowę wydania rzeczy bez dowodu. Przyjęto do wiadomości. — V. Crane"}}, {"akcja": "zadzwon", "etykieta": "Zadzwoń do inspekcji, że opis nie pasuje", "reakcja": "Dzwonić? Przy takiej drobnostce? Zgodnie z regulaminem… dobrze, dobrze, nie ma sprawy.", "zysk": "Masz pewność, że nikt nie nabrał biura, i ślad w księdze.", "strata": "Victor liczy, ile razy pytasz o pozwolenie, zamiast zdecydować sam.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Inspekcja przewozów: odnotowano telefon w sprawie niezgodności opisu. Nie wszystko wymaga telefonu. — V. Crane"}}], "rola": "zbyt grzeczny zgłaszający kapelusz", "watki": ["Zaginiona", "Urząd"], "tik": "mówi „zgodnie z regulaminem”", "potrzeba": "szary filcowy kapelusz bez dowodu", "slad": "kłamie o sobie i wraca w d22", "sprite": "kapelusz", "face": null, "face2": null, "line": "4", "itemName": "kapelusz", "inside": null}, {"id": "d10_vera", "dzien": 10, "postac": "Vera Kovacs, 62", "glos": "Najpierw miejsce, potem rzecz, na końcu nazwisko. Dzwoni kluczami przy pasie, kiedy się wstydzi.", "typ": "uczciwa, ukrywa", "rzecz": "Blaszane pudełko zapinane na sprzączkę", "wnetrze": [{"sekret_id": "d10_pudelko_karta", "co_widac": "W pudełku pasek od zegarka bez tarczy i karta inwentarza szuflady z numerem 6. Na wewnętrznej stronie wieka ołówkiem: „Teczka jest pusta. Tak ma być. S.H.” Ten sam numer 6 jest na szufladzie w biurze, w której leży klucz bez zamka.", "co_z_tego_wynika": "Szuflada w biurze należała do Sama. Klucz bez zamka otwiera tę szufladę."}], "wejscie": "Dobry wieczór. Zaplecze tramwajowe, pudełko z szafki, Vera Kovacs. Zgubiłam je w jedenastce, w drodze do domu. Szafkę zamykają w przyszły piątek, a pudełko jest z niej. Proszę o pomoc.", "tury": [{"pytania": [{"tekst": "Jak wygląda to pudełko?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Blaszane, zapinane na sprzączkę. Na wieczku wgniecenie, bo siadałam na nim w poczekalni. Zapina się z oporem.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie je zgubiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, wczoraj, ostatni kurs. Położyłam je obok i wysiadłam bez niego. Klucze mi dzwoniły, jak biegłam.", "mina": "neutralna"}, {"tekst": "Czemu zgubiłaś rzecz z cudzej szafki?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo nosiłam je do domu, żeby nikt ich nie wyrzucił. Szafka jest starego pracownika, nie moja.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Czyja to szafka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Sama Holta, poprzednika w tym biurze. Odszedł ponad miesiąc temu i nikt się szafką nie zajmuje, tylko ja.", "mina": "mowi"}, {"tekst": "Co jest w pudełku?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Pasek od zegarka i kartka z inwentarza. Nic wartościowego.", "mina": "neutralna"}, {"tekst": "Dlaczego to ty zajmujesz się jego szafką?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo jak szafka jest zajęta, to nikt jej nie likwiduje. Sam mnie o to prosił. Powiedział: trzymaj, aż wrócę.", "mina": "emocja"}, {"tekst": "Na karcie jest numer szuflady 6, taki jak w biurze. Co to znaczy?", "ton": "niewygodne", "wymaga": "d10_pudelko_karta", "odpowiedz": "Że szuflada szóstka jest jego. Klucz od niej dostałam od Sama i zostawiłam w tej szufladzie, żeby następny nie musiał go szukać.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czemu zależy ci na tym pudełku?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Bo to ostatnie, co zostało po Samie. Wezwałam go na przyszły piątek, na zamknięcie szafki. Chcę, żeby miał co zabrać.", "mina": "emocja"}, {"tekst": "Co się stanie z rzeczami, jeśli Sam nie przyjdzie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Pójdą do zbiorczego archiwum Urzędu i nikt ich potem nie znajdzie. Dlatego proszę, żeby ktoś przy tym był, jak Sam przyjdzie.", "mina": "mowi"}, {"tekst": "Czy Sam wie, że go wezwałaś?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wie. Napisałam. Nie odpisał. Ale on nigdy nie odpisuje, tylko przychodzi. To znaczy, powinien przyjść.", "mina": "emocja"}]}], "decyzje": [{"akcja": "pokwituj_osobista", "etykieta": "Pokwituj jako osobistą rzecz Sama", "reakcja": "Dziękuję. Osobista rzecz Sama Holta. Proszę o podpis… tak, tutaj, przy K.", "zysk": "Sam zobaczy, że biuro traktuje jego rzeczy jak osobiste, i będzie po twojej stronie.", "strata": "Rzecz zostaje poza zbiorczym archiwum, a Urząd dowie się, że ktoś ją zatrzymał.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Vera Kovacs: „Szafka Sama jest zamknięta, ale pudełko u was. Napisałam do niego jeszcze raz. Nie wiem, czy przyjdzie, ale ktoś będzie czekał.”"}}, {"akcja": "archiwum", "etykieta": "Oddaj do zbiorczego archiwum", "reakcja": "Rozumiem. Zbiorcze archiwum. Jak trzeba, to trzeba.", "zysk": "Czysto, zgodnie z przepisami: rzeczy Sama są w archiwum Urzędu.", "strata": "Rzeczy osobiste Sama zostają w systemie Urzędu, a Sam straci możliwość odebrania ich samodzielnie.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Vera Kovacs: „Pudełko pojechało do archiwum. Napisałam do Sama, że rzeczy są w papierach. Nie odpisał. Chyba ma żal.”"}}, {"akcja": "zatrzymaj_do_15", "etykieta": "Zatrzymaj pudełko do przyjścia Sama w piątek", "reakcja": "Do piątku? Dziękuję. Przyprowadzę go, jak się zgodzi.", "zysk": "Sam odbierze pudełko osobiście, a Vera nie złamie obietnicy.", "strata": "Rzecz leży bez wpisu przez tydzień, a Urząd może zacząć pytać, czemu.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Vera Kovacs: „Zatrzymane do piątku. Powiedziałam Samowi. Nie odpisał, ale chyba przeczytał. To znaczy, że może przyjdzie.”"}}], "rola": "zaplecze z kluczami przy pasie", "watki": ["Poprzednik", "Skrytka", "Fotel"], "tik": "dzwoni kluczami, gdy się wstydzi", "potrzeba": "pudełko z szafki Sama", "slad": "wezwała Sama na zamknięcie jego starej szafki", "sprite": "pudelko_blaszane", "face": null, "face2": null, "line": "11", "itemName": "pudełko", "inside": {"img": "W8", "x": 0.45, "y": 0.65}}, {"id": "d10_dario", "dzien": 10, "postac": "Dario Ruiz, 29", "glos": "Opowiada o jedzeniu, żartuje, wciska kanapkę zamiast pieniędzy. Poważnieje, kiedy mówi o Samie.", "typ": "uczciwy, łapówka w naturze", "rzecz": "Gruby zeszyt grafiku dyżurów w tłustej okładce, z gumką", "wnetrze": [{"sekret_id": "d10_zeszyt_sam", "co_widac": "Na ostatniej stronie zeszytu zapisane: „Sam, 13 $, kanapki i herbata. Oddaje, jak wróci.” Dopisek: „Czy on żyje?”", "co_z_tego_wynika": "Dario martwi się o Sama i nosi jego dług w zeszycie jak ważny dokument."}], "wejscie": "Cześć, Dario, motorniczy z jedenastki. Zgubiłem zeszyt z grafikiem dyżurów, gruby, w tłustej okładce, z gumką. Bez niego nie wiem, kiedy jeżdżę. A przy okazji: czy ktoś tu wie, co się stało z Samem?", "tury": [{"pytania": [{"tekst": "Jak wygląda ten zeszyt?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Gruby, tłusta okładka, bo noszę go z kanapką. Gumka ledwo trzyma. Pachnie cebulą, uprzedzam.", "mina": "mowi"}, {"tekst": "Gdzie go zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, na pętli, jak jadłem. Odłożyłem zeszyt obok kanapki i zjadłem kanapkę. Zeszytu już nie.", "mina": "mowi"}, {"tekst": "Co jest w tym zeszycie poza grafikiem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Przepisy na zupy i numery telefonów. Masz kanapkę, poczęstuj się.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Kim jest Sam?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Kolega, poprzednik z tego okienka. Zawsze miał dla mnie herbatę i dobre słowo. Teraz go nie ma i nikt nie wie gdzie.", "mina": "emocja"}, {"tekst": "Od kiedy go nie ma?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Od ponad miesiąca. Powiedział, że idzie do portu. Potem nie odbierał telefonu. Pytam wszystkich w zajezdni.", "mina": "mowi"}, {"tekst": "Czemu pytasz akurat tutaj?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo to jego miejsce. Jak ktoś ma wiedzieć, to ten, kto siedzi na jego krześle.", "mina": "emocja"}, {"tekst": "Na ostatniej stronie jest dopisek „Czy on żyje?”. Czyj?", "ton": "niewygodne", "wymaga": "d10_zeszyt_sam", "odpowiedz": "Mój. Dopisałem go w poniedziałek. Sam jest mi winien trzynaście dolarów, ale nie o to chodzi. Chcę wiedzieć, czy żyje.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz z zeszytem, jak go dostaniesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Wrócę na pętlę i będę jeździł według grafiku. A w wolnej chwili spróbuję znowu zadzwonić do Sama.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Dario Ruiz, z zetem na końcu. Pół zajezdni to Ruizowie, Dana z warsztatu to moja kuzynka.", "mina": "neutralna"}, {"tekst": "Co zrobisz, jeśli nikt nie odpowie o Samie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Będę pytał dalej. Aż ktoś powie albo aż mi się znudzi, a to drugie się nie zdarza.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki! Masz, weź kanapkę, serio. A jakby ktoś coś wiedział o Samie, to wiesz, gdzie jestem.", "zysk": "Dario odzyskuje grafik, a ty dostajesz pół kanapki z cebulą.", "strata": "Nie dowiadujesz się nic o Samie, a Dario wraca z tą samą troską.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Dario Ruiz: „Zeszyt cały, nawet okruchy po kanapce są. Jak wiesz coś o Samie, to powiedz. Nie ma pośpiechu. Jest tylko pytanie.”"}}, {"akcja": "odmow", "reakcja": "Co? To przecież mój zeszyt! Dobra, przyniosę kogoś z zajezdni, kto potwierdzi.", "zysk": "Zeszyt zostaje w biurze, a w nim dopisek o Samie, który możesz przeczytać jeszcze raz.", "strata": "Dario nie ma grafiku i jutro nie wie, o której jedzie. Szef się wścieknie.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Dario Ruiz: „Spóźniłem się na zmianę, bo nie miałem grafiku. Szef dał mi dyżur w niedzielę. Za karę.”"}}, {"akcja": "powiedz_dario", "etykieta": "Wydaj zeszyt i powiedz, że Sam ma przyjść po rzeczy w piątek", "reakcja": "Naprawdę? Wróci? To dobrze. Powiem mu, że czeka na niego kanapka. A jak nie przyjdzie, to chociaż wiem, że żyje.", "zysk": "Dario przestaje się martwić, a Sam ma przyjaciela, który przyjdzie na spotkanie.", "strata": "Zdradzasz plan Sama: jeśli nie chciał, żeby ktoś o nim wiedział, może się wycofać.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Dario Ruiz: „Powiedziałem wszystkim w zajezdni, że Sam przyjdzie w piątek za tydzień. Wszyscy się ucieszyli. Mam nadzieję, że to dobrze.”"}, "wymaga": "d10_vera:pokwituj_osobista|d10_vera:zatrzymaj_do_15|d10_vera:archiwum"}], "rola": "motorniczy, który płaci kanapką", "watki": ["Poprzednik", "humor"], "tik": "mówi „masz, weź kanapkę”", "potrzeba": "zeszyt grafiku dyżurów", "slad": "zapisał dług Sama i pyta o niego", "sprite": "ksiazka", "face": null, "face2": null, "line": "11", "itemName": "zeszyt z przepisami", "inside": null}, {"id": "d11_maya", "dzien": 11, "postac": "Maya Doyle, 34", "glos": "Precyzyjna, spokojna. Przed każdą zgodą liczy do trzech. Mówi słowami z elektryki: zwarcie, obwód, bezpiecznik.", "typ": "właścicielka, która sama układa zasady", "rzecz": "Czarny pokrowiec na okulary ze zszytą gumką", "wnetrze": [{"sekret_id": "d11_trzy_warunki", "co_widac": "Pod wewnętrzną łatką leży złożona karteczka z trzema numerowanymi punktami, pisanymi równym, drobnym pismem. Punkt pierwszy: „Nikt nie wie, gdzie jestem”.", "co_z_tego_wynika": "Maya zaplanowała, kto i co się o niej dowie. Nie zginęła: sama układa zasady."}], "wejscie": "Maya Doyle. Zostawiłam pokrowiec na okulary w czwórce, wczoraj. Zanim go wyjmiecie, opiszę: czarny, gumka zszyta z boku, wewnątrz łatka niebieską nitką. Jeśli się zgadza, porozmawiamy.", "wejscie_jesli": {"d7_evan:powiedz_linie": "Maya Doyle. Pokrowiec na okulary, czwórka. Opiszę go: czarny, gumka zszyta z boku, łatka niebieską nitką. I jedno pytanie: ktoś powiedział mojemu mężowi, którą linią jeżdżę. Stał trzy noce na pętli. Kto?"}, "tury": [{"pytania": [{"tekst": "Jak wygląda ten pokrowiec?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, twardy. Gumkę z boku zszyłam sama, a łatkę w środku niebieską nitką, bo czarna się skończyła. Sprawdź, to chwila.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy go zostawiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, wczoraj koło 22:40, przy tylnych drzwiach. Zostawiłam celowo, więc nie pytaj, czy zapomniałam.", "mina": "neutralna"}, {"tekst": "Skąd znasz łatkę, zanim ją zobaczysz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Z pamięci, jak każdą własną rzecz. Dziwniej byłoby, gdybym jej nie znała.", "mina": "neutralna"}, {"tekst": "Evan stał trzy noce na pętli czwórki. Wiesz o tym?", "ton": "niewygodne", "wymaga": "d7_evan:powiedz_linie", "odpowiedz": "Widziałam z wagonu. Szedł równo, z termosem, jak ktoś, komu podano linię. Chcę wiedzieć, kto mu ją podał.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czemu zostawiasz rzeczy w tramwajach?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Telefon, klucze, torbę, teraz pokrowiec. Chcę wiedzieć, czy ktoś po drugiej stronie szyby wytrzyma i nie zacznie rozdawać. Na razie wytrzymuje.", "mina": "mowi"}, {"tekst": "Czy Lena ci pomogła?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Tak, na początku, z mieszkaniem. Potem zaczęła decydować, co mi wolno. To było drugie zwarcie.", "mina": "mowi"}, {"tekst": "Czemu mnie obserwujesz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Sprawdzam, co robisz z rękami. Tamten też nie wiedział, co z nimi zrobić, a siedział tu dłużej.", "mina": "neutralna"}, {"tekst": "Na karteczce pod łatką są trzy punkty. Kto je ułożył?", "ton": "niewygodne", "wymaga": "d11_trzy_warunki", "odpowiedz": "Ja, przez trzy noce, w kolejności, w jakiej coś może się zepsuć. Pierwszy: nikt nie wie, gdzie jestem. Resztę dostanie ten, kto dostanie moje „tak”.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czego od nas potrzebujesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Trzech rzeczy. Nikt nie wie, gdzie jestem. Jedno zdanie może iść do policjanta: „Żyje. Nie wróci. Nie szukać.” Reszta tylko za moim „tak”.", "mina": "mowi"}, {"tekst": "Telefon dostał Evan. Wiesz, co zrobił?", "ton": "uprzejme", "wymaga": "d3_maz_i_siostra:wydaj_evan", "odpowiedz": "Wiem od Leny. Przeczytał jej SMS i poszedł do niej z awanturą. Takie zwarcie. Nie mam żalu, ale policzyłam. A teraz nikt nie wie, gdzie jestem.", "mina": "emocja"}, {"tekst": "Telefon dostała Lena. Co z tego wynikło?", "ton": "uprzejme", "wymaga": "d3_maz_i_siostra:wydaj_lena", "odpowiedz": "Lena ma swoją wiadomość, a Evan został bez śladu i przestał ufać tej szybie. Obie strony policzyłam. Zostaje jedno: nikt nie wie, gdzie jestem.", "mina": "emocja"}, {"tekst": "Co z rzeczami, które u nas leżą?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Niech leżą. To depozyt. Wezmę je, jak skończę, i nikt ich beze mnie nie czyta.", "mina": "neutralna"}, {"tekst": "Szalik z twoimi inicjałami też tu leży. Czemu go zostawiłaś?", "ton": "rzeczowe", "wymaga": "d2_szalik_md", "odpowiedz": "Szalik był pierwszy. Chciałam zobaczyć, czy ktoś go sprzeda albo poda dalej. Nikt nie podał, więc zostawiam dalej.", "mina": "mowi"}, {"tekst": "Czy powiadomić rodzinę, że żyjesz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wysłuchaj do końca. Raz. Dwa. Trzy. Nie, nie bez mojego „tak”. Nawet jeśli oni nie śpią.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "przez_okienko", "etykieta": "Zgoda: kontakt tylko przez okienko", "reakcja": "Raz. Dwa. Trzy. Tak. Okienko, jedno zdanie dla policjanta, reszta za moim „tak”. Zapisz, że zgodziłam się dziś i bez przymusu.", "zysk": "Maya ci ufa i będzie wracać po swoje rzeczy.", "strata": "Evan i Lena nie dowiedzą się niczego, a Evan stoi dalej na pętli.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Noah Reyes: „Dostałem jedno zdanie: żyje, nie wróci, nie szukać. Nie pytam skąd. Zapisałem słowo w słowo.”"}}, {"akcja": "powiadom_rodzine", "etykieta": "Powiadom rodzinę przy Mai", "reakcja": "Nie. Raz. Dwa. Trzy. Nie. Wrócę już tylko po swoje rzeczy i bez słowa.", "zysk": "Rodzina dowie się, że Maya żyje, i przestanie czekać w niepewności.", "strata": "Maya zrywa rozmowy i przychodzi już tylko po walizkę, bez słowa.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Lena Brandt: „Dowiedziałam się od was, że siostra żyje. Nie powiedzieliście gdzie ani dlaczego, a ona nie dała mi nic powiedzieć. Jeśli coś po niej zostało, niech ktoś mi powie. — L.”"}}, {"akcja": "szept_lenie", "etykieta": "Powiedz Lenie po cichu, że siostra żyje", "reakcja": "Skąd on wie… skąd ona wie, że tu byłam? Policzyłam, że ktoś wygada. Nie myliłam się.", "zysk": "Lena przestaje się bać, a Maya zostaje bez straży, której nie chciała.", "strata": "Maya dowie się od Leny, że ktoś wygadał, i przestanie ci ufać.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Lena Brandt: „Ktoś mi powiedział po cichu, że Maya żyje. Płakałam dwa dni z ulgi. Nie pytam kto. Nie powiem Evanowi. — L.”"}}], "rola": "elektryczka, która układa zasady", "watki": ["Zaginiona", "Fotel"], "tik": "liczy „raz, dwa, trzy”", "potrzeba": "sama zdecydować, kto wie", "slad": "pierwszy z trzech testów, które robi okienku", "sprite": "futeral", "face": null, "face2": null, "line": "4", "itemName": "pokrowiec na okulary", "inside": null}, {"id": "d11_grace", "dzien": 11, "postac": "Grace Okoye, 35", "glos": "Krótko, zmęczona, liczy czas w godzinach dyżuru. Czarny szpitalny humor, nigdy nie narzeka wprost.", "typ": "uczciwa, spieszy się", "rzecz": "Granatowa torebka na ramię z legitymacją szpitalną", "wnetrze": [{"sekret_id": "d11_kartka_iris", "co_widac": "W bocznej kieszeni złożona kartka sprzed dwóch tygodni: „Iris, 400 $, żółta kopia u elektryczki z pierwszego piętra”. Obok legitymacja szpitalna z jej zdjęciem.", "co_z_tego_wynika": "Grace wpłaciła 400 dolarów Iris Bell, a dowód wpłaty, żółta kopia, jest u Mai Doyle. To ta kopia z torby narzędziowej z dnia 8."}], "wejscie": "Grace Okoye, pielęgniarka, nocka na onkologii. Zostawiłam torebkę w jedenastce, granatową, z legitymacją. O szóstej muszę wejść na oddział, a bez karty drzwi się nie otworzą. Mam godzinę i dwadzieścia minut.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta torebka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Granatowa, skórzana, na ramię. Pasek przetarty od smyczy. Legitymacja ma moje zdjęcie z trzeciego roku, jeszcze z lepszą cerą.", "mina": "mowi"}, {"tekst": "Co jest w środku oprócz legitymacji?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Klucze, tabletki na ból głowy i kartka z zakupami. Nic więcej.", "mina": "mowi"}, {"tekst": "Czemu bez karty nie wejdziesz na oddział?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Drzwi są na kartę, a dyżurny nikogo nie wpuszcza na słowo. Ma rację, ale dziś mnie to boli.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Gdzie pracujesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szpital miejski, onkologia, trzecie piętro. Nocki od dwudziestej. Dzieci śpią u sąsiadki, więc tym bardziej nie mam czasu.", "mina": "mowi"}, {"tekst": "Kiedy zostawiłaś torebkę?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Koło wpół do pierwszej, w jedenastce. Zdjęłam ją z ramienia, bo bolał mnie bark. Wysiadłam na Rynku bez niej.", "mina": "mowi"}, {"tekst": "Kartka w kieszeni to na pewno zakupy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Zakupy. Mleko, chleb. Ale proszę jej nie czytać, bo jest głupia.", "mina": "emocja"}, {"tekst": "Na kartce jest: „Iris, 400 $, żółta kopia u elektryczki”. Co to?", "ton": "niewygodne", "wymaga": "d11_kartka_iris", "odpowiedz": "To moje czterysta dolarów i dowód, że je wpłaciłam. Kopię schowała elektryczka z naszej kamienicy, bo Iris nie lubi, jak lokatorzy mają papiery.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Ktoś potwierdzi, że to twoja torebka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dyżurny z oddziału, Hollis. Zadzwoń, odbierze po trzecim sygnale, zawsze się spóźnia.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "G. Okoye, byle szybko. Zegar bije.", "mina": "neutralna"}, {"tekst": "Żółta kopia została u nas. Czy to dowód twoich 400 $?", "ton": "rzeczowe", "wymaga": "d8_lena_i_nora:kopia_osobno", "odpowiedz": "Czyli gdzieś jest. Nora Vance ją zna. Dobrze, niech leży zamknięta, bo mam szóstą.", "mina": "emocja"}, {"tekst": "Żółta kopia poszła z torbą do siostry Mai. Wiesz o tym?", "ton": "rzeczowe", "wymaga": "d8_lena_i_nora:wydaj_lenie_cala", "odpowiedz": "Nie wiedziałam. Czyli dowód mam tylko w głowie i na kartce. Dlatego kartkę wezmę, przepraszam.", "mina": "emocja"}, {"tekst": "Czy Iris cię o coś prosiła?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "O drobną przysługę. Iris zawsze prosi o drobną przysługę, a potem sama się robi pogoda.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Zdążę. Karta, drzwi, Hollis. Reszta może poczekać do rana.", "zysk": "Grace wchodzi na oddział o 6:00 i nikt jej nie karze.", "strata": "Kartka z wpłatą 400 $ wychodzi z biura i nie zostaje po niej żaden ślad.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Nora Vance: „Grace mówi, że odebrała torebkę i że o kopii powiedziała tutaj. Przyjdę po kolei: rzecz, osoba, skutek.”"}}, {"akcja": "kartka_odpis", "etykieta": "Poproś o zgodę i przepisz kartkę do rejestru", "reakcja": "Przepisz. Jedną linijkę, bez nazwiska. Szybko, proszę, mam szóstą.", "zysk": "W rejestrze zostaje ślad wpłaty Okoye, więc Nora będzie miała czym walczyć.", "strata": "Grace traci minuty, których nie ma, i boi się, że Iris dowie się, skąd ślad.", "echo": {"za_dni": 1, "forma": "list", "tekst": "W rejestrze jest wpis o wpłacie 400 $ rodziny Okoye. Dziękuję. Przy następnej wizycie zapytam, co z oryginałami. — N. Vance"}}, {"akcja": "zadzwon", "etykieta": "Zadzwoń do Hollisa, zanim wydasz", "reakcja": "Dzwoń. Ale on odbiera po trzecim sygnale i potem mówi dwie minuty o grafiku.", "zysk": "Hollis potwierdza i masz pewność, że torebka jest jej.", "strata": "Grace traci dwadzieścia minut i może nie zdążyć na oddział.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Grace Okoye: „Weszłam o 6:02. Hollis zapisał mi spóźnienie. Powiedział, że to przez biuro. Śmiałam się, bo co mi zostało.”"}}], "rola": "pielęgniarka z nocnej zmiany", "watki": ["kamienica", "pieniądze"], "tik": "liczy czas godzinami dyżuru", "potrzeba": "torebka z kartą na szóstą", "slad": "wpłaciła 400 $ i nie ma papieru", "sprite": "torebka", "face": null, "face2": null, "line": "11", "itemName": "torebka", "inside": null}, {"id": "d12_iris_nora", "dzien": 12, "postac": "Iris Bell, Nora Vance, Ada Vale", "glos": "Iris: cicho, „nie lubię naciskać”, nigdy nie dotyka szyby. Nora: po kolei, rzecz-osoba-skutek. Ada: wprost, bo tu mówią do niej ładnie.", "typ": "dwie prawdy na jednym papierze", "rzecz": "Torba na zakupy z drugą kasetką na dnie", "ludzie": {"iris": "Iris Bell", "nora": "Nora Vance", "ada": "Ada Vale"}, "wnetrze": [{"sekret_id": "d12_oryginaly", "co_widac": "W kasetce leżą oryginały pokwitowań zaliczek lokatorów i druga lista: wpłaty miasta na rzecz kamienicy, 6 800 $, z podpisem Iris. Między nimi bloczek z numerami odbioru.", "co_z_tego_wynika": "Oryginały dowodzą dwóch rzeczy: co wpłacili lokatorzy i co Iris odebrała od miasta."}], "wejscie": "Iris Bell, Nora Vance i mała Ada Vale stoją razem przy szybie. Iris prosi o kasetkę z torby na zakupy. Nora twierdzi, że są w niej oryginały pokwitowań lokatorów, i żąda ich dziś. Ada pokazuje palcem na puszkę z dnia sześć.", "wejscie_jesli": {"d8_lena_i_nora:wydaj_lenie_cala": "Iris Bell prosi o swoją kasetkę z torby na zakupy. Nora Vance, bez żółtej kopii, którą oddano siostrze Mai, podaje numer z własnego wykazu i żąda oryginałów. Ada Vale pokazuje puszkę. Stoją razem przy szybie."}, "tury": [{"pytania": [{"tekst": "Co jest w kasetce z torby na zakupy?", "ton": "uprzejme", "wymaga": null, "kto": "iris", "odpowiedz": "Rachunki. Karty rozliczeń kamienicy, nic ponad to. To nasze, lokatorów i moje.", "mina": "klamie"}, {"tekst": "Czego dokładnie żądasz?", "ton": "rzeczowe", "wymaga": null, "kto": "nora", "odpowiedz": "Oryginałów pokwitowań zaliczek: czternaście rodzin, po 400 dolarów, termin czwartek, dziewiąty września. Bez nich Okoye zapłacą drugi raz, a ja nie mam jak tego udowodnić.", "mina": "mowi"}, {"tekst": "Ada, czemu pokazujesz na puszkę?", "ton": "niewygodne", "wymaga": null, "kto": "ada", "odpowiedz": "Bo ona jest z tego samego bloczka co papier pani Iris. Mama mówi, że nie wolno gadać, ale tu można, bo tu mówią do mnie ładnie.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Czy lokatorzy wiedzą, gdzie są ich papiery?", "ton": "uprzejme", "wymaga": null, "kto": "iris", "odpowiedz": "Wiedzą, że są bezpieczne. Czasem aż za bardzo, przyznaję. Zbierałam zaliczki, bo ktoś musiał, i to ja musiałam.", "mina": "mowi"}, {"tekst": "Po czym poznasz oryginał?", "ton": "rzeczowe", "wymaga": null, "kto": "nora", "odpowiedz": "Po numerze z mojego wykazu, podpisie „I.” i zielonym stemplu kamienicy. Jak się zgadza, wiem.", "mina": "mowi"}, {"tekst": "Żółta kopia poszła do Leny. Jak udowodnisz wpłatę?", "ton": "rzeczowe", "wymaga": "d8_lena_i_nora:wydaj_lenie_cala", "kto": "nora", "odpowiedz": "Numerem z wykazu: czterysta jedenaście. Papier mogłam zgubić, liczby nie. Ale numer bez oryginału to dalej tylko moje słowo.", "mina": "mowi"}, {"tekst": "Żółta kopia leży u nas. Czy to wystarczy?", "ton": "rzeczowe", "wymaga": "d8_lena_i_nora:kopia_osobno", "kto": "nora", "odpowiedz": "Potwierdza jedną wpłatę, Okoye. Ale tylko jeśli da się ją powiązać z oryginałem. Dlatego oryginały.", "mina": "mowi"}, {"tekst": "Ada, co jeszcze widziałaś u pani Iris?", "ton": "niewygodne", "wymaga": null, "kto": "ada", "odpowiedz": "Że otwiera tę zacinającą się szufladę bez patrzenia. Ja muszę kopnąć w lewy róg.", "mina": "mowi"}, {"tekst": "W kasetce są dwa komplety: wpłaty i 6 800 $ od miasta. Czyje?", "ton": "niewygodne", "wymaga": "d12_oryginaly", "kto": "iris", "odpowiedz": "Miasta, lokatorów i moje, w kolejności, w jakiej je rozdzieliłam. Nora policzyła jedną stronę. To prawie uczciwe rozliczenie.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czemu nie oddasz oryginałów Norze?", "ton": "uprzejme", "wymaga": null, "kto": "iris", "odpowiedz": "Bo jak Nora je pokaże, wyjdzie też to, co leży obok: papiery czterech osób, które już kupiły bilet. Czternaście rodzin czy czterech ludzi? To nie jest pytanie retoryczne.", "mina": "mowi"}, {"tekst": "Co się stanie w czwartek, dziewiątego września?", "ton": "rzeczowe", "wymaga": null, "kto": "nora", "odpowiedz": "Termin mija. Bez oryginałów lokatorzy wpłacają zaliczki drugi raz albo wylatują. Mam czternaście rodzin i dwanaście dni.", "mina": "mowi"}, {"tekst": "Czy w kasetce są też dokumenty dla ludzi z żetonów?", "ton": "niewygodne", "wymaga": null, "kto": "iris", "odpowiedz": "Kasetka jest jedna, papierów w niej dużo. Pytanie jest nieostrożne, więc nie odpowiem.", "mina": "neutralna"}, {"tekst": "Piórnik poszedł do Victora. Co z ludźmi z żetonów?", "ton": "niewygodne", "wymaga": "d9_iris:zetony_victor", "kto": "iris", "odpowiedz": "Są na liście inspekcji: dla niego drobiazg, dla nich wyrok. Tu nie mam wyboru.", "mina": "emocja"}, {"tekst": "Piórnik wrócił do ciebie. Gdzie są teraz żetony?", "ton": "niewygodne", "wymaga": "d9_iris:zetony_iris", "kto": "iris", "odpowiedz": "Bezpieczne. Cztery czekają na odbiór, a piąty jeszcze nie ma opisu. Wszystko w porządku.", "mina": "klamie"}, {"tekst": "Piórnik leży w depozycie. Co z ludźmi z żetonów?", "ton": "niewygodne", "wymaga": "d9_iris:depozyt", "kto": "iris", "odpowiedz": "Czekają. Do soboty żaden z czterech nie dostanie dokumentu, a jedna rodzina jedzie o 5:40 rano. Nie mówię tego jak groźbę, to rozkład jazdy.", "mina": "emocja"}]}], "decyzje": [{"akcja": "zabezpiecz", "etykieta": "Zabezpiecz oryginały za pokwitowaniem", "kto": "nora", "reakcja": "Pokwitowanie, numer, podpis. Tak to powinno wyglądać. Iris patrzy na ciebie, ale ja wolę patrzeć na papier.", "zysk": "Oryginały leżą w biurze za pokwitowaniem, więc Nora ma szansę przed czwartkiem.", "strata": "Iris cię zapamięta, a papiery czterech osób leżą obok oryginałów i przestają być bezpieczne.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Iris Bell: „Dziś rano dwóch lokatorów odmówiło mi zaliczek. Zastanawiam się dlaczego.”"}}, {"akcja": "wydaj_iris", "etykieta": "Wydaj kasetkę Iris", "kto": "iris", "reakcja": "Dziękuję. Zawsze miło, kiedy ktoś rozumie. Drobna przysługa, nic więcej.", "zysk": "Papiery czterech osób zostają poza księgą i poza Urzędem.", "strata": "Oryginały odpływają, a rodzina Okoye zapłaci 400 $ drugi raz.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Wiem, że kasetkę wydano. Okoye wpłacą drugi raz do czwartku. Zapisałam, kto stał przy szybie. — N. Vance"}}, {"akcja": "sprawdz_z_nora", "etykieta": "Sprawdź kasetkę wspólnie z Norą i Iris", "kto": "nora", "reakcja": "Po kolei: numer, podpis, stempel. Zgadza się. Iris, widzisz to, co ja.", "zysk": "Żadna strona nie zarzuci ci stronniczości, a oryginały są policzone.", "strata": "Tracisz godzinę, kolejka rośnie, a Iris widzi dokładnie to, co widzi Nora.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dziękuję za wspólne sprawdzenie. Mam listę numerów, każdy podpisany przez obie strony. Nie wiem jeszcze, co z nią zrobię. — N. Vance"}}, {"akcja": "wyloz_400", "etykieta": "Wyłóż 400 $ z własnych za Okoye", "kasa": -400, "kto": "nora", "reakcja": "Nie prosiłam o to. Przyjmę dla Grace. Nie myśl, że to rozwiązuje resztę.", "zysk": "Rodzina Okoye ma czterysta dolarów na drugą wpłatę i nic nie traci.", "strata": "Tracisz prawie trzy czynsze, a Iris zostaje bezkarna i dalej ma oryginały.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Grace Okoye: „Nora mówi, że ktoś zapłacił za mnie. Nie wiem kto. Dziękuję. Oddam, jak skończę nocki.”"}}], "rola": "zarządczyni, prawniczka i dziecko przy kasetce", "watki": ["Skrytka", "kamienica"], "tik": "Iris „drobna przysługa”, Nora „po kolei”", "potrzeba": "kasetka z oryginałami pokwitowań", "slad": "drugi papier: 6 800 $ wpłaty miasta", "sprite": "torba_zakupy", "face": "dama", "face2": {"iris": "dama", "nora": null, "ada": null}, "line": "6", "itemName": "torba na zakupy", "inside": null}, {"id": "d12_linh", "dzien": 12, "postac": "Linh Tran, 33", "glos": "Cicho, krótkie zdania. Zaczyna od „proszę”. Odpowiada tylko na to, o co pytają.", "typ": "uczciwa i przerażona", "rzecz": "Drewniana pozytywka z gwiazdką na wieczku", "wnetrze": [{"sekret_id": "d12_pozytywka_0623", "co_widac": "Pod ruchomym dnem pozytywki leży bilet na pociąg i kartonik z numerem 0623. Na odwrocie drobny dopisek: „matka z synem”.", "co_z_tego_wynika": "To numer z piórnika Iris, taki sam jak na żetonie. Linh jedzie o 5:40, a ktoś jej szuka."}], "wejscie": "Linh Tran. Mój syn Milo, sześć lat, śpi na ławce. Zgubiłam pozytywkę z kołysanką, jedenastka, drewniana, z gwiazdką na wieczku. Rano mamy pociąg, a bez niej Milo nie zaśnie w drodze. Proszę, bez pytań o to, co w środku.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta pozytywka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Drewniana, mała, z gwiazdką na wieczku. Gra kołysankę, ale jedną nutę zacina. Milo mówi, że gwiazdka kaszle.", "mina": "mowi"}, {"tekst": "Gdzie ją zgubiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, na siedzeniu, kiedy zdejmowałam Milo z kolan. Zasnął, a ja zapomniałam o całym świecie.", "mina": "neutralna"}, {"tekst": "Dokąd jedziecie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Na dworzec, rano. Dalej nie powiem. Nie dlatego, że nie ufam. Dlatego, że nie wolno.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Ile lat ma Milo?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Sześć, w maju skończył. Nie chodzi jeszcze do szkoły, bo szkoły są tam, gdzie zostawia się adres.", "mina": "emocja"}, {"tekst": "Co jest w pozytywce?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Mechanizm i coś, czego wolałabym nie pokazywać. Proszę nie zdejmować dna.", "mina": "emocja"}, {"tekst": "Czy ktoś was szuka?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie wiem. Dlatego pociąg jest o 5:40, a nie o dziewiątej.", "mina": "emocja"}, {"tekst": "Pod dnem jest bilet i kartonik z numerem 0623. Co to?", "ton": "niewygodne", "wymaga": "d12_pozytywka_0623", "odpowiedz": "Proszę, nie pytaj. To jest to, co zostało z trzech lat. Jak ktoś się dowie, Milo i ja nie dojedziemy.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czego potrzebujesz najbardziej?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Żeby Milo zasnął w pociągu. I żeby nikt nie zapisał mojego nazwiska obok jego imienia.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Linh. Samo Linh, bez nazwiska. Jeśli musi być nazwisko, napisz mi, które mam podać.", "mina": "neutralna"}, {"tekst": "Żeton 0623 leży w depozycie. Wiesz o tym?", "ton": "rzeczowe", "wymaga": "d9_iris:depozyt", "odpowiedz": "Wiem, Iris mi powiedziała. Pociąg mam o 5:40, depozyt do soboty. Czyli wyjadę bez papieru albo wcale.", "mina": "emocja"}, {"tekst": "Numer 0623 jest na liście Victora. Wiesz o tym?", "ton": "rzeczowe", "wymaga": "d9_iris:zetony_victor", "odpowiedz": "Wiem, Iris mi powiedziała. Wsiądę, ale będę się rozglądać do ostatniego przystanku.", "mina": "emocja"}, {"tekst": "Kto wam pomaga w tym wyjeździe?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Ktoś, kto bierze za to pieniądze i nie lubi, kiedy się o tym mówi. Więcej nie powiem.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Milo, patrz, gwiazdka wróciła. Nie pytam, co widać. Dziękuję, że nie pytasz.", "zysk": "Linh i Milo mają pozytywkę i bilet, rano wsiądą do pociągu o 5:40.", "strata": "Wydajesz rzecz z numerem od Iris, więc jesteś w jej układzie, a w księdze nie ma po tym śladu.", "echo": {"za_dni": 4, "forma": "list", "tekst": "Pocztówka z dworca, bez nadawcy: narysowana gwiazdka. Pod spodem: „Milo zasnął w połowie drogi. Dziękuję.”"}}, {"akcja": "zatrzymaj", "reakcja": "Rozumiem. Proszę tylko, żeby Milo tego nie słyszał. On pamięta.", "zysk": "Kartonik z 0623 zostaje u ciebie, więc masz dowód, że ktoś handluje papierami.", "strata": "Linh i Milo mogą nie zdążyć na pociąg, a dziecko zostaje na ławce bez kołysanki.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Iris Bell: „Pewna matka z synem nie wsiadła rano do pociągu. Ktoś tu się pomylił i będzie to droga pomyłka.”"}}, {"akcja": "wydaj_zapisz", "etykieta": "Wydaj i wpisz do księgi, że odebrała Linh", "reakcja": "Wpisujecie? Samo Linh, bez nazwiska… dobrze. Tylko proszę, żeby księga leżała zamknięta.", "zysk": "Wydanie jest w księdze, więc nikt nie zarzuci ci tajnych układów.", "strata": "Księgę czyta Victor, a imię Linh i data pociągu trafiają na papier.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Victor Crane: „W księdze jest wpis o pozytywce. Samo imię, bez nazwiska. Zapisuję, że zapisano.”"}}], "rola": "matka z synem w drodze", "watki": ["Skrytka"], "tik": "zaczyna od „proszę”", "potrzeba": "pozytywka, żeby Milo zasnął", "slad": "numer 0623 ukryty pod dnem pozytywki", "sprite": "pozytywka", "face": null, "face2": null, "line": "11", "itemName": "pozytywka", "inside": null}, {"id": "d13_elias", "dzien": 13, "postac": "Elias Wren, 73", "glos": "Powoli, staroświecko, z uprzejmością, która ma coś zasłonić. Składa numerek w prostokąt. Kończy: „Dziękuję.”", "typ": "uczciwy, wstydliwy", "rzecz": "Futerał z oprawką okularów, bez szkieł", "wnetrze": [{"sekret_id": "d13_kwit_zwrotu", "co_widac": "Za wyściółką futerału złożony kwit zwrotu pieniędzy: 85 $, podpis S. Holt. Numer paczki zgadza się z wykazem z piórnika Iris.", "co_z_tego_wynika": "Oprawka przejechała przez ręce Iris, a Sam zwrócił Eliasowi pieniądze z własnej kieszeni."}], "wejscie": "Elias Wren, numerek jeden. Oprawka okularów mojej żony wróciła szóstką, tak mówi konduktor. Chcę ją odebrać. I chcę wiedzieć, dlaczego pan Holt zapłacił za nią z własnej kieszeni, bo ja o to nie prosiłem.", "tury": [{"pytania": [{"tekst": "Jak wygląda oprawka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Złota, cienka, jedno ucho wygięte. Żona prostowała je kciukiem, a ono i tak wracało. Czterdzieści jeden lat.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy zniknęła?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, tuż przed Bożym Narodzeniem, jak wracaliśmy od jej siostry. Potem żona zachorowała i okularów już nie założyła.", "mina": "mowi"}, {"tekst": "Czemu Sam za nią zapłacił?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo obiecał szukać. Nie znalazł, więc zapłacił, jakby to była jego wina. Dowiedziałem się, jak już było po wszystkim.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Z czego żyjesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Z emerytury, czterysta dziesięć dolarów miesięcznie. Nie narzekam, tylko liczę.", "mina": "mowi"}, {"tekst": "Skąd znasz Sama?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Z okienka. Pan Holt nie miał nazwiska na karcie przez dwa lata. Potem napisał ołówkiem: S. Holt. Chyba sam sobie przypominał.", "mina": "mowi"}, {"tekst": "Kiedy Sam odszedł?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Ponad miesiąc temu. Mówił: jeszcze nie, panie Eliasie. A potem przestał przychodzić.", "mina": "emocja"}, {"tekst": "Co wiesz o paczkach, które jeżdżą szóstką?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Że konduktor ich nie lubi. Więcej nie wiem i nie chcę wiedzieć.", "mina": "neutralna"}, {"tekst": "Kwit zwrotu ma numer paczki od Iris. Co to znaczy?", "ton": "niewygodne", "wymaga": "d13_kwit_zwrotu", "odpowiedz": "Nie znam żadnej paczki od Iris. Wiem, że Sam powiedział: nie pytaj, skąd pieniądze. Wziąłem. Wstyd bywa jedyną zapłatą, jaka zostaje.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co chcesz zrobić z kwitem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Żeby ktoś zapisał, że Sam zapłacił, a ja przyjąłem. Żeby to nie był dług bez nazwy. To dla niego, nie dla mnie.", "mina": "mowi"}, {"tekst": "Co zrobisz z pieniędzmi w kopercie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Oddam Samowi do ręki. Cztery tygodnie odkładałem po dwadzieścia jeden dolarów. Nie napiszę ani nie zadzwonię, oddam.", "mina": "mowi"}, {"tekst": "Jak Sam zareaguje?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Odmówi, a ja nie odpuszczę. On jest młodszy, a ja mam czas tylko do końca miesiąca.", "mina": "emocja"}]}], "decyzje": [{"akcja": "odpis_za_zgoda", "etykieta": "Poproś Eliasa o zgodę i zrób odpis kwitu", "reakcja": "Zgoda. Powiem to głośno: pan Holt zapłacił, ja przyjąłem. Proszę napisać dokładnie. Dziękuję.", "zysk": "Masz odpis kwitu i zeznanie Eliasa jako dowód, że Sam zapłacił, a paczka jechała przez ręce Iris.", "strata": "Elias staje się świadkiem w sprawie, której nie wybierał, i będzie o niej pamiętał.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Elias Wren: „Czy ktoś już pokwitował moje zeznanie? Proszę o numer. Jeśli nie, to jutro. — E.W.”"}}, {"akcja": "wydaj_od_reki", "etykieta": "Wydaj oprawkę z całą zawartością od ręki", "reakcja": "Dziękuję. Okulary żony. Jutro… nie, już nie jutro. Dziękuję.", "zysk": "Elias odbiera oprawkę bez pytań i wraca do domu spokojny.", "strata": "Kwit odchodzi z oprawką, więc nie masz dowodu na Sama ani na paczkę od Iris.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Elias przeszedł dziś obok okienka, skłonił głowę i poszedł dalej. Pierwszy raz od trzynastu dni nie zapytał o oprawkę."}}, {"akcja": "zatrzymaj_koperte", "etykieta": "Weź kopertę Eliasa w depozyt dla Sama", "reakcja": "Proszę. Osiemdziesiąt pięć dolarów, w kopercie, dla pana Holta. Niech tam leży, aż odważę się go zapytać.", "zysk": "Pieniądze Sama są bezpieczne, a Elias nie musi sam się z nim mierzyć.", "strata": "Przyjmujesz cudze pieniądze na przechowanie i musisz je zapisać, bo inaczej zostaną po tobie jako dług.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Elias Wren: „Czy koperta nadal leży? Chciałbym ją zobaczyć raz, żeby wiedzieć, że jest. — E.W.”"}}], "rola": "emeryt z długiem wdzięczności", "watki": ["Poprzednik", "Fotel"], "tik": "składa numerek w prostokąt", "potrzeba": "oprawka żony i pytanie o Sama", "slad": "od czterech tygodni odkłada 85 $", "sprite": "futeral", "face": null, "face2": null, "line": "6", "itemName": "futerał z oprawką", "inside": null}, {"id": "d13_odile", "dzien": 13, "postac": "Odile Faber, 68", "glos": "Głośna, wesoła, żartuje z własnych zębów. Mówi „dziecko” do wszystkich, nawet do urzędników.", "typ": "uczciwa, zawstydzona", "rzecz": "Niebieskie pudełko po herbatnikach", "wnetrze": [{"sekret_id": "d13_mandat", "co_widac": "W pudełku na serwetce leży proteza z wygrawerowanymi od spodu inicjałami O.F. Pod nią złożony mandat za jazdę bez biletu, bez pieczątki, z dopiskiem Leo: „zdarza się”.", "co_z_tego_wynika": "Odile jeździ bez biletu, a konduktor to przepuszcza. To nic dla sprawy, tylko ludzka rzecz."}], "wejscie": "Odile Faber, sześćdziesiąt osiem lat i trzydzieści dwa zęby, z czego dwadzieścia osiem moich. Zgubiłam protezę w pudełku po herbatnikach, szóstka, dziś rano. O dziesiątej ślub wnuczki, a zdjęcie rodzinne bez zębów to kara.", "tury": [{"pytania": [{"tekst": "Jak wygląda to pudełko?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Okrągłe, niebieskie, po duńskich herbatnikach. Wieczko zagięte, bo siadam na nim na przystanku. W środku serwetka w kwiatki.", "mina": "mowi"}, {"tekst": "Czemu proteza jest w pudełku po herbatnikach?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo w kieszeni by się pogniotła, a w szklance nie wypada. Pudełko jest szczelne i ładnie pachnie.", "mina": "mowi"}, {"tekst": "Czy jechałaś z biletem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Dziś nie. Spieszyłam się na wesele i nie skasowałam. Zapłacę mandat, kochanie.", "mina": "emocja"}, {"tekst": "W pudełku jest mandat z dopiskiem Leo: „zdarza się”. Co to?", "ton": "niewygodne", "wymaga": "d13_mandat", "odpowiedz": "Dziecko, emerytura to czterysta dolarów i zęby. Bilet kosztuje tyle co obiad. A Leo to człowiek, więc nie piszcie na niego.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Gdzie jest ślub?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Kościół świętej Łucji, dziesiąta rano. Wnuczka Frida, narzeczony z wąsami jak szczotka. Przysięgam, że ona go kocha.", "mina": "mowi"}, {"tekst": "Po czym poznasz protezę?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Od spodu ma wygrawerowane O.F. Dentysta mówił: żeby ktoś nie zabrał. Nikt nie zabierze, ale grawer został.", "mina": "mowi"}, {"tekst": "Czy rodzina wie, że ją zgubiłaś?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nikt. Córce powiedziałam, że mam przeziębienie i jem zupę. Zęby to rzecz prywatna, dziecko.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co powiesz w kościele bez zębów?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Że uśmiecham się wewnętrznie. Frida się popłacze, ja się popłaczę, a wąsaty zacznie mówić o hipotece.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Odile Faber, z kreską nad „e”, kochanie. Jak ktoś źle napisze, wracam.", "mina": "neutralna"}, {"tekst": "Ile razy jechałaś bez biletu w tym roku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Policzyć? Chyba nie zdążysz, wesele za dwie godziny. Dużo. Ale zawsze z szacunkiem.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję! Frida będzie miała babcię z uśmiechem. Dziecko, jesteś złoto.", "zysk": "Odile idzie na ślub z zębami.", "strata": "Mandat Leo zostaje w pudełku, więc ślad zostaje w jej rękach, nie u ciebie.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Frida Faber: „Babcia wróciła do domu z zębami i opowiedziała całemu weselu, że w biurze rzeczy znalezionych ktoś ma ludzkie serce. Nie wiem, co to znaczy, ale dziękuję.”"}}, {"akcja": "zapisz_mandat", "etykieta": "Wydaj, ale zapisz mandat Leo do księgi", "reakcja": "Zapisujesz? Dziecko, po co. Wpisujcie, co chcecie. Byle zęby były moje.", "zysk": "Mandat jest w księdze, więc Urząd widzi, że konduktor przymyka oko, i masz czyste ręce.", "strata": "Leo oberwie za „zdarza się”, a Odile już nie wsiądzie do szóstki bez bilecika w kieszeni.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Leo Marsh: „Ktoś dopisał moje „zdarza się” do księgi. Przełożony pytał, ile razy mi się zdarzyło. Odpowiedziałem, że ludzie mają zęby.”"}}, {"akcja": "wydaj_i_zniszcz_mandat", "etykieta": "Wydaj i podrzyj mandat przy niej", "reakcja": "Dziecko! Za to dostaniesz ode mnie ciasto. Tylko nie mów Leo, że wiem.", "zysk": "Odile i Leo mają spokój, a ślub toczy się dalej.", "strata": "Niszczysz dokument bez wpisu, a to się liczy jak wydanie po cichu.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Odile Faber: „Przyniosłam ciasto. Nie, dziecko, nie mów nikomu, że to za mandat. Powiedz, że to za ząb.”"}}], "rola": "babcia z protezą na ślub", "watki": ["humor"], "tik": "mówi „dziecko”, „kochanie”", "potrzeba": "proteza przed ślubem o dziesiątej", "slad": "jeździ na gapę i zapisuje mandat", "sprite": "pudelko_blaszane", "face": null, "face2": null, "line": "6", "itemName": "pudełko po herbatnikach", "inside": null}, {"id": "d13_tess", "dzien": 13, "postac": "Tess Rusk, 33", "glos": "Mówi wolno, jakby liczyła słowa. Każde zdanie kończy tak, jakby czekała, aż ktoś ją poprawi. Nie płacze.", "typ": "uczciwa, uparta", "rzecz": "Zielona metalowa skrzynka z dnia trzeciego", "wnetrze": [{"sekret_id": "d13_zegarek_tr", "co_widac": "Na kopercie męskiego zegarka grawer: „T.R. — od T.”. Wskazówki stoją na 23:15, szkiełko ma pęknięcie w rogu.", "co_z_tego_wynika": "Zegarek należał do Tobiasa Rusk. „T.” to Tess, która dała go bratu na trzydzieste urodziny."}, {"sekret_id": "d13_karta_szafki", "co_widac": "W przegródce klucz z mosiężnym numerkiem i karta z numerem szafki, pisanym ołówkiem. Karta jest zgięta w czwórkę, od dawna.", "co_z_tego_wynika": "Brat miał gdzieś szafkę, o której siostra nie wie. Klucz otwiera ją tylko z tą kartą."}], "wejscie": "Tess Rusk. Pytam o zieloną skrzynkę z numerem trzy na wieczku. Leży tu od trzech lat, tak mi powiedziano. Należała do mojego brata Tobiasa. Wyłowili go z kanału, a skrzynki nie znaleźli. Chcę ją zobaczyć.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta skrzynka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zielona, metalowa, z trójką wybitą na wieczku. Zamek zacięty, otwiera się płaskim śrubokrętem. Tobias dostał ją od ojca razem z zawodem.", "mina": "mowi"}, {"tekst": "Gdzie ją zostawił twój brat?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Nie on. Ktoś znalazł ją w tramwaju i oddał tu. Dopiero niedawno zobaczyłam ogłoszenie na słupie i skojarzyłam wieczko.", "mina": "neutralna"}, {"tekst": "Czemu przychodzisz dopiero teraz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo przez trzy lata nie chciałam wiedzieć. Policja powiedziała: wypadek. Dopiero ogłoszenie na słupie ruszyło mnie z miejsca.", "mina": "emocja"}, {"tekst": "Na zegarku jest grawer „T.R. — od T.”. Od kogo?", "ton": "niewygodne", "wymaga": "d13_zegarek_tr", "odpowiedz": "Ode mnie. T. jak Tess, R. jak Rusk. Dałam mu go na trzydzieste urodziny. Nosił na lewej ręce i nigdy nie zdejmował.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Kim był twój brat?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Tobias Rusk, elektryk. Cichy, punktualny, nie pytał o więcej, niż trzeba. Brał nocne zmiany i nigdy nie mówił gdzie.", "mina": "mowi"}, {"tekst": "Co jest w skrzynce poza zegarkiem?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Klucz z numerkiem i karta z numerem szafki. Nie wiem, której. Chcę ją otworzyć sama, zanim ktoś mi powie, co w niej leży.", "mina": "neutralna"}, {"tekst": "Czemu uważasz, że to nie był wypadek?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo Tobias pływał jak ryba. Bo nie miał zegarka, kiedy go znaleźli. Nic z tego nie jest dowodem, a ja się tym żywię.", "mina": "emocja"}, {"tekst": "Na karcie jest numer szafki. Czyja to szafka?", "ton": "niewygodne", "wymaga": "d13_karta_szafki", "odpowiedz": "Brata, tak mi się zdaje. Nie wiem, gdzie stoi. Jeśli wiesz, nie mów na głos. Chcę ją zobaczyć dopiero z kluczem w ręku.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz, jeśli dostaniesz skrzynkę?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zawiozę zegarek do rzeczoznawcy. Chcę papier, że stanął o konkretnej godzinie. Reszta to już nie moja robota, tylko policji.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Tess Rusk. Dwa „s” na końcu nazwiska? Nie, jedno. Podpisuję równo, bo ojciec nauczył.", "mina": "neutralna"}, {"tekst": "Kto jeszcze pytał o tę skrzynkę?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nikt. Dopiero ja. Jeśli ktoś pytał wcześniej, powiedz mi, kto. Naprawdę chcę wiedzieć.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj_tess", "etykieta": "Wydaj skrzynkę Tess", "reakcja": "Dziękuję. Nie zapomnę, że ktoś mi uwierzył na słowo.", "zysk": "Tess dostaje zegarek brata i klucz, a z nimi pierwszy ślad od trzech lat.", "strata": "Skrzynka wychodzi bez ekspertyzy i bez wpisu, a ktoś może zapytać, kto ją wydał.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Tess Rusk: „Otworzyłam szafkę. Pusta, poza kartką z jednym słowem: Kanał. Nie wiem, co to znaczy, ale ktoś tam był przede mną. — T.R.”"}}, {"akcja": "zatrzymaj_ekspertyza", "etykieta": "Zatrzymaj skrzynkę do ekspertyzy zegarka", "reakcja": "Papier? Dobrze. Wolę czekać na papier niż dostać pustą skrzynkę. Ale wrócę.", "zysk": "Zegarek idzie do rzeczoznawcy i masz godzinę, o której stanął.", "strata": "Tess czeka kolejne dni i może przestać Ci ufać.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Tess Rusk: „Ekspertyza. Zegarek stanął o 23:15. Nic mi to nie mówi, ale spisałam sobie tę godzinę. Ty też spisz.”"}}, {"akcja": "odeslij_noah", "etykieta": "Odeślij Tess do Noaha Reyesa", "reakcja": "Policja? Trzy lata temu powiedzieli mi: wypadek. Ale dobrze, spróbuję jeszcze raz.", "zysk": "Sprawa trafia do kogoś, kto prowadzi akta, a Ty nie dotykasz skrzynki.", "strata": "Tess odchodzi z niczym, a skrzynka dalej leży w depozycie bez właściciela.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Noah Reyes: „Przyszła kobieta z pytaniem o wypadek sprzed trzech lat. Czyli: zapisałem. Nie obiecuję, że ktoś to otworzy. — N.R.”"}}], "rola": "siostra zmarłego elektryka", "watki": ["kanal"], "tik": "kończy zdania i czeka na poprawkę", "potrzeba": "skrzynka i zegarek brata, ekspertyza godziny", "slad": "zegarek z grawerem T.R. od T. i klucz", "sprite": "pudelko", "face": null, "face2": null, "line": "6", "itemName": "Zielona metalowa skrzynka z dn", "inside": null}, {"id": "d14_noah", "dzien": 14, "postac": "Noah Reyes, 42", "glos": "Krótko, prosto, ściszonym głosem. Kładzie rzeczy równo z krawędzią lady. Mówi: „Czyli:”.", "typ": "uczciwy, zmęczony", "rzecz": "Czarny organizer w skórze z gumką", "wnetrze": [{"sekret_id": "d14_kartka_oswiadczenie", "co_widac": "W kieszeni organizera kartka z gotowym oświadczeniem i miejscem na podpis do weryfikacji z Mayą. Obok notatka: „Evan: godzina 23:30, ulotki 22:15?”.", "co_z_tego_wynika": "Noah wie, że relacja Evana się nie zgadza, i potrzebuje podpisu Mai, żeby zamknąć sprawę."}], "wejscie": "Noah Reyes, komisariat przy Rynku. Zgubiłem organizer, czarny, w skórze, z gumką. Mam w nim kartkę do podpisu, która ma dojść do Mai Doyle. We wtorek, siódmego września, sprawa idzie wyżej i zaczyna się prawdziwe szukanie.", "wejscie_jesli": {"d11_maya:przez_okienko": "Noah Reyes, komisariat. Zgubiłem organizer, czarny, w skórze, z gumką. Dostałem od was jedno zdanie od Mai, zapisałem słowo w słowo. Teraz potrzebuję czegoś na piśmie, bo do wtorku, siódmego września, sprawa idzie wyżej.", "d11_maya:powiadom_rodzine": "Noah Reyes, komisariat. Zgubiłem organizer, czarny, w skórze, z gumką. Wiem, że Lena wie, że siostra żyje, i że Maya się wycofała. We wtorek, siódmego września, sprawa idzie wyżej, a ja mam tylko puste pole podpisu.", "d11_maya:szept_lenie": "Noah Reyes, komisariat. Zgubiłem organizer, czarny, w skórze, z gumką. Lena Brandt była u mnie i powiedziała, że siostra żyje. Nie powiedziała skąd. Mam kartkę do podpisu i puste pole, więc przyszedłem tutaj."}, "tury": [{"pytania": [{"tekst": "Jak wygląda ten organizer?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, skóra, gumka na grzbiecie. Pół roku noszony, w rogu wytarty na szaro.", "mina": "mowi"}, {"tekst": "Gdzie go zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W szóstce, po dyżurze. Odłożyłem obok termosu i wziąłem termos. Czyli: nie ten sprzęt.", "mina": "neutralna"}, {"tekst": "Co to za kartka do podpisu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Oświadczenie: że Maya żyje, że odeszła z własnej woli i że nie chce kontaktu. Jej podpis załatwia sprawę. Nie mam pewności, że ona to w ogóle widzi.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Od kiedy prowadzisz tę sprawę?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Od czwartku. Mąż przyszedł o 23:30 z prośbą o poszukiwania i zdjęciem w kopercie.", "mina": "mowi"}, {"tekst": "Co jeszcze jest w organizerze?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Terminy, numery, adres Leny Brandt. I kalendarz, w którym wtorek, siódmy września, jest zakreślony na czerwono.", "mina": "neutralna"}, {"tekst": "Czemu relacja Evana ci nie pasuje?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "To moje zmartwienie. Powiem tylko, że ktoś nie mówi mi wszystkiego, a ja wolę pytać cicho.", "mina": "neutralna"}, {"tekst": "W organizerze jest notatka: „Evan: 23:30, ulotki 22:15?”. Co to?", "ton": "niewygodne", "wymaga": "d14_kartka_oswiadczenie", "odpowiedz": "Że ulotki z twarzą żony zamówił godzinę i kwadrans przed zgłoszeniem. Może zbieg okoliczności. Dlatego sam nie szukam jej na siłę.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co się stanie we wtorek, siódmego września?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Sprawa idzie do wydziału, a tam nikt nie pyta, czy ktoś chce być znaleziony. Evan zadzwoni po detektywa. Ponoć za tysiąc dwieście dolarów.", "mina": "mowi"}, {"tekst": "Mogę przekazać Mai tę kartkę?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Tylko jeśli sama przyjdzie. Nie proszę o szukanie, tylko żeby leżała tu na wypadek.", "mina": "neutralna"}, {"tekst": "Czemu tak patrzysz na moją kartę?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo pole nazwiska jest puste. Masz przy sobie jakiś dokument? Nie? Zapisuję: dyżurny, bez nazwiska. W nocy różnie bywa.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "rezerwacja_d22", "etykieta": "Zarezerwuj dla Mai poufną rozmowę na dzień 22", "reakcja": "Czyli: obiecujesz coś w jej imieniu. Dobrze. Jeśli nie przyjdzie, to nie będzie moja wina.", "zysk": "Noah wstrzymuje zgłoszenie do wtorku i daje Mai szansę, żeby sama przyszła.", "strata": "Obiecujesz coś w imieniu Mai, a jeśli się nie pojawi, Noah uzna, że grasz na zwłokę.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Noah Reyes: „Rezerwacja przyjęta. Wpisuję. Czyli: we wtorek o szóstej rano sprawdzam, kto przyszedł.”"}}, {"akcja": "bez", "etykieta": "Zostaw tryb zwykły, bez rezerwacji", "reakcja": "Rozumiem. Czyli sprawa idzie normalnym torem. Nic więcej nie mogę.", "zysk": "Nie obiecujesz nic, czego nie wiesz, i nie ryzykujesz uwiarygodnienia kłamstwa.", "strata": "We wtorek, siódmego września, zgłoszenie idzie wyżej, a detektyw Evana zaczyna szukać.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Noah Reyes: „Czyli: bez rezerwacji. Jeśli do wtorku nic się nie zmieni, sprawa idzie wyżej. Mówię to teraz, żeby potem nikt nie mówił, że nie uprzedzałem.”"}}, {"akcja": "list_od_mai", "etykieta": "Zaproponuj Noahowi, żeby zostawił kartkę w depozycie dla Mai", "reakcja": "Dla Mai, w depozycie. Niech sama zdecyduje, czy podpisze. To uczciwe. Czyli: biorę.", "zysk": "Maya sama wybiera, czy podpisze, a Noah nie naciska.", "strata": "Jeśli Maya nie wróci po kartkę, Noah zostaje z niczym i z żalem do biura.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Noah Reyes: „Kartka leży w depozycie dla Mai D. Nie wiem, czy ktoś ją przeczyta. Wtorek jest blisko. — N.R.”"}}], "rola": "policjant, który zamyka sprawę", "watki": ["Zaginiona"], "tik": "kładzie rzeczy równo z krawędzią", "potrzeba": "podpis Mai do wtorku", "slad": "zapisuje gracza: „dyżurny, bez nazwiska” jako pustkę", "sprite": "organizer", "face": null, "face2": null, "line": "6", "itemName": "organizer", "inside": null}, {"id": "d14_billie", "dzien": 14, "postac": "Billie Cross, 16", "glos": "Szybko, z dumą, rzuca „serio” i „no weź”. Mówi, że ma osiemnaście, i poprawia się dopiero po trzecim pytaniu.", "typ": "wagarowicz, udaje dorosłą", "rzecz": "Różowy kask rowerowy z nalepką", "wnetrze": [{"sekret_id": "d14_legitymacja", "co_widac": "Pod wyściółką kasku wsunięta legitymacja szkolna: Billie Cross, klasa 2B, rocznik 2009. Obok karteczka: „Dziś nie idę. B.”", "co_z_tego_wynika": "Billie ma szesnaście lat i wagaruje. Kłamała o wieku."}], "wejscie": "No hejka, Billie Cross, osiemnaście lat. Zgubiłam kask, różowy, z nalepką z gwiazdką, w czwórce. Zostawiłam go razem z hulajnogą, bo się spieszyłam, a hulajnoga jest w domu. Potrzebuję kasku na jutro, bo mam egzamin.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten kask?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Różowy, z gwiazdką na nalepce, z tyłu pęknięcie, bo spadłam na schodach. No, może dwa razy.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie go zostawiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, w środku, na kolanach. Rozmawiałam przez telefon i nie zauważyłam, że wysiadłam bez niego.", "mina": "neutralna"}, {"tekst": "Jaki egzamin masz jutro?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Taki… z jazdy. Znaczy z fizyki. Eee, poprawny egzamin, wiesz.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Ile masz lat?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Osiemnaście. No, prawie. Siedemnaście? No dobra, szesnaście i pół. Ale dorosła w środku.", "mina": "klamie"}, {"tekst": "Gdzie jesteś w nocy, jak mamy wieczór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na hulajnodze. Jeżdżę tam, gdzie nie ma nauczycieli. Raz spotkałam Leo i dał mi herbatę.", "mina": "mowi"}, {"tekst": "Czemu nie jesteś w domu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo w domu pytają, czemu nie jestem w szkole. A w szkole pytają, czemu nie jestem w domu.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czego potrzebujesz od nas najbardziej?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Kasku. I żebyście nie dzwonili do szkoły, serio. Mam trzy dni nieobecności i bardzo ładne wytłumaczenie.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Billie Cross. Przez dwa „s”, bo tak ładniej. Podpisuję jak dorosła, patrz.", "mina": "neutralna"}, {"tekst": "Co się stanie, jeśli kask zostanie u nas?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy pojadę bez kasku. Wiem, wiem, głupio. Ale lepiej głupio niż pod wzrokiem szkoły.", "mina": "neutralna"}, {"tekst": "Pod wyściółką jest legitymacja szkolna. Czyja?", "ton": "niewygodne", "wymaga": "d14_legitymacja", "odpowiedz": "Moja. Klasa druga B, rocznik dwa tysiące dziewiąty. No dobra, nie kłamię już. Nie dzwońcie.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki, jesteś super! I tak, kask jest mój, mam stos dowodów, tylko że w domu.", "zysk": "Billie odzyskuje kask i nie traci jednej nocy.", "strata": "Wydajesz kask szesnastolatce, która kłamała o wieku, i nikt o tym nie wie.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Billie Cross: „Kask żyje. Mama zapytała, skąd go mam. Powiedziałam, że z biura rzeczy znalezionych i że tam jest miły człowiek. Mama chce cię poznać.”"}}, {"akcja": "wydaj_z_poucz", "etykieta": "Wydaj kask i powiedz jej wprost, że zna prawdę", "reakcja": "No dobra, wiem, wiem. Że wagary, że niebezpiecznie. Mów dalej, zapamiętam połowę.", "zysk": "Billie wie, że ktoś to widzi, i może wrócić, żeby porozmawiać.", "strata": "Billie traci twarz i przestaje opowiadać prawdziwe rzeczy.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Billie Cross: „Poszłam do szkoły. Całe pół dnia. Powiedz Leo, że herbata była lepsza.”"}}, {"akcja": "zadzwon_szkola", "etykieta": "Zadzwoń do szkoły, że uczennica jest na mieście", "reakcja": "Co?! Tylko nie do szkoły! Zabijecie mnie! Dobra, dobra, nie będę już…", "zysk": "Szkoła i rodzice wiedzą, gdzie jest Billie.", "strata": "Billie przestaje przychodzić do biura i znika nocą z hulajnogą po miejscach, gdzie nikt jej nie zna.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Noah Reyes: „Nastolatka z różowym kaskiem była dziś zgłoszona z powodu wagarów. Powiedziała, że okienko ją sprzedało. Czyli: pamięta.”"}}], "rola": "szesnastolatka udająca dorosłą", "watki": ["humor"], "tik": "mówi „serio”, „no weź”", "potrzeba": "kask i święty spokój", "slad": "trzy wersje wieku w jednym zdaniu", "sprite": "czapka_daszek", "face": null, "face2": null, "line": "4", "itemName": "kask", "inside": null}, {"id": "d15_sam", "dzien": 15, "postac": "Sam Holt, 44 i Vera Kovacs, 62", "glos": "Sam: najpierw szczegół techniczny, dopiero po dopytaniu prawda; dziwnie spokojny. Vera: miejsce, rzecz, nazwisko; kluczami dzwoni, kiedy się wstydzi.", "typ": "poprzednik wraca po swoje", "rzecz": "Stalowy zielony termos z wgnieceniem", "ludzie": {"sam": "Sam Holt", "vera": "Vera Kovacs"}, "wnetrze": [{"sekret_id": "d15_termos_notatka", "co_widac": "Na dnie termosu leży zegarek kieszonkowy z kwitem odbioru na imię Sam Holt. Pod zegarkiem kartonik: „Nie pytaj, od czego uciekasz. Nikt nie pyta.”", "co_z_tego_wynika": "Sam zostawiał sobie notatki, które brzmią jak rady dla kogoś innego."}], "wejscie": "Sam Holt. Wezwano mnie po rzeczy z szafki. Zielony termos, stalowy, wgniecenie na pokrywce. Klamra była lewostronna. Vera przyszła ze mną, bo twierdzi, że ktoś ma być przy tym, jak ja tu stoję.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten termos?", "ton": "uprzejme", "wymaga": null, "kto": "sam", "odpowiedz": "Stalowy, zielony, wgnieciony po tym, jak spadł z ciężarówki. Klamra lewostronna, kto robił, myślał o leworęcznych.", "mina": "mowi"}, {"tekst": "Gdzie go zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "kto": "sam", "odpowiedz": "W szafce na zapleczu, ponad miesiąc temu. Vera zabrała całą szafkę razem z termosem, a teraz wszystko trafiło tu.", "mina": "neutralna"}, {"tekst": "Czemu przyszedłeś dopiero teraz?", "ton": "niewygodne", "wymaga": null, "kto": "sam", "odpowiedz": "Bo Vera napisała, że szafkę zamykają. Inaczej bym nie przyszedł. Nie lubię tego miejsca.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Vera, czemu go wezwałaś?", "ton": "uprzejme", "wymaga": null, "kto": "vera", "odpowiedz": "Bo szafkę zamykają, a on przez miesiąc nie przyszedł po nic. Wolałam, żeby ktoś przy tym był.", "mina": "mowi"}, {"tekst": "Czemu wydałeś Thomasowi rękawiczkę bez wpisu?", "ton": "rzeczowe", "wymaga": null, "kto": "sam", "odpowiedz": "Bo to pamiątka, nie zguba. Wpis robi z niej zgubę, a on stracił już dość.", "mina": "emocja"}, {"tekst": "Co się stało ze stroną czterdzieści jeden?", "ton": "niewygodne", "wymaga": null, "kto": "sam", "odpowiedz": "Wyrwałem ją. Wyrwałem, żeby nikt nie miał tych nazwisk. Nie pytaj mnie więcej, bo powiem za dużo.", "mina": "emocja"}, {"tekst": "W szufladzie jest zatwierdzenie z podpisem Victora. Co to?", "ton": "niewygodne", "wymaga": "d15_zatwierdzenie_victora", "kto": "sam", "odpowiedz": "Rozliczenie, które Victor zamknął. Ktoś potem dopisał rzeczy innym tuszem. To nie on, bo on nie zmienia ani przecinka.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czego chcesz od biura?", "ton": "uprzejme", "wymaga": null, "kto": "sam", "odpowiedz": "Termosu, zegarka i spokoju. Referencje z portu mam do piątku, dziesiątego września, bez nich tracę robotę, którą załatwił mi kolega.", "mina": "mowi"}, {"tekst": "Co mam zrobić z kalką?", "ton": "rzeczowe", "wymaga": null, "kto": "sam", "odpowiedz": "Zasłoń nazwiska albo daj mi ją. Jak pokażesz bez zasłony, Nora ma dowód, a czternaście rodzin leży na biurku Urzędu. Wybieraj: oni albo ja. Przykład: Okoye.", "mina": "emocja"}, {"tekst": "Czemu nie chcesz, żeby Victor ją widział?", "ton": "niewygodne", "wymaga": null, "kto": "sam", "odpowiedz": "Bo nie ufam drugiej kopii. Każda kartka, która idzie dalej, trafia do kogoś, kto ją czyta.", "mina": "neutralna"}, {"tekst": "Na kalce jest szósta linia, zaklejona. Co tam jest?", "ton": "niewygodne", "wymaga": "d15_szosta_linia", "kto": "sam", "odpowiedz": "Nie czytaj tego głośno. Ta linia czeka na kogoś i nie wiem jeszcze, jak ci to powiedzieć. Po prostu nie czytaj dalej przy Victorze.", "mina": "emocja"}]}], "decyzje": [{"akcja": "uzgodnij", "etykieta": "Uzgodnij z Samem, Victorowi daj odpis z zasłoniętymi danymi", "kto": "sam", "reakcja": "Zasłonięte. Dobrze. Nikt nie powie, że nie próbowałem. Dziękuję.", "zysk": "Sam zostaje po twojej stronie, a ludzie z listy nie trafiają do Urzędu.", "strata": "Dowód słabnie: bez nazwisk Nora nie wygra z Iris.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Sam Holt: „Nazwiska zasłonięte. Tego się nie zapomina. Dziękuję. — S.H.”"}}, {"akcja": "victor_od_razu", "etykieta": "Przekaż kalkę Victorowi od razu, bez zasłaniania", "kto": "sam", "reakcja": "Zrobione. Od teraz jestem w papierach i nie mam już nic do dodania.", "zysk": "Mocny dowód: Victor ma pełną kalkę i zatwierdzenie z dopiskami.", "strata": "Czternaście rodzin trafia do Urzędu, a Sam wycofuje zgodę i przestaje ci ufać.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Victor Crane: „Kalka przyjęta. Pełny egzemplarz. Wiem, że to nie wszystkim się spodoba, ale dowód jest dowodem.”"}}, {"akcja": "oddaj_samowi", "etykieta": "Oddaj kalkę Samowi, bez kopii", "kto": "sam", "reakcja": "Dziękuję. Spalę ją, zanim się rozmyślę. Nikt jej nie zobaczy, i tak będzie lepiej.", "zysk": "Sam zachowuje spokój, a ludzie z kalki są bezpieczni.", "strata": "Nie ma żadnego dowodu przeciw Iris ani przeciw Victorowi, a Nora zostaje z pustymi rękami.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Sam Holt: „Spaliłem. Nie pytaj, gdzie. Jeśli cię ktoś zapyta o kalkę, powiedz, że jej nie było. — S.H.”"}}], "rola": "poprzednik, który wraca po swoje", "watki": ["Poprzednik", "Skrytka", "Fotel"], "tik": "zaczyna od szczegółu technicznego", "potrzeba": "referencje i spokój do piątku", "slad": "kalka strony 41 z szóstą linią", "sprite": "termos", "face": null, "face2": {"sam": null, "vera": null}, "line": "6", "itemName": "termos", "inside": {"img": "W13", "x": 0.3, "y": 0.2}}, {"id": "d15_pruitt", "dzien": 15, "postac": "Pan Pruitt, 80", "glos": "Spokojnie, żartobliwie, z pretensją do całego świata. Zawsze „przy okazji”. Mówi do parasoli.", "typ": "oddający, samotny", "rzecz": "Jedenaście parasoli w siatce na zakupy", "wnetrze": [{"sekret_id": "d15_pruitt_kartka", "co_widac": "Do siatki przypięta kartka z jedenastoma linijkami. Przy każdym parasolu miejsce i dzień znalezienia. Przy jednym dopisek: „Ulubiony, E.W. na rączce.”", "co_z_tego_wynika": "Pruitt prowadzi własną ewidencję znalezionych parasoli i zna je po imieniu, więc oddaje nie bez powodu."}], "wejscie": "Pruitt, osiemdziesiąt lat. Przyszedłem oddać parasole. Jedenaście, znalezionych w tym tygodniu. Niczyich, bo nikt po nie nie przyszedł, więc wszystko jest w porządku. Można je gdzieś położyć?", "tury": [{"pytania": [{"tekst": "Skąd masz te parasole?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Z pętli, ławek, kratek na przystankach. W tym tygodniu padało, ludzie zostawiają. Ja zbieram, bo parasol bez człowieka jest smutny.", "mina": "mowi"}, {"tekst": "Czemu dopiero teraz je oddajesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo wcześniej były krótsze. Dziś jest ich jedenaście, a jedenastka to ładna liczba. Poza tym nikt nie pytał, a ja nie narzucam się.", "mina": "mowi"}, {"tekst": "Dlaczego zbierasz parasole?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo ktoś musi. Moja żona zawsze mówiła, że człowiek, który nie oddaje cudzych rzeczy, nie powinien mieć własnych.", "mina": "emocja"}, {"tekst": "Do siatki przypięta jest kartka z miejscami. Po co ją prowadzisz?", "ton": "niewygodne", "wymaga": "d15_pruitt_kartka", "odpowiedz": "Żeby wiedzieć, skąd który. Człowiek, który wraca po parasol, zawsze mówi: na pętli. A ja wiem, na której i o której. To też jest kwit.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Który parasol jest najstarszy?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Ten czarny, z drewnianą rączką, z siedemdziesiątego dziewiątego. Ma krzywą szprychę. Nie oddaję go, tylko przy okazji pokazuję.", "mina": "mowi"}, {"tekst": "Co robisz, jak ktoś jednak przyjdzie po parasol?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Wydaję z uśmiechem, bez pytań. Raz przyszła kobieta po parasol w kwiatki i płakała ze szczęścia. Nie wiem dlaczego, ale było miło.", "mina": "mowi"}, {"tekst": "Czy ktoś kiedykolwiek przyszedł po parasol?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Dwa razy w tym roku. Pozostałe dziewięć czeka. Nikt nie przychodzi, więc wszystko w porządku. Tak sobie mówię.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co mam z nimi zrobić?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Położyć gdzieś, gdzie nie zmokną. Niech czekają, jak ja. Nie lubię, jak się marnują.", "mina": "mowi"}, {"tekst": "Podpiszesz zdanie zbiorcze?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Pruitt. Bez imienia, tak jak mnie wołają. Jedenaście sztuk, każda z numerkiem. Mam kredę.", "mina": "neutralna"}, {"tekst": "Czemu nie zostawisz ich na przystanku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo mokną, bo wiatr, bo wredni ludzie. I bo gdybym zostawił, nie miałbym po co tu przychodzić.", "mina": "emocja"}]}], "decyzje": [{"akcja": "przyjmij_wpis", "etykieta": "Przyjmij wszystkie i wpisz je do księgi, po jednym", "reakcja": "Jedenaście pozycji! Dziękuję, to się nazywa porządek.", "zysk": "Parasole są w księdze i mogą wrócić do właścicieli, jeśli ktoś przyjdzie.", "strata": "Zajmuje to dziesięć minut zmiany, a kolejka rośnie.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Pruitt: „Przyszła kobieta po parasol w kwiatki. Płakała. Powiedziałem jej, że wpisaliście wszystko. Chyba nie wie, jak ładnie to brzmi.”"}}, {"akcja": "przyjmij_bez_wpisu", "etykieta": "Przyjmij parasole bez wpisu, żeby nie tracić czasu", "reakcja": "Dziękuję. Oby nie zmokły. I niech nikt nie pyta, skąd się wzięły.", "zysk": "Oszczędzasz czas, a Pruitt odchodzi uśmiechnięty.", "strata": "Rzeczy leżą w biurze bez śladu w księdze, a licznik „bez wpisu” rośnie.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Pruitt: „Szukałem parasola w kwiatki w waszej księdze, ale go tam nie było. Może to wina mojego wzroku.”"}}, {"akcja": "odeslij", "etykieta": "Odeślij Pruitta na komisariat z parasolami", "reakcja": "Na komisariat? W moim wieku? Dobrze. Parasole poczekają na deszcz.", "zysk": "Zyskujesz dziesięć minut i nie zaśmiecasz biura.", "strata": "Pruitt wraca do domu z jedenastoma parasolami i znowu nikt do niego nie przychodzi.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Pruitt: „Wróciłem z parasolami do domu. Postawiłem je w przedpokoju. Chyba się obraziły. — P.”"}}], "rola": "samotnik z parasolami", "watki": ["humor"], "tik": "mówi „przy okazji”", "potrzeba": "ktoś, kto przyjmie parasole", "slad": "oddaje parasole, żeby było do kogo gadać", "sprite": "parasol", "face": null, "face2": null, "line": "11", "itemName": "parasole", "inside": null}, {"id": "d16_maya_lena", "dzien": 16, "postac": "Maya Doyle i Lena Brandt", "glos": "Maya: precyzyjnie, liczy do trzech. Lena: szybko, urywa „ale…”, mówi za dużo.", "typ": "dwie siostry, jedno okienko", "rzecz": "Granatowa saszetka podróżna", "ludzie": {"maya": "Maya Doyle", "lena": "Lena Brandt"}, "wnetrze": [{"sekret_id": "d16_kartka_walizka", "co_widac": "W jednej przegródce dwa żetony bagażowe i kartka pisana równym pismem Mai: „Lena: jedna rzecz. Walizkę do czwórki, wtorek, 6:10. Jak wybierzesz ją zamiast mnie, nie przyjdę.”", "co_z_tego_wynika": "Maya prosi siostrę o jedną rzecz i zostawia warunek."}, {"sekret_id": "d16_najem_lena", "co_widac": "W drugiej przegródce potwierdzenie najmu mieszkania na nazwisko Mai, podpisane przez Lenę tydzień temu.", "co_z_tego_wynika": "Lena załatwiła już przeprowadzkę, o której Maya nie wiedziała."}], "wejscie": "Maya Doyle. Zostawiłam w jedenastce granatową saszetkę podróżną. Obok stoi Lena, moja siostra, i mówi, że saszetka jest jej. To nieprawda. Chcę ją odebrać sama i powiedzieć Lenie jedną rzecz.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta saszetka?", "ton": "uprzejme", "wymaga": null, "kto": "maya", "odpowiedz": "Granatowa, na zamek, z haftem w rogu: M.D. Dwie przegródki: w jednej rzeczy podróżne, w drugiej papiery.", "mina": "mowi"}, {"tekst": "Lena, czemu twierdzisz, że to twoja saszetka?", "ton": "rzeczowe", "wymaga": null, "kto": "lena", "odpowiedz": "Bo ją kupiłam. Na podróż dla Mai, tydzień temu. Maya ją zgubiła, a ja przyszłam sprawdzić, czy biuro ją ma.", "mina": "emocja"}, {"tekst": "Czemu przyszłyście razem?", "ton": "niewygodne", "wymaga": null, "kto": "maya", "odpowiedz": "Po raz pierwszy w kolejce. Nie planowałam tego. Lena stanęła za mną, a ja policzyłam: raz, dwa, trzy. Zostałam.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Maya, co chcesz powiedzieć siostrze?", "ton": "uprzejme", "wymaga": null, "kto": "maya", "odpowiedz": "Że przestała mnie ratować. Pomogła, dziękuję. Ale od tygodnia decyduje, gdzie mam spać i z kim rozmawiać.", "mina": "mowi"}, {"tekst": "Lena, czego chcesz od Mai?", "ton": "rzeczowe", "wymaga": null, "kto": "lena", "odpowiedz": "Żeby powiedziała, gdzie jest. Ale… chcę tylko wiedzieć, czy bezpieczna. Naprawdę tylko tyle.", "mina": "emocja"}, {"tekst": "Co jest w drugiej przegródce?", "ton": "niewygodne", "wymaga": null, "kto": "maya", "odpowiedz": "Karteczka dla Leny i dwa żetony bagażowe. Walizka jest w depozycie, ale nie tu. Dlatego te żetony.", "mina": "neutralna"}, {"tekst": "Jest tu potwierdzenie najmu mieszkania na nazwisko Mai. Czyje?", "ton": "niewygodne", "wymaga": "d16_najem_lena", "kto": "lena", "odpowiedz": "Moje. To znaczy… ja załatwiłam. Tydzień temu. Chciałam jej zrobić niespodziankę. Ale… ona o tym nie wiedziała.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co chcesz, żeby Lena zrobiła?", "ton": "uprzejme", "wymaga": null, "kto": "maya", "odpowiedz": "Jedną rzecz. Odwieźć walizkę do tramwaju we wtorek o 6:10. Tylko to, nic więcej.", "mina": "mowi"}, {"tekst": "Czy wtorek jest pewny?", "ton": "rzeczowe", "wymaga": null, "kto": "maya", "odpowiedz": "Jeśli Lena wybierze mnie, a nie siebie, przyjdę. Jak wybierze siebie, nie przyjdę. Kto odbiera ważną rzecz, sprawdza okienko trzy razy. Dziś drugi raz.", "mina": "neutralna"}, {"tekst": "Lena, czemu załatwiłaś mieszkanie bez pytania?", "ton": "niewygodne", "wymaga": null, "kto": "lena", "odpowiedz": "Bo… bo wiedziałam, że ona nie poprosi. Ale… ona ma prawo… tak, wiem. Muszę przestać planować.", "mina": "emocja"}]}], "decyzje": [{"akcja": "maya_sama", "etykieta": "Pozwól Mai powiedzieć to siostrze osobiście", "kto": "maya", "reakcja": "Raz. Dwa. Trzy. Tak. Lena, słuchaj. Przestań decydować, a ja przyjdę we wtorek.", "zysk": "Maya zachowuje sprawczość i zalicza ci drugi test zaufania.", "strata": "Lena ma żal, że usłyszała to w kolejce, a nie w domu.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Lena Brandt: „Maya powiedziała mi to przy okienku. Pierwszy raz od dwóch lat nie przerwałam. Dziękuję, że wybór został przy nas. — L.”"}}, {"akcja": "lena_zalatwia", "etykieta": "Oddaj saszetkę Lenie do załatwienia", "kto": "lena", "reakcja": "Ale… dobrze. Wszystko załatwię. Maya… no właśnie. Nie patrz tak.", "zysk": "Lena dostaje rolę i czuje się potrzebna.", "strata": "Maya wycofuje zgodę na pośrednictwo i traci zaufanie do okienka.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Maya Doyle: „Saszetka wróciła do Leny. Policzyłam: raz, dwa, trzy. Wiem, co zrobię. Nie we wtorek.”"}}, {"akcja": "bez_decyzji", "etykieta": "Zatrzymaj saszetkę, niech siostry same się dogadają", "reakcja": "Rozumiem. Raz, dwa, trzy. Zostaje u was. Wrócę, jak będzie czas.", "zysk": "Nikt nie wygrywa i nikt nie traci twarzy.", "strata": "Maya nie dostaje swojej rzeczy, a Lena planuje dalej bez pytania.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Lena Brandt: „Saszetka leży u was. Pytałam Mai, czy to dobrze. Powiedziała: policzyłam. Nie wiem, co to znaczy, ale mi odpowiedziała.”"}}], "rola": "dwie siostry przy saszetce", "watki": ["Zaginiona", "Fotel"], "tik": "Maya liczy, Lena mówi „ale…”", "potrzeba": "saszetka i jedno zdanie siostry", "slad": "drugi test Mai: wybór zostaje jej", "wejscie_jesli": {"d11_maya:przez_okienko": "Maya Doyle. Zostawiłam w jedenastce granatową saszetkę podróżną. Noah dostał ode mnie jedno zdanie, więc wiem, że to biuro umie milczeć. Obok stoi Lena i mówi, że saszetka jest jej. To nieprawda. Chcę ją odebrać sama i powiedzieć Lenie jedną rzecz.", "d11_maya:powiadom_rodzine": "Maya Doyle. Zostawiłam w jedenastce granatową saszetkę podróżną. Lena wie, że żyję, bo biuro jej to powiedziało, choć nie prosiłam. Stoi obok i mówi, że saszetka jest jej. To nieprawda. Chcę ją odebrać sama i powiedzieć Lenie jedną rzecz.", "d11_maya:szept_lenie": "Maya Doyle. Zostawiłam w jedenastce granatową saszetkę podróżną. Lena wie, że żyję, bo ktoś jej to szepnął, i wiem, że nie ja. Stoi obok i mówi, że saszetka jest jej. To nieprawda. Chcę ją odebrać sama i powiedzieć Lenie jedną rzecz."}, "sprite": "saszetka", "face": null, "face2": null, "line": "11", "itemName": "Granatowa saszetka podróżna", "inside": null}, {"id": "d16_dorian", "dzien": 16, "postac": "Dorian Lund, 45", "glos": "Cicho, z ironią, cytuje tytuły piosenek zamiast odpowiedzi. Nigdy nie mówi, od czego ucieka.", "typ": "uczciwy, boi się", "rzecz": "Pudełko po kasecie magnetofonowej z ręcznie podpisaną kasetą", "wnetrze": [{"sekret_id": "d16_kaseta_0731", "co_widac": "Pod pasiastą naklejką na kasecie wsunięta karteczka z numerem 0731 i dopiskiem „kasetowiec”.", "co_z_tego_wynika": "To numer z piórnika Iris. Dorian jest jedną z czterech osób z papierami."}], "wejscie": "Dorian Lund. Zgubiłem kasetę, ręcznie podpisaną, w pudełku. Jedenastka, ostatni kurs. Nie jest wartościowa, tylko moja. Jeśli się znajdzie, proszę przechować do soboty. Nie dam rady odebrać wcześniej.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta kaseta?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Przezroczysta, z pasiastą naklejką i podpisem długopisem: „na pożegnanie”. W pudełku z zielonym grzbietem.", "mina": "mowi"}, {"tekst": "Gdzie ją zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, na ostatnim siedzeniu przy tylnych drzwiach. Trzymałem w ręku, a potem wysiadłem bez niej. Takie życie.", "mina": "neutralna"}, {"tekst": "Co jest nagrane na tej kasecie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Piosenka. Jedna, ile razy, tyle razy. Nie powiem którą, to osobiste.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czemu jej szukasz tak późno?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Bo wcześniej nie wiedziałem, że zniknęła. A dziś wiem, że jutro bym płakał.", "mina": "emocja"}, {"tekst": "Czemu przechować do soboty?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo w sobotę mam coś do załatwienia. Wolałbym nie mieć jej wtedy przy sobie.", "mina": "neutralna"}, {"tekst": "Od czego uciekasz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Od ludzi, którzy pytają, czemu nie dzwonię. Ale to moja sprawa.", "mina": "emocja"}, {"tekst": "Pod naklejką jest karteczka z numerem 0731. Co to?", "ton": "niewygodne", "wymaga": "d16_kaseta_0731", "odpowiedz": "To mój numer. Nie pytaj. Naprawdę. Tak się zaczęło i nie wiem, jak skończyć.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czego potrzebujesz od biura?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Spokoju do soboty. I żeby nikt nie pytał o mnie wprost. Pokwitowanie niech będzie na kasetę, nie na człowieka.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "D. Lund. Samo D., jeśli można. Jak nie, to Dorian, bez nazwiska.", "mina": "neutralna"}, {"tekst": "Czemu boisz się kwitu z nazwiskiem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo kwit trafia do księgi, a księga do tych, którzy potrafią czytać.", "mina": "emocja"}]}], "decyzje": [{"akcja": "przechowaj_z_kwitem", "etykieta": "Przechowaj do soboty i wystaw kwit na kasetę", "reakcja": "Dobrze. „Nie ma jak w domu.” Czyli nie. Wystaw. Przyjdę w sobotę.", "zysk": "Kaseta jest bezpieczna, a w księdze zostaje ślad kasety, nie człowieka.", "strata": "Zajmuje to jedno miejsce w depozycie i księga mówi, że ktoś tu był.", "echo": {"za_dni": 4, "forma": "gosc", "tekst": "Dorian Lund: „Odebrałem kasetę. Niczego nie zostawiłem. Dziękuję, że nikt nie zapytał, od czego uciekam.”"}}, {"akcja": "przechowaj_bez_kwitu", "etykieta": "Przechowaj do soboty bez kwitu", "reakcja": "Dziękuję. Nie ma śladu, nie ma problemu. Cicho jak mysz.", "zysk": "Dorian zostaje poza księgą i czuje się bezpieczny.", "strata": "Rzecz leży bez wpisu, a licznik „bez wpisu” rośnie.", "echo": {"za_dni": 4, "forma": "gosc", "tekst": "Dorian Lund: „Kaseta wróciła. Nikt nie wie, że tu byłem. Chyba po raz pierwszy od roku to się liczy.”"}}, {"akcja": "odmow", "reakcja": "Rozumiem. „Nie ma lekko.” Muszę poszukać innego miejsca.", "zysk": "Nie ryzykujesz układu i nie zostawiasz nic bez śladu.", "strata": "Dorian traci jedyną szansę na przechowanie i idzie dalej bez kasety.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Dorian Lund: „Poszedłem szukać innego okienka. Nie znalazłem. Kaseta gdzieś jedzie beze mnie.”"}}], "rola": "kasetowiec, który boi się wyjechać", "watki": ["Skrytka"], "tik": "cytuje tytuły piosenek", "potrzeba": "kaseta i cisza do soboty", "slad": "żeton 0731 w pudełku po kasecie", "sprite": "pudelko_blaszane", "face": null, "face2": null, "line": "11", "itemName": "Pudełko po kasecie magnetofono", "inside": null}, {"id": "d17_evan", "dzien": 17, "postac": "Evan Doyle, 37", "glos": "Grzecznie, pełnymi zdaniami, wraca do tego samego pytania. Poprawia mankiet, dziś wygnieciony do połowy.", "typ": "mąż, który trzyma się planu", "rzecz": "Etui na aparat z zamkniętym listem", "wnetrze": [{"sekret_id": "d17_data_listu", "co_widac": "Na kopercie z listem data sprzed dwudziestu sześciu dni. Wewnątrz notatka: „Wiem, że chcesz odejść. Proszę, odpisz.”", "co_z_tego_wynika": "Evan wiedział o odejściu Mai, zanim zgłosił jej zaginięcie."}], "wejscie": "Dobry wieczór. Evan Doyle. Zostawiłem w czwórce czarne etui na aparat, a w nim list do żony. Detektyw jest opłacony, zaliczka poszła w zeszłym tygodniu. Po wtorku dostanie pełnomocnictwo i pójdzie do Urzędu po wgląd. Wolałbym nie musieć.", "tury": [{"pytania": [{"tekst": "Jak wygląda to etui?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarne, skórzane, z miękką podszewką. W środku stary aparat i list. Aparat jest jej, od teścia.", "mina": "mowi"}, {"tekst": "Gdzie je zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, na siedzeniu przy oknie. Jechałem do niej, a właściwie na pętlę, jak ostatnio. Odłożyłem i zapomniałem.", "mina": "neutralna"}, {"tekst": "Czemu piszesz list, zamiast zadzwonić?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo ona nie odbiera. I tak sobie myślę, że list jest poważniejszy. Zamyka sprawę albo ją otwiera.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Co jest w liście?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Prośba, żeby odpisała. Adres zwrotny, mój numer i jedno zdanie: „Wiem, że byłem niesprawiedliwy.” Nic więcej.", "mina": "mowi"}, {"tekst": "Ile detektyw naprawdę kosztuje?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Tysiąc dwieście dolarów. Zaliczka poszła w zeszłym tygodniu. Powiedział, że w trzy dni znajdzie każdego, a po wtorku pójdzie do Urzędu po wgląd w kopie.", "mina": "neutralna"}, {"tekst": "Dlaczego uważasz, że żona potrzebuje ratunku?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo nikt dobrowolnie nie zostawia wszystkiego. Przynajmniej nikt rozsądny. Takie jest moje przekonanie.", "mina": "klamie"}, {"tekst": "Na kopercie jest data sprzed dwudziestu sześciu dni. Co to znaczy?", "ton": "niewygodne", "wymaga": "d17_data_listu", "odpowiedz": "Że list napisałem wcześniej, niż zgłosiłem zaginięcie. Usłyszałem „odchodzę”. Nie zgłosiłem tego, bo ktoś by powiedział, że to jej wybór.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz, jeśli Maya nie odpisze?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Przyjdę jeszcze raz. I jeszcze raz. Ale nie z pretensją, tylko z kopertą, która czeka.", "mina": "mowi"}, {"tekst": "Odbiór wymaga podpisu. Podpiszesz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Evan Doyle. Z kropką po „E”. Zawsze.", "mina": "neutralna"}, {"tekst": "Czemu mankiet masz dziś pomięty?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo ręce mi się trzęsą. Zwykle prasuję. Dziś nie miałem siły, a to już jest informacja.", "mina": "emocja"}]}], "decyzje": [{"akcja": "zostaw_zamkniety", "etykieta": "Zostaw list zamknięty dla Mai, bez obietnicy odpowiedzi", "reakcja": "Dla niej. Zamknięty. Niech ona zdecyduje. Rozumiem… no dobrze. Szansa jedna.", "zysk": "Evan ma jedną szansę, a Maya sama wybiera, czy otworzy list.", "strata": "Evan nie dostaje obietnicy i może zadzwonić do detektywa.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Evan Doyle: „Zostawiłem list. Nie wiem, czy dotrze. Jeżeli nie odpisze do wtorku, siódmego września, detektyw dostanie pełnomocnictwo i pójdzie do Urzędu. — E.D.”"}}, {"akcja": "odmow", "reakcja": "Odmowa pośrednictwa? Dobrze. Pójdę do Leny z pretensjami. Mam takie prawo.", "zysk": "Czysto: nie angażujesz się w sprawę małżonków.", "strata": "Evan idzie do Leny z pretensjami, a Maya traci spokój.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Lena Brandt: „Evan stał pod moimi drzwiami przez godzinę. Nie otworzyłam. Powiedział, że to wasza wina. Nie wiem, co to znaczy. — L.”"}}, {"akcja": "zdradz_szczegol", "etykieta": "Zdradź Evanowi jeden szczegół o Mai", "reakcja": "Naprawdę? Dziękuję. Zapiszę. To pierwszy raz, kiedy ktoś mi coś powiedział. Kto wie, może jeszcze odzyskam.", "zysk": "Evan odzyskuje nadzieję i przestaje naciskać na biuro.", "strata": "Maya traci poczucie bezpieczeństwa, a detektyw dostaje ślad.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Maya Doyle: „Evan wie, że byłam w czwórce o 22:40. Skąd? Policzyłam: raz, dwa, trzy. Ktoś mu powiedział. Przestaję wierzyć szybie.”"}}], "rola": "mąż, który trzyma się planu", "watki": ["Zaginiona"], "tik": "poprawia mankiet", "potrzeba": "żeby żona wróciła albo odpisała", "slad": "wspomina detektywa za 1 200 $", "wejscie_jesli": {"d16_maya_lena:lena_zalatwia": "Dobry wieczór. Evan Doyle. Lena mówi, że zajęła się wszystkim i żebym nie przychodził. Przyszedłem po czarne etui na aparat, w nim list do żony. Detektyw jest opłacony, po wtorku pójdzie do Urzędu po wgląd. Wolałbym nie musieć.", "d16_maya_lena:maya_sama": "Dobry wieczór. Evan Doyle. Słyszałem, że Maya odebrała coś sama, a Lena się cofnęła. Nie wiem, gdzie żona. Zostawiłem w czwórce czarne etui na aparat, a w nim list. Detektyw jest opłacony, po wtorku pójdzie do Urzędu po wgląd."}, "sprite": "aparat", "face": null, "face2": null, "line": "4", "itemName": "Etui na aparat z zamkniętym li", "inside": null}, {"id": "d17_sylvia", "dzien": 17, "postac": "Sylvia Okafor, 52", "glos": "Spokojnie, z nauczycielską ironią. Zdania rzuca jak pionki: po jednym ruchu.", "typ": "uczciwa, zagrywa", "rzecz": "Drewniane szachy bez króla", "wnetrze": [{"sekret_id": "d17_koperta_klasy", "co_widac": "W kieszonce pudełka koperta z napisem „wycieczka 3b” i sto dwadzieścia dolarów w banknotach, zwrot od rodziców.", "co_z_tego_wynika": "To pieniądze dzieci, nie Sylvii. Jeśli zginą, zapłaci z własnej pensji."}], "wejscie": "Sylvia Okafor, nauczycielka. Zgubiłam szachy, drewniane, składane. Nie ma w nich białego króla. Szukam całości, ale też tego jednego pionka, którego brakuje, bo dzieci się o niego kłócą.", "tury": [{"pytania": [{"tekst": "Jak wyglądają te szachy?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Składana plansza, pionki wyrzeźbione ręcznie, trochę nierówne. Białego króla nie ma od lutego. Dzieci twierdzą, że gra się ciekawiej.", "mina": "mowi"}, {"tekst": "Gdzie je zostawiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwórce, po zajęciach. Położyłam pudełko obok i zaczęłam rozmawiać z kierowcą o remoncie. Wysiadłam, a szachy jechały dalej.", "mina": "neutralna"}, {"tekst": "Czemu gracie bez króla?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo uczę, że gra toczy się dalej, nawet jeśli czegoś brakuje. Zwykle dzieci rozumieją to szybciej niż dorośli.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Czego uczysz dzieci?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szachów, logiki i cierpliwości. Cierpliwość idzie najgorzej. Uczę też, że czasem trzeba poświęcić hetmana.", "mina": "mowi"}, {"tekst": "Czy ktoś wie, gdzie jest król?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Nie wiem. Zgubił się w lutym, jeszcze w klasie. Dzieciom powiedziałam, że wyjechał na urlop. Uwierzyły.", "mina": "mowi"}, {"tekst": "Czy brak króla to kłopot?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Czasem. Przeciwnik zawsze wie, czego nie masz. Ale zwykle nie wie, co z tym zrobisz.", "mina": "neutralna"}, {"tekst": "W pudełku jest koperta „wycieczka 3b”. Co to?", "ton": "niewygodne", "wymaga": "d17_koperta_klasy", "odpowiedz": "Pieniądze rodziców, sto dwadzieścia dolarów. Zapomniałam, że je tam włożyłam. Jak zginą, zapłacę z pensji, a ja nie mam z czego.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz, jak je odzyskasz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zagram z kimś, kto nie zna zasad. To zawsze interesujące.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "S. Okafor. Przez „k”, nie „c”. Dzieci pytają, czy to szachowy skrót.", "mina": "neutralna"}, {"tekst": "Czy to ważne, że szachy wróciły?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Dla mnie to tylko pionki. Dla dzieci to pierwsze wrażenie, że rzeczy wracają.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Dzieci się ucieszą. A ja wrócę do mówienia, że hetmana nie wolno tracić bez powodu.", "zysk": "Sylvia odzyskuje szachy, a dzieci grają dalej.", "strata": "Wydajesz bez żadnego dowodu poza opisem, który zgadza się z rzeczą.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Sylvia Okafor: „Zagraliśmy bez króla w trzy osoby. Wygrał najmłodszy. Powiedział: „Ja nie miałem czego tracić.” Zapisałam.”"}}, {"akcja": "wydaj_z_dopiskiem", "etykieta": "Wydaj i dołóż dopisek: „kto czeka na króla, ten gra dalej”", "reakcja": "Dopisek? Ha. To wyśle się w ślad za nimi jako lekcja. Dziękuję.", "zysk": "Sylvia dostaje coś, co może powiesić w klasie.", "strata": "Dopisek w księdze może komuś zabrzmieć jak zaszyfrowana wiadomość.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Sylvia Okafor: „Dopisek wisi nad tablicą. Dzieci pytają, co to znaczy. Odpowiedziałam: to znaczy, że ktoś gdzieś czeka. — S.O.”"}}, {"akcja": "odmow", "reakcja": "Rozumiem. Gdyby ktoś jeszcze miał pytania, wiem, gdzie szachy się kończą.", "zysk": "Szachy zostają w biurze do potwierdzenia.", "strata": "Dzieci grają dziś bez planszy, a Sylvia dostaje zaległą naganę.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Sylvia Okafor: „Dzieci grały na kartkach. Skrzywione, ale wygrały. Na przyszłość zastanowię się, czy biuro też tak gra.”"}}, {"akcja": "wez_120_wycieczka", "etykieta": "Zatrzymaj 120 $ z koperty „wycieczka 3b”", "kasa": 120, "wymaga": "d17_koperta_klasy", "reakcja": "Szachy są? Dobrze. A koperta? Przecież… zaraz. Nie. Nic. Zapomniałam, co chciałam powiedzieć.", "zysk": "120 $ w kieszeni i dług u Marlowa o dwie raty mniejszy.", "strata": "Dzieci tracą wycieczkę albo Sylvia dopłaca z pensji. Wpis liczy się do zakończenia Nowy Sam.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Sylvia Okafor: „Wycieczka odwołana. Sprawdzałam trzy razy, bo wolę wierzyć, że sama się pomyliłam. Dzieci pytają, czemu nic nie wyszło.”"}}], "rola": "nauczycielka z szachami bez króla", "watki": ["humor", "pieniądze"], "tik": "mówi pionkami", "potrzeba": "szachy dla dzieci", "slad": "koperta z pieniędzmi wycieczki 3b w pudełku", "sprite": "pudelko", "face": null, "face2": null, "line": "4", "itemName": "Drewniane szachy bez króla", "inside": null}, {"id": "d18_iris_nora", "dzien": 18, "postac": "Iris Bell i Nora Vance", "glos": "Iris: cicho, uprzejmie, „nie lubię naciskać”, groźbę podaje jak prognozę pogody. Nora: po kolei, rzecz-osoba-skutek.", "typ": "dwie kobiety, jedna teczka", "rzecz": "Teczka budowlana z planem kamienicy", "ludzie": {"iris": "Iris Bell", "nora": "Nora Vance"}, "wnetrze": [{"sekret_id": "d18_plan_wyburzenia", "co_widac": "W teczce plan Cooper Street 9 z czerwonym dopiskiem „do wyburzenia” i lista terminów rozliczenia zaliczek: czwartek, dziewiąty września, podkreślony dwa razy.", "co_z_tego_wynika": "Cały dom idzie pod rozbiórkę, a termin rozliczenia zaliczek jest ostateczny. Lokatorzy nie mają zapasu."}], "wejscie": "Dobry wieczór. Iris Bell, a obok Nora Vance. Teczka budowlana, szara, zgubiona w szóstce. Są w niej plan kamienicy i lista terminów. Nora ją zna, ja ją znam. Chcemy ją odebrać. Z różnych powodów.", "wejscie_jesli": {"d12_iris_nora:wydaj_iris": "Dobry wieczór. Iris Bell i Nora Vance. Teczka budowlana, szara, zgubiona w szóstce. Plan kamienicy i lista terminów. Kasetkę biuro wydało już jakiś czas temu, więc dziś chcemy tylko teczkę. Z różnych powodów.", "d12_iris_nora:zabezpiecz": "Dobry wieczór. Iris Bell i Nora Vance. Teczka budowlana, szara, zgubiona w szóstce. Oryginały leżą u was w depozycie, a my przyszłyśmy po resztę: plan kamienicy i listę terminów. Z różnych powodów.", "d12_iris_nora:sprawdz_z_nora": "Dobry wieczór. Iris Bell i Nora Vance. Teczka budowlana, szara, zgubiona w szóstce, plan kamienicy i lista terminów. Kasetkę liczyłyśmy wspólnie, każdy numer ma dwa podpisy, więc dziś nie walczymy o nią. Teczka to druga sprawa. Z różnych powodów.", "d12_iris_nora:wyloz_400": "Dobry wieczór. Iris Bell i Nora Vance. Teczka budowlana, zgubiona w szóstce, plan kamienicy i lista terminów. Nora ma od Was czterysta dolarów dla Okoye, a oryginały nadal ma Iris. Chcemy teczkę. Z różnych powodów."}, "tury": [{"pytania": [{"tekst": "Co jest w tej teczce?", "ton": "uprzejme", "wymaga": null, "kto": "iris", "odpowiedz": "Plan Cooper Street dziewięć z dopiskiem „do wyburzenia” i lista terminów rozliczenia zaliczek. Nic ciekawego, dla mnie to papier, dla lokatorów los.", "mina": "mowi"}, {"tekst": "Nora, po co ci ta teczka?", "ton": "rzeczowe", "wymaga": null, "kto": "nora", "odpowiedz": "Po kolei: rzecz, osoba, skutek. Lista terminów, czternaście rodzin, czwartek, dziewiąty września. Bez niej nie mam daty, do kiedy Okoye mają zapłacić.", "mina": "mowi"}, {"tekst": "Czemu stoicie tu razem?", "ton": "niewygodne", "wymaga": null, "kto": "iris", "odpowiedz": "Bo przyszłyśmy w tej samej sprawie. Niektóre sprawy lepiej ustalać przy świadkach.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Iris, ile wynosi twoja oferta?", "ton": "uprzejme", "wymaga": null, "kto": "iris", "odpowiedz": "Trzysta dolarów. Za zwrot kasetki i za zwolnienie z formalności. To nie łapówka, tylko wykup. Dwa czynsze, uczciwie.", "mina": "mowi", "ustawia": "d18_oferta_300"}, {"tekst": "Nora, co proponujesz?", "ton": "rzeczowe", "wymaga": null, "kto": "nora", "odpowiedz": "Pokwitowanie z pieczęcią biura i terminem wydania oryginałów. Formalnie czyste. Wiem, że to wolniejsze, ale wygrywa na papierze.", "mina": "mowi"}, {"tekst": "Czemu Nora odmówiła Iris rok temu?", "ton": "niewygodne", "wymaga": null, "kto": "nora", "odpowiedz": "Nie odmówiłam. Odebrałam kiedyś paczkę przez okienko, bez wpisu. Iris pamięta. „Wykupuje” moje milczenie tak samo jak twoje.", "mina": "emocja"}, {"tekst": "Iris, skąd wiesz, gdzie jest mój pokój?", "ton": "niewygodne", "wymaga": null, "kto": "iris", "odpowiedz": "Z umowy. Nie lubię naciskać, ale pokój służbowy też bywa wypowiadany. Mówię to jak prognozę pogody.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz, jeśli oryginały trafią do Nory?", "ton": "uprzejme", "wymaga": null, "kto": "iris", "odpowiedz": "Będę musiała się z nimi rozliczyć. I z tymi, którzy pomagają. To ludzie, nie liczby.", "mina": "mowi"}, {"tekst": "Co zrobisz, jeśli oryginały trafią do Iris?", "ton": "rzeczowe", "wymaga": null, "kto": "nora", "odpowiedz": "Okoye zapłacą drugi raz. Termin w czwartek, dziewiątego września, jest sztywny. Powiem to po kolei, żeby nikt nie mówił, że nie wiedział.", "mina": "neutralna"}, {"tekst": "Co się stanie, jeśli materiały pójdą do kontroli?", "ton": "niewygodne", "wymaga": null, "kto": "iris", "odpowiedz": "Czyli do Victora. Wyjdzie wszystko: papiery, nazwiska, kasetki. Wtedy nikt nie będzie wolny.", "mina": "emocja"}]}], "decyzje": [{"akcja": "rezerwacja_nora", "etykieta": "Zarezerwuj wydanie oryginałów dla Nory", "kto": "nora", "reakcja": "Rezerwacja przyjęta. Po kolei: oryginały dla mnie, kopia dla biura. Dziękuję.", "zysk": "Lokatorzy mają szansę, a ty trzymasz się przepisów.", "strata": "Iris zaczyna grozić jak prognozą pogody i nie zapomni, kto stał przy szybie.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Iris Bell: „Pan zarządca z Urzędu pytał o pokój służbowy przy Cooper Street. Zastanawiam się dlaczego.”"}, "wymaga": "d12_iris_nora:zabezpiecz|d12_iris_nora:sprawdz_z_nora"}, {"akcja": "nora_kopia", "etykieta": "Odpisz Norze listę numerów z biura", "kto": "nora", "wymaga": "d12_iris_nora:wydaj_iris|d12_iris_nora:wyloz_400", "reakcja": "Lista numerów, bez oryginałów. To mniej, niż chciałam, ale więcej niż nic. Zapisuję, kto ją dał.", "zysk": "Nora ma numery do sądu i wie, kogo pytać, choć oryginały zostały u Iris.", "strata": "Kopia z biura dowodzi, że biuro wiedziało, a Iris dowie się, kto ją odpisał.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Nora Vance: „Mam listę numerów z biura. Sąd weźmie ją jako kopię, oryginały ma Iris. Piszę, żebyś wiedział, że ktoś to zrobił, kiedy nikt nie musiał. — N.V.”"}}, {"akcja": "do_kontroli", "etykieta": "Przekaż materiały do kontroli", "kto": "iris", "reakcja": "Do Victora. Dobrze. Czyli formalnie czysto. Nora poczeka dłużej.", "zysk": "Formalnie nikt nie zarzuci ci układu.", "strata": "Nora czeka dłużej, Skrytka jest wystawiona, a Urząd dostaje drugi egzemplarz.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Inspekcja przewozów: do protokołu wpłynęły materiały z biura. Do uzupełnienia: źródło planu kamienicy. — V. Crane"}}, {"akcja": "oferta_iris", "etykieta": "Przyjmij 300 $ od Iris i oddaj oryginały bez wpisu", "kasa": 300, "wymaga": "d18_oferta_300", "kto": "iris", "reakcja": "Miło mieć sprawy załatwione bez zbędnych słów. Dziękuję. Uwielbiam rozumienie.", "zysk": "Dostajesz 300 dolarów, czyli dwa czynsze, i spłacasz większość długu u Kuby.", "strata": "Oryginały odpływają bez śladu, Okoye płacą drugi raz, a ty stajesz się „swoim” u Iris.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Nora Vance: „Wiem, że oryginały nie leżą już w biurze. Zapisałam godzinę i to, kto stał przy szybie. Rodzina Okoye ma czas do czwartku, dziewiątego września. — N. Vance”"}}], "rola": "zarządczyni i prawniczka przy teczce", "watki": ["Skrytka", "kamienica", "pieniądze"], "tik": "Iris „drobna przysługa”, Nora „po kolei”", "potrzeba": "teczka z planem wyburzenia", "slad": "oferta 300 $ i „pokój służbowy”", "sprite": "teczka", "face": null, "face2": null, "line": "6", "itemName": "Teczka budowlana z planem kami", "inside": null}, {"id": "d18_hugo", "dzien": 18, "postac": "Hugo Lang, 40", "glos": "Hałaśliwy, zabawny, ciągle „wiesz, jak to jest”. Opowiada historie, których nikt nie sprawdza.", "typ": "uczciwy, kłamie dla spokoju", "rzecz": "Teleskopowa wędka w pokrowcu", "wnetrze": [{"sekret_id": "d18_dlug_karciany", "co_widac": "W kieszeni pokrowca złożony kwit długu karcianego: dwieście dolarów, podpis H.L., odbiorca K.M., termin: sobota.", "co_z_tego_wynika": "Hugo jest winien Marlowowi. Wędka jest alibi i zastawem."}], "wejscie": "Cześć, Hugo Lang, hydraulik. Zgubiłem wędkę, teleskopową, w czarnym pokrowcu. Żona myśli, że łowię ryby, ale ja gram w karty. Wędka ma być przy mnie, jak wrócę, bo ryby są alibi.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta wędka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarna, teleskopowa, z pokrowcem na zamek. Na rączce naklejka „Najlepszy tata”. Dostałem od córki, nie wiem, czemu.", "mina": "mowi"}, {"tekst": "Gdzie ją zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W szóstce, pod siedzeniem. Wracałem znad rzeki, a raczej znad stolika. Wysiadłem w pośpiechu.", "mina": "neutralna"}, {"tekst": "Czemu wędka jest alibi?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo kto łowi, ten ma rybę. A kto nie ma ryby, ten ma wędkę. Żona patrzy tylko na to, co widać.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Czy złowiłeś coś w życiu?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Raz leszcza. Wypuściłem, bo był podejrzanie podobny do teścia.", "mina": "mowi"}, {"tekst": "Ile razy w tygodniu „łowisz”?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Trzy. W czwartek wygrywam, w sobotę przegrywam, w niedzielę wracam z rybą z targu.", "mina": "klamie"}, {"tekst": "Czemu nie powiesz żonie prawdy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo ona mnie kocha za rybę. Co bym zrobił, gdyby się dowiedziała, że kocha mnie za nic?", "mina": "emocja"}, {"tekst": "W pokrowcu jest kwit na dwieście dolarów do K.M. Co to?", "ton": "niewygodne", "wymaga": "d18_dlug_karciany", "odpowiedz": "To nie kwit, to żart, który kosztuje dwieście dolarów. Marlow nie żartuje, ale ja tak. Do soboty.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Czego chcesz od biura?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Wędki. I żeby ktoś w razie czego powiedział, że wędka tu była, więc ryby też.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Hugo Lang. Z wężykiem na końcu, jak rura.", "mina": "neutralna"}, {"tekst": "Czy ktoś może potwierdzić, że łowisz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Jak trzeba, to znajomi. Ale oni też grają. Taka rybacka konspiracja.", "mina": "klamie"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki! Teraz mam wędkę i rybę. Tylko ryby jeszcze nie mam, ale to szczegół.", "zysk": "Hugo odzyskuje wędkę, a żona dalej nie wie.", "strata": "Wydajesz rzecz po opisie bez żadnego dowodu poza pokrowcem.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Hugo Lang: „Żona zapytała, ile złowiłem. Powiedziałem: tyle, co trzeba. Nie dopytywała. Chyba działa.”"}}, {"akcja": "zaswiadczenie", "etykieta": "Wydaj i napisz zaświadczenie, że wędka była w biurze", "reakcja": "Zaświadczenie! Cudo. Pokażę żonie jako dowód uczciwości. Prawie.", "zysk": "Hugo ma na papierze, że wędka była tu, a nie nad stolikiem.", "strata": "Wystawiasz papier, który ma pomóc w kłamstwie, i podpisujesz się pod nim.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Hugo Lang: „Żona czytała zaświadczenie dwa razy. Powiedziała: ciekawe, że biuro wie, gdzie byłeś. Chyba nie powinienem był tego pokazywać. — H.”"}}, {"akcja": "odmow", "reakcja": "Odmawiasz? Z wędką? No to ja dziś bez ryby. Ale i tak dzięki, że szczerze.", "zysk": "Nie tworzysz papierów, które pomagają kłamać.", "strata": "Hugo wraca do domu bez wędki, a żona dopyta o rybę.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Hugo Lang: „Żona zapytała, gdzie wędka. Powiedziałem: w biurze rzeczy znalezionych. Zrobiła minę, której nigdy nie widziałem.”"}}, {"akcja": "wez_100_hugo", "etykieta": "Weź 100 $ od Hugona za zaświadczenie i milczenie", "kasa": 100, "wymaga": "d18_dlug_karciany", "reakcja": "Sto, na ladzie. Zaświadczenie, że wędka tu była, i ani słowa o kwicie. Umowa? Umowa.", "zysk": "100 $ na czynsz, a Hugo ma papier dla żony.", "strata": "Wystawiasz fałszywe zaświadczenie za pieniądze. Urząd +2 przy kontroli, a Marlow wie, że Hugo ma Twoją zgodę.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Hugo Lang: „Żona czytała zaświadczenie. Zapytała, ile wziąłem za wędkę. Powiedziałem, że sto. Nie wiem, skąd wiedziała. — H.”"}}], "rola": "hydraulik, który łowi tylko alibi", "watki": ["humor", "Marlow", "pieniądze"], "tik": "mówi „wiesz, jak to jest”", "potrzeba": "wędka jako alibi dla żony", "slad": "kwit długu karcianego, odbiorcą jest Marlow", "sprite": "wedka", "face": null, "face2": null, "line": "6", "itemName": "Teleskopowa wędka w pokrowcu", "inside": null}, {"id": "d19_ada_leo", "dzien": 19, "postac": "Ada Vale i Leo Marsh", "glos": "Ada: dosłownie, jak dziecko, liczy kroki. Leo: spokojnie, z konduktorskim humorem, wymyka się od odpowiedzi.", "typ": "dziecko i konduktor, jedna puszka", "rzecz": "Konduktorska torba z dwoma wykazami zmiany", "ludzie": {"ada": "Ada Vale", "leo": "Leo Marsh"}, "wnetrze": [{"sekret_id": "d19_wykaz_poprawiony", "co_widac": "W torbie dwa wykazy zmiany. Drugi jest poprawiony ręcznie: dopisany numer puszki i jedno słowo „b.n.” tym samym długopisem.", "co_z_tego_wynika": "Leo wpisał puszkę do wykazu, bo ktoś mu to polecił, a potem sprostował, żeby nie zostać z tym sam."}], "wejscie": "Dobry wieczór. Leo Marsh i Ada Vale. Torba konduktorska, szóstka, z wykazami zmiany. Ada przyszła, bo wie więcej, niż mówi. Ja przyszedłem, bo wolę nie podpisywać za wszystkich.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta torba?", "ton": "uprzejme", "wymaga": null, "kto": "leo", "odpowiedz": "Skórzana, na pasku, z niebieską taśmą na rączce. W środku dwa wykazy: oficjalny i poprawiony.", "mina": "mowi"}, {"tekst": "Ada, po co tu jesteś?", "ton": "rzeczowe", "wymaga": null, "kto": "ada", "odpowiedz": "Bo wiem, skąd jest puszka. Mama mówi, że nie wolno, ale pan Leo mówi, że tu można. I tu mówią do mnie ładnie.", "mina": "mowi"}, {"tekst": "Leo, czemu wybrałeś tę zmianę?", "ton": "niewygodne", "wymaga": null, "kto": "leo", "odpowiedz": "Bo na zmianie jest dużo ludzi, a mało rzeczy. A ja jestem człowiek, który lubi wiedzieć, kto za co odpowiada.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Ada, co wiesz o puszce?", "ton": "uprzejme", "wymaga": null, "kto": "ada", "odpowiedz": "Że stała u pani Iris nad czajnikiem, a potem pan Leo ją wsunął pod ławkę. Zapisał w wykazie i nie powiedział nikomu.", "mina": "mowi"}, {"tekst": "Leo, czym różnią się wykazy?", "ton": "rzeczowe", "wymaga": null, "kto": "leo", "odpowiedz": "W drugim dopisałem numer puszki odręcznie. Oficjalny jest czysty. Wolałem mieć coś na własną rękę.", "mina": "neutralna"}, {"tekst": "Czy wy się boicie?", "ton": "niewygodne", "wymaga": null, "kto": "leo", "odpowiedz": "Ja trochę. Ale ja się boję zawsze, od dawna. Ada nie wie, że się boi, i to jest groźniejsze.", "mina": "emocja"}, {"tekst": "Na poprawionym wykazie jest numer puszki. Czyje to pismo?", "ton": "niewygodne", "wymaga": "d19_wykaz_poprawiony", "kto": "leo", "odpowiedz": "Moje. Ale numer podała mi Iris, pod szybą, jakby to było nic. Powiedziała: „Wpisz, to bezpieczniej.” Wpisałem.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Ada, co się stanie, jeśli wystąpisz jako świadek?", "ton": "uprzejme", "wymaga": null, "kto": "ada", "odpowiedz": "Że mama będzie płakać. Pani Iris powiedziała, że mamy dzień na spakowanie się. To jest dziecięce zdanie, ale ona je zna.", "mina": "emocja"}, {"tekst": "Leo, co mam zapisać?", "ton": "rzeczowe", "wymaga": null, "kto": "leo", "odpowiedz": "Sprostowanie. Że jedna puszka jechała moim kursem bez nadawcy i ja za to odpowiadam. Własnym nazwiskiem.", "mina": "mowi"}, {"tekst": "Dlaczego chcesz brać winę na siebie?", "ton": "niewygodne", "wymaga": null, "kto": "leo", "odpowiedz": "Bo wolę, żeby ktoś oberwał za puszkę, niż żeby całą zmianę wyrzucili. Wolę ja niż oni.", "mina": "emocja"}]}], "decyzje": [{"akcja": "przyjmij_sprostowanie", "etykieta": "Przyjmij podpisane sprostowanie Leo", "kto": "leo", "reakcja": "Podpisuję. Leo Marsh, jeden kurs, jedna puszka. Wszystko własnym nazwiskiem.", "zysk": "Leo bierze odpowiedzialność za jeden kurs, a reszta zmiany jest bezpieczna.", "strata": "W papierach pojawia się nazwisko Ady, więc Iris wypowie mieszkanie rodzinie Vale.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Rosa Vale: „Dostałyśmy wypowiedzenie. Iris powiedziała: „do piątku”. Ada pakuje pluszowe zwierzęta do kartonu i pyta, czy to sprawiedliwe. — Rosa”"}}, {"akcja": "oficjalny_wykaz", "etykieta": "Oprzyj się na oficjalnym wykazie, Adę zostaw poza sprawą", "kto": "ada", "reakcja": "Dziękuję. Pan Leo mówi, że czasem trzeba milczeć, żeby ktoś mógł mówić potem.", "zysk": "Ada i jej rodzina są bezpieczne, a Leo unika zbiorowej kary.", "strata": "Dowód jest słabszy, bo oficjalny wykaz nie zawiera dopisku o puszce.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Leo Marsh: „Zeszłej nocy wsiadła do szóstki dziewczynka i zapytała, czy puszka już jest. Powiedziałem: jest. I że to nic ważnego. Nie wiem, czy uwierzyła.”"}}, {"akcja": "sprostowanie_bez_ady", "etykieta": "Przyjmij sprostowanie Leo, ale bez nazwiska Ady", "kto": "leo", "reakcja": "Dobrze. Ada wypadła z papieru, a ja zostaję w nim sam. Wolę tak.", "zysk": "Leo bierze winę, a rodzina Vale zostaje w mieszkaniu.", "strata": "Wpis o puszce traci świadka, więc Nora ma słabszy dowód na obieg paczek.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Leo Marsh: „Sprostowanie leży w księdze. Ada mówi, że dobrze wyszło. Ja nie jestem pewien, czy to nie zbyt dobrze.”"}}], "rola": "dziecko i konduktor przy puszce", "watki": ["kamienica", "Skrytka"], "tik": "Ada liczy kroki", "potrzeba": "sprostowanie wykazu zmiany", "slad": "dzień na spakowanie dla rodziny Ady", "sprite": "torba_narzedzia", "face": null, "face2": null, "line": "6", "itemName": "Konduktorska torba z dwoma wyk", "inside": null}, {"id": "d19_kofi", "dzien": 19, "postac": "Kofi Mensah, 26", "glos": "Szybko, na jednym oddechu, z kurierską ironią. Zawsze sprawdza telefon.", "typ": "uczciwy, widział za dużo", "rzecz": "Czerwony powerbank z naklejką trasy", "wnetrze": [{"sekret_id": "d19_zlecenie_slip", "co_widac": "Pod naklejką z trasą wklejone stare zlecenie: „Port, Cooper 9, 80 $ za kurs. Cisza w cenie.” Pieczątka bez nazwiska.", "co_z_tego_wynika": "Kofi dostawał pensję za milczenie i jest jedynym, kto wie, co woził."}], "wejscie": "Cześć, Kofi Mensah, kurier rowerowy. Zgubiłem powerbank, czerwony, w szóstce. Bez niego telefon pada po trzech zleceniach, a ja żyję ze zleceń. Naklejka z trasą jest ważna, bo to moje stare kursy.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten powerbank?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czerwony, prostokątny, z pęknięciem na rogu. Naklejka z trasą: Port, Rynek, Cooper Street. Dostałem od kolegi z hurtowni.", "mina": "mowi"}, {"tekst": "Gdzie go zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W szóstce, na ładowarce przy oknie. Wysiadłem w biegu, bo zlecenie piszczało.", "mina": "neutralna"}, {"tekst": "Czemu masz na naklejce akurat tę trasę?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo to moja stara trasa. Kiedyś woziłem paczki bez pytań, ale teraz pytam. Wolę wiedzieć.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Co woziłeś na tej trasie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Płaskie paczki w szarym płótnie. Adres: Cooper Street dziewięć, drugie piętro. Nie wiedziałem, co w środku. Płacili za pięć kilometrów dziesięć dolarów.", "mina": "mowi"}, {"tekst": "Kto ci płacił?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Kobieta w jasnych rękawiczkach. Nigdy nie dotykała mojej ręki, tylko kładła pieniądze na torbie.", "mina": "mowi"}, {"tekst": "Czemu przestałeś wozić paczki?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo raz przesyłka była za lekka i za sztywna, jakby tylko papier. Pomyślałem, że ktoś gdzieś dostaje z niej nowe życie.", "mina": "emocja"}, {"tekst": "Pod naklejką jest zlecenie „cisza w cenie”. Co to znaczy?", "ton": "niewygodne", "wymaga": "d19_zlecenie_slip", "odpowiedz": "Że płacili za to, żebym nie pytał. Ostatni kurs: osiemdziesiąt dolarów. Mam je jeszcze, nie ruszałem.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czego chcesz od biura?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Powerbanku. I żeby moje stare kursy nie wracały jak echo.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Kofi Mensah, przez „K”. Dużymi, bo kurier nie ma czasu na ozdoby.", "mina": "neutralna"}, {"tekst": "Czy opowiesz to komuś jeszcze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Jeśli ktoś zapyta, powiem prawdę. Ale mało kto pyta kuriera, co wiezie.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki! Telefon żyje, ja żyję. A jak ktoś będzie pytał o trasę, to wiecie, gdzie mnie szukać.", "zysk": "Kofi odzyskuje powerbank i wraca na trasę.", "strata": "Wydajesz bez żadnego dowodu poza naklejką i opisem.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Kofi Mensah: „Powerbank działa. Pierwszy raz od tygodnia mam ładunek na cały dzień. Mam też ochotę opowiedzieć komuś o jasnych rękawiczkach.”"}}, {"akcja": "zapisz_zeznanie", "etykieta": "Wydaj i zapisz zeznanie Kofiego o trasie", "reakcja": "Zapisuje się? No dobra. Kofi Mensah, kurier. Tylko niech nikt nie dzwoni do mojego szefa.", "zysk": "Księga ma drugiego świadka trasy, a Nora ma co wskazać.", "strata": "Kofi staje się świadkiem i może stracić zlecenia, jeśli ktoś go znajdzie.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Nora Vance: „W księdze jest zeznanie kuriera. Rzecz, osoba, skutek: trasa paczek idzie z Portu na Cooper Street. Dziękuję.”"}}, {"akcja": "ostrzez", "etykieta": "Wydaj i ostrzeż Kofiego, żeby przestał o tym mówić", "reakcja": "Ostrzeżenie? No dobra. Nikomu nic. Jak mnie zapytają, zapomniałem.", "zysk": "Kofi jest bezpieczny, a trasa nie wraca do niego jak echo.", "strata": "Drugi świadek milknie, a ty sam stajesz się strażnikiem tajemnicy.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Kofi Mensah: „Zapomniałem. Powiedziałem szefowi, że byłem chory. Gdybyście mieli kiedyś ochotę ruszyć trasę, wiecie, gdzie szukać. — K.”"}}, {"akcja": "wez_80_kofi", "etykieta": "Weź 80 $ od Kofiego, żeby nie zapisywać jego nazwiska", "kasa": 80, "wymaga": "d19_zlecenie_slip", "reakcja": "Osiemdziesiąt, to ostatni kurs. Bierz. Nie zapisuj mnie, nie pytaj o trasę. Jak ktoś zapyta, nigdy mnie tu nie było.", "zysk": "80 $ w kieszeni i Kofi jest bezpieczny.", "strata": "Bierzesz pieniądze za to samo milczenie, które kupowano od Kofiego. Nora traci świadka, Urząd +1 przy kontroli.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Kofi Mensah: „Zapłaciłem. Nie wiem, kto przyjął pieniądze. Czuję się tak, jak wtedy na trasie. — K.”"}}], "rola": "kurier, który woził paczki w płótnie", "watki": ["Skrytka", "pieniądze"], "tik": "sprawdza telefon", "potrzeba": "powerbank na trasę", "slad": "zlecenie „cisza w cenie” pod naklejką", "sprite": "powerbank", "face": null, "face2": null, "line": "6", "itemName": "Czerwony powerbank z naklejką ", "inside": null}, {"id": "d19_ferro", "dzien": 19, "postac": "Mario Ferro, 47", "glos": "Mówi grzecznie i za głośno, jakby przeprosił z góry. Zaczyna od „przepraszam, że zawracam”, kończy od „jeszcze jedno”.", "typ": "uczciwy, pokrzywdzony", "rzecz": "Brązowa teczka z dokumentami na nazwisko Ferro", "wnetrze": [{"sekret_id": "d19_zaswiadczenie_ferro", "co_widac": "W teczce akt urodzenia, polisa i zaświadczenie o niekaralności na Augusta Maria Ferro. Na zaświadczeniu adnotacja: „Dowód wydany w duplikacie pod innym adresem, 2 lata temu”.", "co_z_tego_wynika": "Ktoś od dwóch lat używa dowodu na to nazwisko, wydanego w duplikacie. To ten sam August Ferro, którego dowód Gus Pell miał w portfelu."}], "wejscie": "Przepraszam, że zawracam. Mario Ferro, August Mario, jeśli pełnym imieniem. Zgubiłem brązową teczkę z dokumentami w szóstce. Chcę ją odebrać, ale jeszcze jedno: ktoś od dwóch lat chodzi po mieście jako ja.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta teczka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowa, sztywna, z gumką na rogu. Dwie przegródki. W jednej akt urodzenia, w drugiej polisa. Etykieta „M.F.” pisana flamastrem.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie ją zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W szóstce, na siedzeniu za kierowcą. Jechałem z wizyty u adwokata i ręce miałem pełne papierów. Zostawiłem ją, bo adwokat mówił za szybko.", "mina": "neutralna"}, {"tekst": "Co to znaczy, że ktoś chodzi po mieście jako Ty?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Dostałem wezwanie na sprawę o długi, których nie miałem. Dowód wydano w duplikacie, pod innym adresem. Od dwóch lat. Nie wiem kto.", "mina": "emocja"}, {"tekst": "W teczce jest adnotacja o duplikacie. Co to dla Ciebie znaczy?", "ton": "niewygodne", "wymaga": "d19_zaswiadczenie_ferro", "odpowiedz": "Że ktoś poszedł do urzędu i powiedział, że to ja. Z moim zdjęciem z lat dwudziestych. Dowód wygląda inaczej, ale kto sprawdza?", "mina": "emocja"}]}, {"pytania": [{"tekst": "Kim jesteś z zawodu?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Fryzjer. Własny zakład przy Rynku. Dwa foteliki, kolejka rano. Nie widzę, żeby moje nazwisko miało komukolwiek służyć.", "mina": "mowi"}, {"tekst": "Co jeszcze jest w teczce?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Zaświadczenie o niekaralności, polisa i zdjęcie z komunii. Zdjęcie jest ostatnią rzeczą, o którą się boję, bo ma datę na odwrocie.", "mina": "neutralna"}, {"tekst": "Czemu przyszedłeś właśnie tu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo adwokat powiedział: sprawdź, czy ktoś u was nie ma dwóch dowodów. W biurach rzeczy znalezionych takie rzeczy leżą. Przepraszam, że tak mówię.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz, jeśli dowiesz się, kto Cię udaje?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Nic. Pójdę do adwokata. Nie szukam zemsty, tylko pisma, że nie jestem tym, który ma długi.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór teczki?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Mario Ferro. August Mario podpisuję rzadko. Zwykle skracam, bo tamten podpisuje długo.", "mina": "neutralna"}, {"tekst": "Czy masz tu jakiś dowód, że to Ty jesteś prawdziwym Ferro?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Teczkę. Akt urodzenia, polisę i zdjęcie. A jeśli to za mało, proszę zadzwonić do adwokata. Numer mam w telefonie. Przepraszam, że tak mało.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj_ferro", "etykieta": "Wydaj teczkę i powiedz o duplikacie dowodu", "reakcja": "Dziękuję. Czyli ktoś miał dwa dowody. Proszę powiedzieć tylko tyle: jakie miasto, jakie nazwisko. Resztę znajdę sam.", "zysk": "Mario dostaje teczkę i wiadomość, że dowód z jego nazwiskiem był gdzieś w obiegu.", "strata": "Ujawniasz, co leżało w portfelu Gusa, a Gus mógł zostać bez drugiego nazwiska.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Mario Ferro: „Adwokat złożył pismo. Dowód z moim nazwiskiem był w obiegu, ktoś potwierdził to u Was. Dziękuję. Zdjęcia z komunii nie zgubię drugi raz. — M.F.”"}}, {"akcja": "odmow_ferro", "etykieta": "Wydaj teczkę, o duplikacie nic nie mów", "reakcja": "Dobrze. Przepraszam, że pytałem. Zostaję z dokumentami i bez odpowiedzi.", "zysk": "Gus i jego drugie nazwisko zostają poza sprawą, a biuro nie komentuje cudzych dokumentów.", "strata": "Mario dalej nie wie, kto go udaje, a sprawa o długi idzie swoim torem.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Mario Ferro: „Ktoś jeszcze używa mojego nazwiska. Dostałem kolejne wezwanie. Nie pytam dlaczego. Pytam, czy ktoś zapisał, że pytałem.”"}}, {"akcja": "ferro_kopia", "etykieta": "Wydaj teczkę i dołącz kopię wpisu o dowodzie Gusa Pella", "reakcja": "Kopia wpisu? Czyli ktoś zapisał, że był drugi dowód. Dobrze, to jest dowód, że biuro to widziało.", "zysk": "Mario ma papier z pieczątką, że dowód z jego nazwiskiem był w biurze.", "strata": "Kopia trafia do akt, a Urząd zobaczy dwa dowody pod jednym zdjęciem.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Victor Crane: „W aktach pojawiła się kopia wpisu o dwóch dowodach. Do wyjaśnienia: kto ją wydał i na czyją prośbę. — V.C.”"}}], "rola": "fryzjer udawany przez kogoś", "watki": ["cudze_nazwiska"], "tik": "przeprasza z góry, kończy „jeszcze jedno”", "potrzeba": "teczka z aktem urodzenia i polisą", "slad": "duplikat dowodu na jego nazwisko od dwóch lat", "sprite": "teczka", "face": null, "face2": null, "line": "6", "itemName": "Brązowa teczka z dokumentami n", "inside": null}, {"id": "d20_elias_sam", "dzien": 20, "postac": "Elias Wren, Sam Holt i Victor Crane", "glos": "Elias: powoli, staroświecko, uparcie. Sam: najpierw szczegół techniczny. Victor: krótko, ale dziś zaczyna mówić dłużej.", "typ": "trzej mężczyźni i jedna koperta", "rzecz": "Złoty zegarek kieszonkowy w etui po okularach", "ludzie": {"elias": "Elias Wren", "sam": "Sam Holt", "victor": "Victor Crane"}, "wnetrze": [{"sekret_id": "d20_zegarek_tyl", "co_widac": "Na tyle zegarka odcinek wpłaty z datą zgodną z kwitem Eliasa: 85 $, podpis S. Holt. Na odwrocie ołówkiem: „Wpisuj mało. Pytaj o imiona.”", "co_z_tego_wynika": "Sam zapłacił Eliasowi z własnej kieszeni. Notatki na odcinku brzmią jak rady dla kogoś innego."}], "wejscie": "Elias Wren. Przyszedłem z panem Holtem. Zegarek jest jego, w etui po okularach, bo nie miał gdzie. Pan Holt odmawia pieniędzy, a ja nie odpuszczę. O trzeciej pan Crane odbiera materiały, więc musimy się zmieścić.", "tury": [{"pytania": [{"tekst": "Sam, jak wygląda ten zegarek?", "ton": "uprzejme", "wymaga": null, "kto": "sam", "odpowiedz": "Złoty, mały, z pękniętym szkłem. Na pokrywce inicjały S.H. Wszystko, co mam po dziadku, kiedy go jeszcze miałem.", "mina": "mowi"}, {"tekst": "Sam, gdzie go zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "kto": "sam", "odpowiedz": "Nie zostawiłem. Mam go przy sobie od piętnastego dnia, w kieszeni płaszcza, i nie chcę go nosić. Etui jest Eliasa, bo swoje zgubiłem.", "mina": "neutralna"}, {"tekst": "Victor, czemu odbierasz materiały o trzeciej?", "ton": "niewygodne", "wymaga": null, "kto": "victor", "odpowiedz": "Bo o trzeciej zamykam tydzień. Nikt nie przeszkadza, papiery zachowują się spokojniej, a zmęczeni mówią prawdę. Bez kompletu do tej godziny rozliczenie przesuwa się o dobę, a doba w tej sprawie ma wartość.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Sam, czemu odmawiasz koperty?", "ton": "uprzejme", "wymaga": null, "kto": "sam", "odpowiedz": "Bo to nie są jego pieniądze. Zwróciłem Eliasowi za oprawkę, bo tak zrobiłem. Nie chcę, żeby mi to oddawał. To wstyd i dla niego, i dla mnie.", "mina": "emocja"}, {"tekst": "Elias, czemu nie odpuszczasz?", "ton": "rzeczowe", "wymaga": null, "kto": "elias", "odpowiedz": "Bo dług bez nazwy jest gorszy od długu z nazwiskiem. Oddam, a pan Holt może to wyrzucić. Ale najpierw musi wziąć.", "mina": "mowi"}, {"tekst": "Sam, czemu odszedłeś tak nagle?", "ton": "niewygodne", "wymaga": null, "kto": "sam", "odpowiedz": "Nie nagle, odchodziłem sześć tygodni. Bilet leży u Iris od pierwszego dnia, od kiedy Ty usiadłeś. Nie wziąłem go. Wziąć znaczyło zostawić Cię i nic nie powiedzieć.", "mina": "emocja"}, {"tekst": "Na odcinku jest data wpłaty zgodna z kwitem Eliasa. Co to?", "ton": "niewygodne", "wymaga": "d20_zegarek_tyl", "kto": "sam", "odpowiedz": "Dowód, że zapłaciłem. Z własnej kieszeni, nie z żadnego funduszu. To jedyna czysta rzecz w tej historii.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czego od nas chcesz, Sam?", "ton": "uprzejme", "wymaga": null, "kto": "sam", "odpowiedz": "Niczego. Chciałem tylko zapytać: jak cię zapisać? Elias pyta o imię od tygodni, a ja nie umiem odpowiedzieć za ciebie.", "mina": "emocja"}, {"tekst": "Victor, co weźmiesz o trzeciej?", "ton": "rzeczowe", "wymaga": null, "kto": "victor", "odpowiedz": "Komplet: zeznanie Eliasa, zeznanie Sama, dowód wpłaty. Jeśli pochodzenie jest czytelne i jest pokwitowanie, wpisuję własny podpis. Jeśli nie, zamykam tak, jak jest.", "mina": "mowi"}, {"tekst": "Elias, co zrobisz z kopertą, jeśli Sam jej nie weźmie?", "ton": "niewygodne", "wymaga": null, "kto": "elias", "odpowiedz": "Zostawię tu, na jego nazwisko. Niech leży, aż się zmęczy odmawiać.", "mina": "mowi"}, {"tekst": "Na odwrocie odcinka: „Wpisuj mało. Pytaj o imiona.” Do kogo to?", "ton": "niewygodne", "wymaga": "d20_zegarek_tyl", "kto": "sam", "odpowiedz": "Do mnie, kiedyś. Dziś do ciebie. Nie pytaj, skąd wiem, że ci się przyda.", "mina": "emocja"}]}], "decyzje": [{"akcja": "komplet_zeznan", "etykieta": "Złóż uzgodniony komplet zeznań i dowodów", "kto": "victor", "pole": "imie", "reakcja": "Komplet przyjęty. Zeznania obu stron, dowód wpłaty i pokwitowanie. Wpisuję własny podpis, bo pochodzenie jest czytelne.", "zysk": "Victor podpisuje rozliczenie, a Sam zostaje czysty w papierach.", "strata": "Wszystkie dokumenty idą do Urzędu w dwóch egzemplarzach, a druga kopia zostaje poza twoją kontrolą.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Victor Crane: „Komplet w teczce. Zapisałem godzinę, 3:00, i imię, które podano. Oba egzemplarze wyszły.”"}}, {"akcja": "poza_audytem", "etykieta": "Oddaj Samowi zegarek i trzymaj dokumenty poza audytem", "kto": "sam", "pole": "imie", "reakcja": "Zegarek wraca. Dokumenty zostają. Victor, nie patrz tak, tak jest uczciwie.", "zysk": "Sam zachowuje spokój, a Elias nie musi składać zeznań.", "strata": "Nic się nie zmienia w protokole, a Victor zamyka tydzień bez podpisu na swój koszt.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Victor Crane: „Audyt zamknięty bez kompletu. Zapisane: odmowa złożenia materiałów w terminie. Wrócimy do tego. — V.C.”"}}, {"akcja": "czesc_zeznan", "etykieta": "Złóż tylko zeznanie Eliasa, bez Sama", "kto": "elias", "pole": "imie", "reakcja": "Moje zeznanie przyjęte? Dobrze. Niech zostanie. Pan Holt może się nie zgodzić, ale to moja sprawa.", "zysk": "Elias wreszcie mówi głośno, że przyjął zwrot, a Sam nie jest pytany.", "strata": "Dowód zostaje niepełny, a Victor wraca z pytaniem o Sama.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Elias Wren: „Czy moje zeznanie zostało przyjęte? Pytam, bo pan Holt przestał mi odpowiadać.”"}}], "rola": "trzej mężczyźni i jedna koperta", "watki": ["Poprzednik", "Fotel", "Urząd"], "tik": "Elias rozprostowuje numerek", "potrzeba": "zegarek Sama i zeznania", "slad": "notatka „Pytaj o imiona” i pole na imię", "wejscie_jesli": {"d15_sam:uzgodnij": "Elias Wren. Przyszedłem z panem Holtem, uzgodniliśmy to w zeszłym tygodniu. Zegarek jest jego, w etui po okularach, bo nie miał gdzie. Pan Holt odmawia pieniędzy, a ja nie odpuszczę. O trzeciej pan Crane odbiera materiały, więc musimy się zmieścić.", "d15_sam:victor_od_razu": "Elias Wren. Pan Holt nie chciał tu wracać, odkąd pan Crane dostał jego kalkę, ale przyszedł. Zegarek jest jego, w etui po okularach. Pan Holt odmawia pieniędzy, a ja nie odpuszczę. O trzeciej pan Crane odbiera materiały, więc musimy się zmieścić.", "d15_sam:oddaj_samowi": "Elias Wren. Przyszedłem z panem Holtem, który dostał od Was swoją kalkę i od tamtej pory patrzy na okienko inaczej. Zegarek jest jego, w etui po okularach. Pan Holt odmawia pieniędzy, a ja nie odpuszczę. O trzeciej pan Crane odbiera materiały."}, "sprite": "zegarek", "face": null, "face2": null, "line": "6", "itemName": "Złoty zegarek kieszonkowy w et", "inside": null}, {"id": "d20_tobias", "dzien": 20, "postac": "Tobias Reed, 29", "glos": "Szybko, o dostawach mówi jak o pogodzie. Skraca nazwy ulic, kiedy się spieszy.", "typ": "kierowca dostawczy, którego goni grafik", "rzecz": "Kluczyki do vana z breloczkiem-syreną", "wnetrze": [{"sekret_id": "d20_koperta_napiwki", "co_widac": "W blaszanej syrenie schowek na zawleczkę, a w nim koperta z napiwkami: sześćdziesiąt dolarów, w drobnych, z karteczką „kurtka M.”.", "co_z_tego_wynika": "Pieniądze są córki Tobiasa, nie jego. Zbierał je miesiącami."}], "wejscie": "Tobias Reed, kierowca firmowy. Zostawiłem w szóstce kluczyki do vana, z breloczkiem w kształcie syreny. Van stoi pod zajezdnią z towarem dla sklepu i bez kluczyków nie ruszy o szóstej.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten breloczek?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Syrena z blachy, niebieska, z odłamanym ogonem. Dostałem od córki. Kluczyki są trzy, na kółku z kartą do bramy zajezdni.", "mina": "mowi"}, {"tekst": "Gdzie ich szukać?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W szóstce, na ostatnim siedzeniu przy oknie. Położyłem, jak zdejmowałem plecak, i wysiadłem w biegu. Typowe dla mnie, tylko że dziś piątek.", "mina": "mowi"}, {"tekst": "Co jest w tym vanie, że tak Ci się spieszy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Towar dla sklepu: chleb, jajka i dwie skrzynki mleka. Jak nie dowiozę do szóstej, sklep nie otworzy się na czas.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Od jak dawna jeździsz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Cztery lata. Prawie nie widuję dnia. Córka mówi, że jestem jak nietoperz z prawem jazdy.", "mina": "mowi"}, {"tekst": "Kto może potwierdzić, że van jest Twój?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Firma. Dyspozytor Mick, numer jest na karcie. Ale o tej porze śpi i nie odbierze.", "mina": "mowi"}, {"tekst": "Czemu spieszysz się tak, jakby coś Cię goniło?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo gonią mnie minuty. Pięć minut spóźnienia i dyspozytor odejmuje z pensji. Przy mojej pensji to boli.", "mina": "emocja"}, {"tekst": "Czemu ten breloczek jest taki ciężki?", "ton": "niewygodne", "wymaga": "d20_koperta_napiwki", "odpowiedz": "Bo w środku jest schowek. Trzymam tam napiwki od klientów, żeby ich nie wydać. Sześćdziesiąt dolarów na kurtkę dla córki.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz, jak odzyskasz kluczyki?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Pojadę po bułki. Potem na stację, wypiję kawę i poczuję się jak człowiek.", "mina": "mowi"}, {"tekst": "Jak zapisać Twoje nazwisko?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Reed, przez dwa e. Tobias, bez drugiego s, jak syrena bez ogona.", "mina": "mowi"}, {"tekst": "Czy ktoś mógłby chcieć tych kluczyków?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nikt z firmy. Ale ktoś mógłby wziąć van i sprzedać towar. Zdarzało się. Dlatego pilnuję kluczy bardziej niż portfela.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Są. Z ogonem albo bez, są. Dziękuję. Zdążę, chyba że zatrzymają mnie na świetle.", "zysk": "Tobias zdąża z towarem, a sklep otwiera się na czas.", "strata": "Wydajesz po opisie, bez dowodu, że van należy do niego.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Tobias Reed: „Zdążyłem. Sklep otworzył się o szóstej. Pani sprzedawczyni dała mi bułkę gratis. Powiedziałem, że to przez was.”"}}, {"akcja": "odmow", "reakcja": "Nie? Jak to nie? Dobrze, zadzwonię po Micka, ale on będzie wściekły. Wrócę z jego potwierdzeniem.", "zysk": "Procedura zachowana, kluczyki zostają w biurze.", "strata": "Tobias spóźnia się z towarem, a dyspozytor odejmuje mu z pensji.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Tobias Reed: „Mick dostał mnie o piątej. Potwierdził. Straciłem czterdzieści minut i dwadzieścia dolarów. Mówię bez złości, ale z żalem.”"}}, {"akcja": "wez_60_tobias", "etykieta": "Zatrzymaj 60 $ napiwków z breloczka", "kasa": 60, "wymaga": "d20_koperta_napiwki", "reakcja": "Kluczyki są. A koperta? Przecież była w syrenie… Nie, nic. Muszę jechać. Dziękuję.", "zysk": "60 $ w kieszeni i dług u Marlowa o rację mniejszy.", "strata": "Tobias traci kurtkę dla córki, a Ty wiesz, że wziąłeś pieniądze od człowieka, który nic nie ma. Liczy się do zakończenia Nowy Sam.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Tobias Reed: „Koperta zniknęła razem z kluczykami, a kluczyki wróciły. Nie powiem, że to wy. Powiem, że kurtka dla córki poczeka do wypłaty.”"}}], "rola": "kierowca dostawczy z grafikiem", "watki": ["pieniądze"], "tik": "skraca nazwy ulic", "potrzeba": "kluczyki do vana przed szóstą", "slad": "ukryte napiwki na kurtkę dla jego córki", "sprite": "klucze", "face": null, "face2": null, "line": "6", "itemName": "Kluczyki do vana z breloczkiem", "inside": null}, {"id": "d21_maya_lena_priya", "dzien": 21, "postac": "Maya Doyle, Lena Brandt i Priya Nair", "glos": "Maya: precyzyjnie, liczy do trzech. Lena: szybko, urywa „ale…”. Priya: panna młoda, mówi na wdechu, patrzy na zegar.", "typ": "trzy kobiety i dwie identyczne walizki", "rzecz": "Szara twarda walizka z żółtą wstążką na rączce", "ludzie": {"maya": "Maya Doyle", "lena": "Lena Brandt", "priya": "Priya Nair"}, "wnetrze": [{"sekret_id": "d21_bilet_0517", "co_widac": "W zamykanej kieszeni walizki Mai leży suknia i jednorazowy bilet z numerem 0517, bez daty. Zszyty z kartką: „Wyjście. Raz.”", "co_z_tego_wynika": "Bilet Mai przyszedł od ludzi, którzy dają ludziom wyjście. To nie ona go wymyśliła."}, {"sekret_id": "d21_metka", "co_widac": "Na rączce jednej z walizek metka z długopisem: „P. Nair”. Druga ma pusty uchwyt na metkę.", "co_z_tego_wynika": "Walizki odróżnia metka i wstążka. Kto wydaje bez porównania, ryzykuje czyjś ślub."}], "wejscie": "Maya Doyle po walizkę, Lena Brandt po wiadomość od Mai, a Priya Nair po swoją, bo ślub ma o jedenastej. Są dwie szare walizki i obie zamykają się tak samo. Zacznijmy od tego, która czyja.", "tury": [{"pytania": [{"tekst": "Priya, jak wygląda Twoja walizka?", "ton": "uprzejme", "wymaga": null, "kto": "priya", "odpowiedz": "Szara, twarda, z żółtą wstążką na rączce. W środku suknia, buty i welon w osobnej torbie, bo się gniecie. Zamek ma zacięty suwak z lewej.", "mina": "mowi"}, {"tekst": "Maya, co jest w Twojej walizce?", "ton": "rzeczowe", "wymaga": null, "kto": "maya", "odpowiedz": "Suknia. Moja, sprzed siedmiu lat. Nie na ślub, na oddanie. Raz, dwa, trzy. Evan ma ją dostać. To jedyna wiadomość, jaką mu wyślę.", "mina": "emocja"}, {"tekst": "Lena, czemu przyszłaś razem z Mayą?", "ton": "niewygodne", "wymaga": null, "kto": "lena", "odpowiedz": "Bo wiem, że to dziś. Nie chcę, żeby poszła sama. Ale… nie sama, tylko obok. Ona mówi, że obok to też za blisko.", "mina": "emocja"}, {"tekst": "W kieszeni walizki Mai jest bilet 0517. Skąd on jest?", "ton": "niewygodne", "wymaga": "d21_bilet_0517", "kto": "maya", "odpowiedz": "Dostałam go w kopercie, bez słowa. Nie wiem od kogo, wiem od czego. Pytaj, czemu nie użyłam go wcześniej.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Maya, czemu oddajesz suknię Evanowi?", "ton": "uprzejme", "wymaga": null, "kto": "maya", "odpowiedz": "Bo to jego pamiątka, nie moja. Nie chcę od niego niczego, ani żalu, ani rzeczy. Oddam i będzie po wszystkim.", "mina": "mowi"}, {"tekst": "Lena, co chcesz przekazać Mai?", "ton": "rzeczowe", "wymaga": null, "kto": "lena", "odpowiedz": "Że jest mi przykro, że dopiero jej zniknięcie mnie ruszyło. Że mogłam pytać. Ale ona nie chce słuchać, a ja nie chcę być jak Evan.", "mina": "emocja"}, {"tekst": "Priya, wesele o jedenastej. Co, jeśli walizki się pomylą?", "ton": "niewygodne", "wymaga": null, "kto": "priya", "odpowiedz": "Będę stała w cudzej sukni, a ktoś w mojej. Nie pomylą się, mam metkę. No i wstążkę. Nikt tak nie wiąże kokardy.", "mina": "mowi"}, {"tekst": "Która walizka ma metkę z nazwiskiem?", "ton": "niewygodne", "wymaga": "d21_metka", "kto": "priya", "odpowiedz": "Moja. Dopisałam długopisem, bo wiem, jak jest na dworcach. Tamta bez metki jest czyjaś inna. Maya, nie obrażaj się.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Maya, jak się czujesz przed oddaniem sukni?", "ton": "uprzejme", "wymaga": null, "kto": "maya", "odpowiedz": "Jak po wyłączeniu prądu. Nic nie iskrzy. Ciszej, niż myślałam. Chyba lepiej.", "mina": "mowi"}, {"tekst": "Maya, powiedz jeszcze coś, zanim odejdziesz.", "ton": "uprzejme", "wymaga": "maya_testy_2", "kto": "maya", "odpowiedz": "Tak. Cicho, żeby Lena nie słyszała. Iris ma dla Ciebie jeden bilet, powiedziała mi sama, kiedy spytałam, kto tu siedział przed Tobą. Nie bierz go z jej ręki. Raz, dwa, trzy.", "mina": "emocja"}, {"tekst": "Lena, wolisz przekazać wiadomość sama czy przeze mnie?", "ton": "rzeczowe", "wymaga": null, "kto": "lena", "odpowiedz": "Przez Ciebie, jeśli Maya pozwoli. Sama zepsuję. Zawsze mówię o dwa zdania za dużo.", "mina": "emocja"}, {"tekst": "Priya, bardzo Ci się spieszy?", "ton": "niewygodne", "wymaga": null, "kto": "priya", "odpowiedz": "Strasznie. Mam pięćdziesiąt dolarów w kopercie na taksówkę. Dam je, jeśli wydacie obie walizki od ręki, bez sprawdzania.", "mina": "neutralna", "ustawia": "d21_oferta_50"}]}], "decyzje": [{"akcja": "wiadomosc_zatwierdzona", "etykieta": "Wydaj Mai walizkę, Lenie tylko zatwierdzoną wiadomość", "kto": "maya", "reakcja": "Raz. Dwa. Trzy. Tak. Trzeci test zaliczony. Lena dostaje to, co zatwierdziłam, nic ponad. Okienko wytrzymało trzy razy z rzędu.", "zysk": "Maya ufa okienku, a Lena dostaje dokładnie jedno zdanie od siostry.", "strata": "Lena zostaje z żalem i wiadomością, która przeszła przez filtr. Evan dostaje tylko suknię.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Lena Brandt: „Dostałam jedno zdanie i kartkę z podpisem Mai. Przeczytałam sześć razy. Dziękuję, że nikt nie dopisał nic od siebie. — L.”"}}, {"akcja": "bez_posrednictwa", "etykieta": "Wydaj Mai walizkę bez pośrednictwa, Lena bez słowa", "kto": "maya", "reakcja": "Czysto. Bez pośrednika i bez wiadomości, którą ktoś mógłby przepisać. Wychodzę. Raz, dwa, trzy. Zamykam.", "zysk": "Maya odchodzi czysto i nikt nie zna szczegółów.", "strata": "Lena zostaje przy szybie bez słowa. Maya nie zalicza trzeciego testu, bo ufa bardziej sobie niż okienku.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Lena Brandt: „Maya wyjechała i nie zostawiła mi nic. Pytałam, czy ktoś coś zapisał. Nikt. Wiem, że tak chciała. To nie znaczy, że umiem.”"}}, {"akcja": "wez_50_priya", "etykieta": "Weź 50 $ od Priyi i wydaj obie walizki od ręki", "kasa": 50, "wymaga": "d21_oferta_50", "kto": "priya", "reakcja": "Dziękuję, dziękuję! Wzięłam szarą ze wstążką. Maya, przepraszam. Lecę, bo zaraz zacznę płakać. Koperta na ladzie, tak?", "zysk": "50 $ w kieszeni i kolejka rusza szybko.", "strata": "Metka przestaje mieć znaczenie, a Maya widzi, że okienko bierze pieniądze za pośpiech. Nie zalicza trzeciego testu.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Priya Nair: „Zdążyłam. W taksówce otworzyłam walizkę i sprawdziłam. Wstążka się zgadzała. Wiem, że mogło być inaczej.”"}}], "rola": "trzy kobiety i dwie walizki", "watki": ["Zaginiona", "Fotel"], "tik": "Maya liczy, Lena „ale…”", "potrzeba": "suknia, wiadomość i ślub o jedenastej", "slad": "bilet 0517 w zamykanej kieszeni walizki Mai", "wejscie_jesli": {"d11_maya:powiadom_rodzine": "Maya Doyle po walizkę, bez słowa do Leny. Lena Brandt stoi obok, bo od was wie, że siostra żyje. Priya Nair po swoją, ślub ma o jedenastej. Są dwie szare walizki i obie zamykają się tak samo. Zacznijmy od tego, która czyja.", "d14_noah:bez": "Maya Doyle po walizkę. Noah Reyes zamknął sprawę bez jej podpisu, więc przyszła tylko po rzecz. Lena Brandt po wiadomość, Priya Nair po swoją, ślub ma o jedenastej. Dwie szare walizki, obie zamykają się tak samo. Zacznijmy od tego, która czyja.", "d16_maya_lena:lena_zalatwia": "Maya Doyle po walizkę, którą Lena obiecała odwieźć. Lena Brandt po wiadomość od Mai, Priya Nair po swoją, ślub ma o jedenastej. Są dwie szare walizki i obie zamykają się tak samo. Zacznijmy od tego, która czyja.", "d17_evan:zdradz_szczegol": "Maya Doyle po walizkę. Ktoś powiedział Evanowi, że była w czwórce o 22:40, więc przyszła tylko po rzecz, bez rozmów. Lena Brandt po wiadomość, Priya Nair po swoją, ślub ma o jedenastej. Dwie szare walizki. Zacznijmy od tego, która czyja."}, "sprite": "walizka", "face": null, "face2": null, "line": "6", "itemName": "Szara twarda walizka z żółtą w", "inside": null}, {"id": "d21_mina", "dzien": 21, "postac": "Mina Oh, 68", "glos": "Spokojnie i z uporem. Mówi do rzeczy tak, jak mówi się do kota: cierpliwie i dwa razy.", "typ": "emerytka, która pilnuje leków", "rzecz": "Wiklinowy koszyk z lekami i słoikiem śliwek", "wnetrze": [{"sekret_id": "d21_recepta", "co_widac": "Na dnie koszyka recepta na nazwisko M. Oh i paragon z apteki: 94 $ za miesiąc leków na serce. Pod spodem druga, nieopłacona.", "co_z_tego_wynika": "Mina płaci za leki z oszczędności. Drugiego miesiąca nie starczy."}], "wejscie": "Mina Oh, emerytka. Zostawiłam w czwórce wiklinowy koszyk z lekami na serce i słoikiem śliwek dla wnuczki. Lek muszę wziąć o ósmej rano. Słyszałam, że w biurze stoją dwa podobne koszyki, więc proszę mi nie dać cudzego.", "tury": [{"pytania": [{"tekst": "Jak wygląda Twój koszyk?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Wiklinowy, z pokrywką na rzemyk. Rzemyk zawiązałam podwójnym węzłem, bo pierwszy zawsze się rozwiązuje. Wewnątrz serwetka w kratkę.", "mina": "mowi"}, {"tekst": "Co jest w środku?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Leki, jedno opakowanie na miesiąc. Słoik śliwek z pestkami, wnuczka nie lubi bez pestek. I paragon z apteki.", "mina": "mowi"}, {"tekst": "Czemu nie wzięłaś koszyka z tramwaju od razu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo zasnęłam. Człowiek w moim wieku zasypia, jak mu się pozwoli. Teraz pamiętam, że pozwoliłam.", "mina": "mowi"}, {"tekst": "Na paragonie jest kwota 94 dolarów. To dużo jak na leki.", "ton": "niewygodne", "wymaga": "d21_recepta", "odpowiedz": "Dużo. Emerytura starcza na dwa tygodnie, a reszta idzie z oszczędności. Nie narzekam, tylko liczę.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Dla kogo jest ten słoik?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dla Zoe, wnuczki. Ma siedem lat i twierdzi, że śliwki to owoce, które się przebrały za winogrona.", "mina": "mowi"}, {"tekst": "Kto może potwierdzić, że koszyk jest Twój?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Apteka na Rynku, farmaceutka Anja. Zna mnie od lat, ale o tej porze już śpi.", "mina": "mowi"}, {"tekst": "Czemu boisz się cudzego koszyka?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo raz wzięłam cudzy i wzięłam cudze tabletki. Dobrze, że to były witaminy. Od tamtej pory sprawdzam podwójnie.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz po odzyskaniu koszyka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Wezmę lek, a potem zrobię sobie herbatę. Zoe przyjdzie na śniadanie z mamą, więc słoik musi być cały.", "mina": "mowi"}, {"tekst": "Jak zapisać Twoje nazwisko?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Oh, przez „h” na końcu. Mina, od Wilhelminy. Tak mnie nazwano przed wojną, której nie pamiętam.", "mina": "mowi"}, {"tekst": "Co, jeśli koszyk się nie znajdzie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "To pójdę do Anji o ósmej i poproszę na kreskę. Nie pierwszy raz, a Anja nie pyta.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Rzemyk podwójny, serwetka w kratkę. To mój. Dziękuję. Wnuczka dostanie śliwki, a ja lek o ósmej.", "zysk": "Mina odzyskuje lek i słoik, a Zoe ma śniadanie.", "strata": "Wydajesz po opisie, a drugi koszyk dalej stoi w kącie bez właściciela.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Mina Oh: „Wzięłam lek o ósmej. Zoe zjadła śliwki z pestkami i powiedziała, że to najlepsze winogrona. Nic nie wiem o tym drugim koszyku.”"}}, {"akcja": "zadzwon", "etykieta": "Zadzwoń do apteki i potwierdź receptę", "reakcja": "O tej porze? Dobrze, apteka na Rynku ma dyżur nocny. Dziękuję, że sprawdzacie, nikt tak nie robi.", "zysk": "Recepta potwierdzona, koszyk wydany bez wątpliwości.", "strata": "Mina czeka dłużej, a lek bierze później niż o ósmej.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Mina Oh: „Anja potwierdziła przez telefon. Powiedziała, że ktoś w biurze pracuje porządnie. Zapisała mnie na stałe, na kreskę.”"}}, {"akcja": "wyloz_94", "etykieta": "Wydaj koszyk i dołóż 94 $ na lek na następny miesiąc", "kasa": -94, "wymaga": "d21_recepta", "reakcja": "Nie prosiłam o to. Nie wezmę. …Wezmę, bo Zoe będzie na śniadaniu, a ja nie będę liczyć dni do końca miesiąca. Dziękuję.", "zysk": "Mina ma lek na dwa miesiące i spokojną głowę.", "strata": "Tracisz 94 $ z własnej kieszeni, a do soboty jest daleko. Liczy się do zakończenia Nowy Sam.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Mina Oh: „Wczoraj wzięłam drugie opakowanie. Zoe narysowała dla Ciebie śliwkę z pestką. Zostawiam przy szybie. — M.O.”"}}], "rola": "emerytka pilnująca leków", "watki": ["pieniądze", "humor"], "tik": "mówi wszystko dwa razy", "potrzeba": "koszyk z lekiem na ósmą", "slad": "paragon 94 $ za miesiąc leków", "sprite": "pudelko", "face": null, "face2": null, "line": "4", "itemName": "Wiklinowy koszyk z lekami i sł", "inside": null}, {"id": "d22_noah", "dzien": 22, "postac": "Noah Reyes, 42", "glos": "Krótko, prosto, ściszonym głosem. Kładzie rzeczy równo z krawędzią lady. Mówi: „Czyli:”.", "typ": "policjant, który zamyka sprawę", "rzecz": "Sztywna szara koperta policyjna", "wnetrze": [{"sekret_id": "d22_zakres_zgody", "co_widac": "Na kartce zakres zgody pismem Mai: „Wolno potwierdzić, że żyję. Nie wolno: miasto, nazwisko, linia, praca. Ważne do wtorku, siódmego września.”", "co_z_tego_wynika": "Maya zgodziła się na jedno zdanie, nie na ślad. Ktoś, kto czyta więcej, wychodzi poza jej zgodę."}], "wejscie": "Noah Reyes, komisariat przy Rynku. Dziś kończy się termin zgłoszenia zaginięcia Mai Doyle. Czyli: potrzebuję oświadczenia, jeśli jest, i decyzji, co z nim zrobić. Koperta powinna być w depozycie.", "tury": [{"pytania": [{"tekst": "Co dokładnie jest w kopercie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czyli: oświadczenie Mai, jedna strona, podpis, data. I kartka z zakresem zgody, żeby nikt nie napisał o jedno zdanie za dużo.", "mina": "mowi"}, {"tekst": "Co zrobisz z oświadczeniem?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Czyli: dołączę do akt i zamknę zgłoszenie. Dziś mija termin. Potem to już nie poszukiwanie, tylko wiedza, że żyje.", "mina": "mowi"}, {"tekst": "Czemu tak Ci zależy na terminie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo po terminie rodzina może wynająć kogoś z zewnątrz. Czyli ktoś będzie szukał, a ja nie będę miał nad nim żadnej kontroli.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Od kiedy prowadzisz tę sprawę?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Od czwartku sprzed pięciu tygodni. Czyli od dnia zgłoszenia. Najpierw myślałem, że zwykła. Potem zobaczyłem pismo Mai.", "mina": "mowi"}, {"tekst": "Do której złożysz papiery?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Do szóstej rano. Czyli jeśli się spóźnię, sprawa idzie wyżej i nic z tego nie zależy ode mnie.", "mina": "mowi"}, {"tekst": "Co dokładnie mogę przekazać z tej koperty?", "ton": "niewygodne", "wymaga": "d22_zakres_zgody", "odpowiedz": "Czyli: że żyje i jest bezpieczna. Nie wolno: miasto, nazwisko, linia, praca. Napisała to sama, własną ręką.", "mina": "mowi"}, {"tekst": "Czy Evan wie, że to oświadczenie istnieje?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. I niech tak zostanie. Ale w kolejce stoi ktoś w szarym kapeluszu, a on pyta o to samo.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co pomogło Ci w tej sprawie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czyli: że ktoś odmówił powiedzenia za dużo. Mało kto to potrafi, zwłaszcza po nocy.", "mina": "mowi"}, {"tekst": "Co się stanie, jeśli nic nie przekażę?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Czyli: zgłoszenie wisi. Maya jest bezpieczna, ale detektyw rusza, a ja go nie zatrzymam.", "mina": "mowi"}, {"tekst": "Co dostanie Evan, jeśli oświadczenie do niego dotrze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Czyli: jedno zdanie. Żyje i nie wróci. Nic więcej. Chyba że ktoś dopisze od siebie, a wtedy to już nie jest jej zdanie.", "mina": "emocja"}]}], "decyzje": [{"akcja": "przekaz_w_granicach", "etykieta": "Przekaż oświadczenie w granicach zgody Mai", "reakcja": "Czyli: zamykam zgłoszenie, Evan dostaje jedno zdanie. Zapisuję: dyżurny, bez nazwiska.", "zysk": "Noah zamyka sprawę, a Maya jest oficjalnie bezpieczna.", "strata": "Dokumenty trafiają do akt, a akta czyta ktoś więcej niż Noah.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Evan Doyle: „Dostałem jedno zdanie od policji. Dziękuję, że ktoś oddał mi je w całości. Nie wiem jeszcze, co z nim zrobię.”"}}, {"akcja": "zostaw_otwarte", "etykieta": "Zostaw sprawę otwartą, nic nie przekazuj", "reakcja": "Czyli: zgłoszenie wisi. Maya bezpieczna, a na zewnątrz ktoś ruszy z własnym szukaniem. Nie moja decyzja.", "zysk": "Maya jest bezpieczna, a oświadczenie zostaje w depozycie.", "strata": "Po terminie Evan może trafić do detektywa, który nie pyta o zgodę.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Mężczyzna w szarym kapeluszu: „Zgodnie z regulaminem. Dostałem wskazówkę z biura rzeczy znalezionych. Nie mówię, od kogo.”"}}, {"akcja": "przekaz_calosc", "etykieta": "Przekaż całą kopertę, także kartkę z zakresem", "reakcja": "Czyli: wszystko, jak leży. Dobrze. Nikt nie powie, że coś ukryłem.", "zysk": "Noah ma komplet i zgłoszenie zamyka się szybko.", "strata": "Granice zgody Mai, jej własne słowa, trafiają do akt, więc ktoś może je wykorzystać przeciw niej.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Noah Reyes: „Kartkę z zakresem zgody widziałem w aktach po raz drugi. Ktoś kopiował, nie ja. Sprawdzam, kto. — N.R.”"}}], "rola": "policjant zamykający zgłoszenie", "watki": ["Zaginiona"], "tik": "mówi „Czyli:”", "potrzeba": "oświadczenie Mai przed terminem", "slad": "zakres zgody Mai: wolno tylko potwierdzić, że żyje", "wejscie_jesli": {"d14_noah:bez": "Noah Reyes, komisariat przy Rynku. Nie rezerwowałem terminu, więc dziś mija. Czyli: potrzebuję oświadczenia, jeśli jest, i decyzji, co z nim zrobić. Koperta powinna być w depozycie.", "d11_maya:powiadom_rodzine": "Noah Reyes, komisariat. Lena Brandt wie, że siostra żyje, i nie pytała mnie o nic więcej. Dziś mija termin zgłoszenia. Czyli: potrzebuję oświadczenia Mai, jeśli jest. Koperta powinna być w depozycie.", "d17_evan:zdradz_szczegol": "Noah Reyes, komisariat. Evan Doyle wie, że Maya była w czwórce o 22:40, i nie powiedział mi, skąd. Dziś mija termin. Czyli: potrzebuję oświadczenia Mai i decyzji, co z nim zrobić. Koperta w depozycie."}, "sprite": "koperta", "face": null, "face2": null, "line": "6", "itemName": "Sztywna szara koperta policyjn", "inside": null}, {"id": "d22_stahl", "dzien": 22, "postac": "Marek Stahl, ok. 50", "glos": "Gładki, zbyt dobrze przygotowany, powtarza frazy z regulaminu: „zgodnie z regulaminem”.", "typ": "klient, który wie za dużo", "rzecz": "Szara walizka z żółtym zamkiem, zgłoszona jako zgubiona", "wnetrze": [{"sekret_id": "d22_kwit_maya", "co_widac": "Na kopii pokwitowania wydania: „Odbiorca: M.D. Rzecz: walizka szara, wydana wczoraj. Dalej: linia 4, peron 5.” Pieczątka okienka.", "co_z_tego_wynika": "Kwit podaje miejsce i godzinę. To adres, którego Maya nie zgodziła się podać."}, {"sekret_id": "d22_depozyt_detektyw", "co_widac": "Do walizki przypięta karteczka: „Depozyt detektywa, zaliczka 600 $, odbiór po okazaniu pełnomocnictwa. S.” Pieczątka biura detektywistycznego.", "co_z_tego_wynika": "Stahl działa jako pełnomocnik zatrudnionego detektywa Evana i ma przy sobie dowód zaliczki."}], "wejscie": "Dobry wieczór. Marek Stahl. Zgodnie z regulaminem zgłaszam zgubę: szara walizka, w środku biała suknia, bilet i kartka z numerem. Proszę o wskazanie, kto ją wczoraj odebrał, żeby sprawa była jasna.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta walizka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szara, twarda, z żółtym zamkiem. Zgodnie z regulaminem dodam, że w środku jest biała suknia. Opis jest dokładny, nie traćmy czasu biura.", "mina": "mowi"}, {"tekst": "Kiedy ją zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Wczoraj, jedenastką, o szóstej. Zgodnie z regulaminem pamiętam to doskonale: peron, godzina, nawet pogoda.", "mina": "klamie"}, {"tekst": "Skąd tak dokładnie znasz opis sukni?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Zgodnie z regulaminem: od klienta, który ją pakował. Nie podaję nazwiska klienta. Mam do tego prawo.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Czego dokładnie od okienka potrzebujesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Jednej rzeczy. Kopii pokwitowania wydania z wczoraj, ze wskazaniem, kto odebrał walizkę i dokąd miała jechać.", "mina": "mowi"}, {"tekst": "Na jakiej podstawie to żądasz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Zgodnie z regulaminem: jako zgłaszający zgubę. Z dokumentem potwierdzającym własność lub bez, ale z opisem. Opis mam, proszę sprawdzić.", "mina": "klamie"}, {"tekst": "Czy to Ty stałeś wczoraj na końcu kolejki?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Zgodnie z regulaminem kolejka jest publiczna. Stałem tam, gdzie wolno stać. Jeśli to zapisano, proszę zapisać z kropką po imieniu.", "mina": "emocja"}, {"tekst": "Na kwicie: odbiór M.D., linia 4, peron 5. Co z tym?", "ton": "niewygodne", "wymaga": "d22_kwit_maya", "odpowiedz": "Zgodnie z regulaminem proszę o kopię. Z tej linijki da się poskładać wszystko. Zapłacę, żeby oszczędzić biuru pisania.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Jak długo szukasz tej osoby?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Ponad miesiąc. Zgodnie z regulaminem nie podaję, kto płaci. Ludzie bywają wdzięczni za dobrze wykonaną robotę.", "mina": "mowi"}, {"tekst": "Czego byś się nie dowiedział, gdyby okienko odmówiło?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Niczego, czego nie da się znaleźć gdzie indziej. Tylko wolniej, a wolniej bywa drożej dla wszystkich zainteresowanych.", "mina": "neutralna"}, {"tekst": "Ile jesteś gotów zapłacić za kopię kwitu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Zgodnie z regulaminem to nie jest łapówka, tylko opłata manipulacyjna. Dwieście dolarów, od ręki, bez podpisywania.", "mina": "neutralna", "ustawia": "d22_oferta_200"}, {"tekst": "Do walizki jest przypięta karteczka z depozytem detektywa. Co to?", "ton": "niewygodne", "wymaga": "d22_depozyt_detektyw", "odpowiedz": "Zaliczka, sześćset dolarów, na wypadek, gdyby pełnomocnictwo nie przyszło na czas. To zgodne z regulaminem. Proszę nie traktować tego jak nacisku.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "stahl_odeslij", "etykieta": "Odeślij: żądaj dokumentu własności i nic nie wydawaj", "reakcja": "Zgodnie z regulaminem… rozumiem. Dokument własności. Wrócę z nim. Albo z kimś, kto wie, jak się takie rzeczy załatwia.", "zysk": "Maya zostaje bezpieczna, a Stahl wie, że okienko go przejrzało.", "strata": "Stahl zapamiętuje, kto stoi za szybą, i wraca z innej strony.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Marek Stahl: „Zgodnie z regulaminem. Dokument właściciela mam. Wystawił go ktoś, kto nie powinien.”"}}, {"akcja": "stahl_wydaj", "etykieta": "Wydaj Stahlowi kopię kwitu z wczorajszego wydania", "reakcja": "Zgodnie z regulaminem. Dziękuję. Linia 4, peron 5. Tyle wystarczy. Nie zapomnę, kto był uprzejmy.", "zysk": "Stahl odchodzi z kierunkiem, a Ty zachowujesz czystą kieszeń i czyste sumienie wobec Marlowa.", "strata": "Detektyw dostaje trop Mai i jedzie za nią na linię 4, na peron 5.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Evan Doyle: „Detektyw zadzwonił. Wie, którą linią i o której. Nie prosiłem o to. Nie wiem, kto zapisał. — E.D.”"}}, {"akcja": "wez_200_stahl", "etykieta": "Weź 200 $ opłaty i wydaj kopię kwitu", "kasa": 200, "wymaga": "d22_oferta_200", "reakcja": "Zgodnie z regulaminem: dwieście, na ladzie. Dziękuję za sprawność. Linia 4, peron 5. Zapisane.", "zysk": "200 $ w ręku i kolejka bez zakłóceń.", "strata": "Okienko sprzedało trop za opłatę: Urząd +2, kopie +1, a Stahl wraca z drugim pytaniem.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Evan Doyle: „Detektyw wie, którą linią i o której. Zapłacił za to, a Ty nie wiesz komu. Dzwonię, bo nie potrafię przestać. — E.D.”"}}], "rola": "detektyw udający zgłaszającego", "watki": ["Zaginiona", "Urząd", "pieniądze"], "tik": "mówi „zgodnie z regulaminem”", "potrzeba": "kwit z kierunkiem Mai", "slad": "200 $ za trop i walizka Mai", "sprite": "walizka", "face": null, "face2": null, "line": "11", "itemName": "Szara walizka z żółtym zamkiem", "inside": null}, {"id": "d22_jonah", "dzien": 22, "postac": "Jonah Pike, 22", "glos": "Mówi szybko, poprawia się w pół zdania. Kiedy pada imię June, zwalnia.", "typ": "kurier, który wraca z dobrą wiadomością i długiem", "rzecz": "Biała koperta z napisem „K.M.”", "wnetrze": [{"sekret_id": "d22_koperta_km", "co_widac": "W kopercie 90 $ w banknotach i kartka z ołówkowym dopiskiem: „Ostatnia rata. K.M.” Obok trzy rubryki dat, dwie przekreślone.", "co_z_tego_wynika": "Pieniądze Jonaha idą do tego samego człowieka, któremu Ty też jesteś winien. Ktoś liczy raty na obu."}], "wejscie": "Jonah. Pamiętasz? Plecak. June powiedziała tak. Zgubiłem teraz kopertę, białą, z napisem K.M., dziewięćdziesiąt dolarów na ratę. Wypadła z kieszeni w czwórce. Proszę, bardzo proszę.", "wejscie_jesli": {"d2_jonah:wydaj": "Jonah. Pamiętasz? Plecak, pierścionek. June powiedziała tak! Zgubiłem teraz kopertę, białą, z napisem K.M. Dziewięćdziesiąt dolarów raty. Wypadła w czwórce. Proszę.", "d2_jonah:wez_pierscionek": "Jonah. Ten od plecaka, bez pierścionka. June i tak powiedziała tak, z serwetką. Zgubiłem kopertę, białą, K.M., dziewięćdziesiąt dolarów raty. Proszę, szukajcie.", "d2_jonah:odmow": "Jonah. Ten, co wrócił po plecak z kolegą. June powiedziała tak. Teraz kopertę zgubiłem, białą, K.M., dziewięćdziesiąt dolarów raty. Proszę, bardzo proszę."}, "tury": [{"pytania": [{"tekst": "Co jest w tej kopercie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dziewięćdziesiąt dolarów w banknotach i kartka z podpisem. Rata dla człowieka, którego nie nazywam, bo i tak wiesz, kto to.", "mina": "mowi"}, {"tekst": "Kiedy ją zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Dziś o piątej, na końcu czwórki. Wiem, bo wysiadałem, żeby zdążyć do June, i dopiero na schodach zobaczyłem, że kieszeń płasko leży.", "mina": "mowi"}, {"tekst": "Komu jesteś winien te pieniądze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Marlowowi. Kubie Marlowowi. Pożyczył na pierścionek i na wesele. Teraz mówi, że rata rośnie, jak się zgubi kopertę.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jak poszły oświadczyny z June?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Powiedziała tak. Jeszcze raz: tak! Płakała i śmiała się naraz. Ślub w czerwcu. Zapraszam, jeśli Ci to nie przeszkadza.", "mina": "emocja"}, {"tekst": "Ile jeszcze jesteś winien Marlowowi?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Z tą ratą zostanie jeszcze trzysta sześćdziesiąt. Czyli sześć sobót. Liczę na ślub, bo goście dadzą na koperty.", "mina": "mowi"}, {"tekst": "Co, jeśli koperty nie ma w biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "To spłacę z czynszu. June się dowie, bo musi. Kuba nie przyjmuje wymówek, tylko pieniądze. Czasem uśmiech.", "mina": "emocja"}, {"tekst": "Na kopercie napisano ołówkiem „ostatnia rata”. Co to znaczy?", "ton": "niewygodne", "wymaga": "d22_koperta_km", "odpowiedz": "Że Kuba tak napisał, żebym nie liczył na ulgę. Czasem pożyczka to nie jest pieniądz. To otwarte drzwi dla niego.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz, jeśli odzyskasz kopertę?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Pobiegnę do Kuby, zanim się rozmyślę. A potem pojadę do June i powiem jej o długu. Wszystko.", "mina": "mowi"}, {"tekst": "Czy kto inny wie o tym długu?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "June nie. Moja matka tak, ale jej nie mówię, że to Marlow. Bo ona zna jego matkę i będzie wstyd.", "mina": "mowi"}, {"tekst": "Co Ci przeszkadza w mówieniu June?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Że będzie patrzyła na pierścionek jak na kredyt. Że spytam, czy kocha mnie, czy ratę. Głupie, ale tak myślę.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję! Nie wiem, jak dziękować. Biegnę do Kuby, a potem do June. Wszystko jej powiem. Dziś. Przysięgam.", "zysk": "Jonah spłaca ratę i zyskuje odwagę, żeby powiedzieć June prawdę.", "strata": "Jonah przynosi okienku ciężar, którego nie będzie umiał udźwignąć sam, i Marlow nie zapomni, kto go ratuje.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Jonah Pike: „Powiedziałem June. Spytała tylko: ile jeszcze? Policzyła i powiedziała, że razem damy radę. Dziękuję za kopertę.”"}}, {"akcja": "odmow", "reakcja": "Nie? Jak to nie? Dobrze, dobrze, rozumiem, że zasady. Ale Kuba tego nie zrozumie. Wrócę z kimś, kto potwierdzi, że to moje.", "zysk": "Okienko trzyma procedurę, a koperta zostaje w depozycie.", "strata": "Jonah wraca do Marlowa z pustymi rękami, a odsetki liczą się od jutra.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Jonah Pike: „Kuba policzył mi dwadzieścia dolarów za to, że nie miałem koperty. Mówi, że to nie kara, tylko procent.”"}}, {"akcja": "wez_90_marlow", "etykieta": "Zatrzymaj 90 $ i zalicz je na własny dług u Marlowa", "kasa": 90, "wymaga": "d22_koperta_km", "reakcja": "Gdzie… gdzie koperta? Przecież tu leżała. Proszę, tu pisało K.M., to przecież dla… ja mam ratę, ja nie mogę… Idę do Kuby.", "zysk": "90 $ ratują Twój czynsz i dług u Marlowa o jedną ratę.", "strata": "Jonah traci ostatnie pieniądze przed ślubem, a Marlow dowiaduje się, kto wziął kopertę z jego imieniem.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Kuba Marlow, przez kuzyna: „Rata sobotnia przyszła z innej ręki niż Jonaha. Dziękuję. Ręka też zostaje zapisana. — K.M.”"}}], "rola": "kurier z dobrą wiadomością i długiem", "watki": ["Marlow", "pieniądze"], "tik": "zwalnia na imieniu June", "potrzeba": "koperta K.M. z 90 $", "slad": "rata dla Marlowa w Twoich rękach", "sprite": "koperta", "face": null, "face2": null, "line": "4", "itemName": "Biała koperta z napisem „K.M.”", "inside": null}, {"id": "d23_iris_nora_victor", "dzien": 23, "postac": "Iris Bell, Nora Vance i Victor Crane", "glos": "Iris: cicho, uprzejmie, „nie lubię naciskać”, groźbę podaje jak prognozę pogody. Nora: po kolei, rzecz-osoba-skutek. Victor: krótko, „kto to podpisze?”.", "typ": "trzy strony i jedna kasetka", "rzecz": "Stalowa kasetka na rachunki z kluczykiem", "ludzie": {"iris": "Iris Bell", "nora": "Nora Vance", "victor": "Victor Crane"}, "wnetrze": [{"sekret_id": "d23_karta_rozliczenia", "co_widac": "W kasetce karta rozliczenia z podpisem Iris Bell i datą sprzed ośmiu lat. Pod spodem pokwitowanie dopłaty z okresu, kiedy nie jeździła jeszcze szóstką.", "co_z_tego_wynika": "Iris podpisywała cudze rozliczenia długo przed objęciem kamienicy. Ma w tym doświadczenie, o którym nie mówi."}], "wejscie": "Iris Bell, Nora Vance i Victor Crane, wszyscy przed zamknięciem rozliczenia. Kasetka na rachunki z szóstki. Każde z nas chce czegoś innego. Prosimy o wydanie w jednej wersji.", "wejscie_jesli": {"d18_iris_nora:rezerwacja_nora": "Iris Bell, Nora Vance i Victor Crane, rozliczenie, kasetka na rachunki z szóstki. Nora ma rezerwację z osiemnastego. Prosimy o wydanie w jednej wersji.", "d18_iris_nora:do_kontroli": "Iris Bell, Nora Vance i Victor Crane. Kasetka na rachunki. Victor ma już kopię z osiemnastego. Nora czekała, Iris czeka. Wszyscy chcą jednej wersji.", "d18_iris_nora:oferta_iris": "Iris Bell, Nora Vance i Victor Crane. Kasetka na rachunki. Iris przypomina o rozmowie z osiemnastego. Nora patrzy na nią, Victor na was oboje. Prosimy o wydanie w jednej wersji.", "d12_iris_nora:wydaj_iris": "Iris Bell, Nora Vance i Victor Crane, rozliczenie. Kasetka na rachunki z szóstki. Nora liczy, że wydano ją Iris, a Victor liczy, że jej nie wydano. Prosimy o wydanie w jednej wersji."}, "tury": [{"pytania": [{"tekst": "Co jest w kasetce?", "ton": "uprzejme", "wymaga": null, "kto": "iris", "odpowiedz": "Karta rozliczenia z moim podpisem i pokwitowanie dopłaty. Nora chce oryginałów, Victor listy nazwisk. Dopiero wtedy wiadomo, co jest czyje.", "mina": "mowi"}, {"tekst": "Nora, czego chcesz od kasetki?", "ton": "rzeczowe", "wymaga": null, "kto": "nora", "odpowiedz": "Po kolei: oryginały zaliczek, bo lokatorzy ich potrzebują. Okoye wpłaciła czterysta dolarów, wszyscy razem pięć tysięcy sześćset. Albo oni, albo my.", "mina": "mowi"}, {"tekst": "Victor, co weźmiesz, jeśli kasetka trafi do Ciebie?", "ton": "niewygodne", "wymaga": null, "kto": "victor", "odpowiedz": "Wszystko. Kopię i oryginał. Pierwszy raz zestawiłem zmiany z pięciu lat i kasetka jest jedyną stałą. Kto to podpisze? Ja. Jeden egzemplarz do Urzędu, jeden do akt.", "mina": "neutralna"}, {"tekst": "Iris, czemu w kasetce jest karta z Twoim podpisem sprzed ośmiu lat?", "ton": "niewygodne", "wymaga": "d23_karta_rozliczenia", "kto": "iris", "odpowiedz": "Bo wtedy też podpisywałam. Nie pytaj o szczegóły, bo ich nie pamiętam tak, jak ludzie myślą.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Iris, mogę zapytać o coś na osobności?", "ton": "uprzejme", "wymaga": null, "kto": "iris", "odpowiedz": "Jeśli Victor i Nora poczekają. Pytaj.", "mina": "neutralna", "ustawia": "d23_iris_sama"}, {"tekst": "Nora, co się stanie, jeśli oryginały trafią do Victora?", "ton": "rzeczowe", "wymaga": null, "kto": "nora", "odpowiedz": "Po kolei: Urząd je zatrzyma, lokatorzy zostaną bez dowodu, kamienica pójdzie pod młot. Rodzina Okoye wyląduje na ulicy w grudniu.", "mina": "emocja"}, {"tekst": "Victor, dla kogo naprawdę liczysz tę kopię?", "ton": "niewygodne", "wymaga": null, "kto": "victor", "odpowiedz": "Dla Urzędu. Kto czyta kopie, to nie moja sprawa. Ale każdy, kto płaci, ma dostęp. Nie podpisuję się pod tym, co dzieje się później.", "mina": "emocja"}, {"tekst": "Iris, na stronie rejestru są nazwiska klientów. Skąd je masz?", "ton": "niewygodne", "wymaga": "kopie_2", "kto": "iris", "odpowiedz": "Z kopii Urzędu. Proszę zobaczyć: wszystko, co zapisano w dwóch egzemplarzach, jest tutaj. To, co się zapisuje, ktoś czyta.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Iris, co będzie po dzisiejszym dniu?", "ton": "uprzejme", "wymaga": null, "kto": "iris", "odpowiedz": "Dziś każdy dostaje bilet. Ty też. Ale nie z mojej ręki, dopóki ktoś nie podpisze po Tobie. Wolę poczekać.", "mina": "emocja"}, {"tekst": "Iris, ile wydałaś na papiery dla czterech osób?", "ton": "rzeczowe", "wymaga": null, "kto": "iris", "odpowiedz": "Tysiąc siedemset za sztukę. Sześć tysięcy osiemset. Wzięłam je od miasta, bo skąd mam wziąć. Lokatorom dałam ludzi, nie pieniądze. Jedno za drugie.", "mina": "emocja"}, {"tekst": "Iris, skąd wiesz, jak się naciska od środka?", "ton": "niewygodne", "wymaga": "d23_iris_sama", "kto": "iris", "odpowiedz": "Siedziałam w tym fotelu. Osiem lat temu. Nikt mnie nie szukał. Dlatego mnie wybrali. Nie lubię naciskać, bo wiem, jak to jest, kiedy ktoś naciska od środka.", "mina": "emocja"}, {"tekst": "Iris, ile zapłacisz, żeby tej kasetki nie było w protokole?", "ton": "niewygodne", "wymaga": null, "kto": "iris", "odpowiedz": "Pięćset dolarów. Lubię porządek. Wsunę kopertę pod szybę i nikt nie musi nic mówić.", "mina": "neutralna", "ustawia": "d23_oferta_500"}]}], "decyzje": [{"akcja": "wydaj_nora", "etykieta": "Wydaj oryginały Norze, zgodnie z rezerwacją", "kto": "nora", "reakcja": "Po kolei: oryginały, pokwitowania, podpis. Dziękuję. Lokatorzy mają dowód, a ja mam z czym iść do sądu. To jeszcze nie koniec, ale początek.", "zysk": "Lokatorzy dostają dowód, a Nora może walczyć o czternaście rodzin.", "strata": "Piórnik z żetonami przestaje być ukryty, a Iris traci wsparcie ludzi, których ukrywała.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Nora Vance: „Sąd przyjął oryginały. Pierwsza rozprawa za trzy tygodnie. Czternaście rodzin zostaje w kamienicy na zimę. Dziękuję.”"}, "wymaga": "d18_iris_nora:rezerwacja_nora|d18_iris_nora:nora_kopia"}, {"akcja": "wydaj_victor", "etykieta": "Przekaż kasetkę Victorowi do Urzędu", "kto": "victor", "reakcja": "Dwa egzemplarze: jeden do Urzędu, jeden do akt. Kto to podpisze? Ja. Dziękuję. Protokół zamknięty o szóstej.", "zysk": "Urząd dostaje komplet, a protokół zamyka się czysto.", "strata": "Skrytka znika razem z klientami, a nazwiska z kasetki trafiają do rąk, którym nie ufasz.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Victor Crane: „Rozliczenie zamknięte. Lista nazwisk w aktach. Zalecam dyskrecję. — V.C.”"}}, {"akcja": "iris_prywatnie", "etykieta": "Domknij prywatne wydanie Iris, bez protokołu", "kto": "iris", "reakcja": "Dziękuję. Cieszy mnie, że się rozumiemy. Zapomnijmy, że byłam dziś w kolejce. Za godzinę jadę.", "zysk": "Iris wyjeżdża cicho, a Ty zostajesz czysty w protokole i czysty wobec Nory.", "strata": "Czternaście rodzin zostaje bez dowodu, a w okienku ktoś jeszcze odpowiada za to, co zniknęło.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Nora Vance: „Oryginałów nie ma. Iris wyjechała. Nie wiem, kogo pytać. Piszę do Ciebie, bo nie mam kogo.”"}}, {"akcja": "wez_500_iris", "etykieta": "Weź 500 $ od Iris i domknij jej prywatne wydanie", "kasa": 500, "wymaga": "d23_oferta_500", "kto": "iris", "reakcja": "Dziękuję. Pięćset, na szybie, bez podpisu. Uwielbiam rozumienie. Nikt się nie dowie, że tu byłam.", "zysk": "500 $ i spokój w okienku, Iris znika bez śladu.", "strata": "Czternaście rodzin bez dowodu, Nora składa skargę do Victora (Urząd +2), a wzięta koperta wraca w zakończeniu.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Nora Vance: „Iris była przy szybie z kopertą. Nie wiem, ile. Nikt mi nie powiedział. Nie piszę, żeby oskarżać. Piszę, żeby wiedzieć.”"}}], "rola": "trzy strony jednej kasetki", "watki": ["Skrytka", "Fotel", "kamienica", "Urząd"], "tik": "Iris „drobna przysługa”", "potrzeba": "kasetka z oryginałami przed zamknięciem", "slad": "Iris siedziała w fotelu osiem lat temu", "sprite": "klucze", "face": null, "face2": null, "line": "6", "itemName": "Stalowa kasetka na rachunki z ", "inside": null}, {"id": "d23_rosa", "dzien": 23, "postac": "Rosa Vale, 33", "glos": "Zmęczona, praktyczna, liczy na głos. Krótkie zdania, suchy humor.", "typ": "stała klientka, która wraca po wszystkim", "rzecz": "Cienki portfel z zatrzaskiem", "wnetrze": [{"sekret_id": "d23_portfel_rosa", "co_widac": "W kieszonce portfela złożona kartka: „6 800 / 4” i data tygodniowej wpłaty dla jednej z pralni. Nie jej pismo.", "co_z_tego_wynika": "Ktoś z kręgu Iris włożył Rosie kartkę, której ona nie rozumie. To sygnał, że sieć sięga dalej niż piórnik."}], "wejscie": "Rosa Vale. Pralnia pod estakadą, pamiętasz. Zgubiłam portfel w jedenastce, cienki, z zatrzaskiem. Sześćdziesiąt dolarów na czynsz, nic więcej. Nie narzekam, tylko liczę.", "wejscie_jesli": {"d23_iris_nora_victor:wydaj_nora": "Rosa Vale. Wiem, co się stało w kamienicy. Dziękuję, że ktoś wydał rzeczy ludziom, nie Urzędowi. Zgubiłam portfel w jedenastce, cienki, z zatrzaskiem. Sześćdziesiąt dolarów.", "d23_iris_nora_victor:wydaj_victor": "Rosa Vale. Słyszałam o kasetce. Wiem, że dało się inaczej. Zgubiłam portfel w jedenastce, cienki, z zatrzaskiem. Sześćdziesiąt dolarów.", "d23_iris_nora_victor:iris_prywatnie": "Rosa Vale. Słyszałam, że ktoś wyjechał z pieniędzmi. Nie pytam, kto. Zgubiłam portfel w jedenastce, cienki, z zatrzaskiem. Sześćdziesiąt dolarów.", "d23_iris_nora_victor:wez_500_iris": "Rosa Vale. Słyszałam, że ktoś wyjechał z pieniędzmi i ktoś inny je wziął. Nie pytam, kto. Zgubiłam portfel w jedenastce, cienki, z zatrzaskiem. Sześćdziesiąt dolarów."}, "tury": [{"pytania": [{"tekst": "Jak wygląda ten portfel?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, cienki, zatrzask pękł z lewej. W środku bilet miesięczny i sześćdziesiąt dolarów w dwóch dwudziestkach i dwóch dziesiątkach.", "mina": "mowi"}, {"tekst": "Gdzie go zgubiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W jedenastce, po nocnej zmianie. Wyjęłam go, żeby sprawdzić godzinę odjazdu, i położyłam obok. Typowe, jak człowiek się spieszy do łóżka.", "mina": "mowi"}, {"tekst": "Skąd masz pieniądze na czynsz, skoro pracujesz za grosze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Z nocy w pralni i z tego, że nie jem w poniedziałki. To nie jest historia na chwałę, tylko na rachunek.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Słyszałaś, co się dzieje w kamienicy Cooper?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Że nie tylko Cooper. Że w tym mieście wszystko jest na kredyt: kamienice, ludzie, nawet cisza. Nie wiem więcej, nie pytam.", "mina": "mowi"}, {"tekst": "Co zrobisz z pieniędzmi, jeśli je odzyskasz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Zapłacę czynsz. A jak zostanie reszta, to kupię Adzie lalkę. Pytała o tę z różowym warkoczem. Nie powiem jej, że to z zaległych.", "mina": "mowi"}, {"tekst": "Czy ktoś ze Skrytki prosił Cię kiedyś o przysługę?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Skrytki? Nie wiem, o czym mówisz. Ale pani Bell kiedyś pytała, czy umiem być cicho. Odpowiedziałam, że tak, bo to bezpłatne.", "mina": "emocja"}, {"tekst": "W portfelu jest kartka z zapisem „6 800 / 4”. Co to?", "ton": "niewygodne", "wymaga": "d23_portfel_rosa", "odpowiedz": "To nie moje. Kartka musiała tam trafić w tramwaju. Albo ktoś mi ją podrzucił. Nie dotykam. Nie chcę być tą, która zobaczyła.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Rosa, co chcesz, żeby się stało po dzisiejszym dniu?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Żeby było cicho. Żebym rano wsiadła do tramwaju i nikt nie pytał, skąd mam czynsz. Dobrze byłoby jeszcze zjeść coś ciepłego.", "mina": "mowi"}, {"tekst": "Co zrobisz, jeśli portfela nie ma?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Pożyczę. Pożyczać umiem. Tylko że potem trzeba oddawać, a ja już teraz oddaję więcej, niż biorę.", "mina": "mowi"}, {"tekst": "Czy komuś ufasz bardziej niż nam?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nikomu. Ufam kartce i długopisowi. Jak jest zapisane, to wiem, że nikt nie zmieni zdania.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Sześćdziesiąt. Zgadza się. Dziękuję. Cicho, bez opowieści. Tak lubię najbardziej.", "zysk": "Rosa płaci czynsz, a okienko zostaje czyste w jej pamięci.", "strata": "Przy kolejnych sprawach Rosa już nie powie nic, bo nie ma czego.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Rosa Vale: „Czynsz zapłacony. Ada ma lalkę. Nie mówię, od kogo. Proszę po prostu wiedzieć.”"}}, {"akcja": "odmow", "reakcja": "Dobrze. Wrócę z kimś, kto potwierdzi. Tylko że ja nie mam takiego kogoś. Mam kartkę.", "zysk": "Okienko trzyma procedurę.", "strata": "Rosa nie ma czym zapłacić czynszu, a pralnia nie czeka.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Rosa Vale: „Pożyczyłam od sąsiadki. Oddam w piątek, z odsetkami. Nie pytam, kto zawinił.”"}}, {"akcja": "wez_20_rosa", "etykieta": "Zatrzymaj 20 $ z portfela Rosy", "kasa": 20, "wymaga": "d23_portfel_rosa", "reakcja": "Czterdzieści? Przeliczę jeszcze raz. …Brakuje dwudziestu. Nie powiem, bo kto mi uwierzy. Dziękuję, że w ogóle jest.", "zysk": "20 $ w kieszeni i spokój do soboty.", "strata": "Rosa liczy dłużej, niż powinna, a Ty wiesz, że ona wie.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Rosa Vale: „Przeliczyłam portfel w domu. Dwadzieścia mniej. Nie przychodzę z pretensją. Przychodzę, żeby wiedzieć, że wiem.”"}}], "rola": "praczka, która liczy i milczy", "watki": ["kamienica", "pieniądze"], "tik": "liczy na głos", "potrzeba": "portfel z czynszem 60 $", "slad": "kartka „6 800 / 4” od Iris", "sprite": "portfel", "face": null, "face2": null, "line": "11", "itemName": "Cienki portfel z zatrzaskiem", "inside": null}, {"id": "d24_vera", "dzien": 24, "postac": "Vera Kovacs, 62", "glos": "Najpierw miejsce, potem rzecz, na końcu nazwisko. Dzwoni kluczami przy pasie, kiedy się wstydzi.", "typ": "zaplecze, które przychodzi się przyznać", "rzecz": "Szara teczka z kartonikiem „szafka 0809”", "ludzie": {"vera": "Vera Kovacs"}, "wnetrze": [{"sekret_id": "d24_kartonik", "co_widac": "Kartonik: „SZAFKA 0809” ołówkiem. Z tyłu: „nie otwierać do odwołania”, pismo Sama, i pieczątka zaplecza.", "co_z_tego_wynika": "Szafka 0809 jest zajęta celowo, żeby nikt jej nie likwidował. Tak jak każde miejsce, które czeka na kogoś."}, {"sekret_id": "d24_umowa", "co_widac": "Umowa gracza z Zarządem Nieruchomości Cooper. Podpis nieczytelny, z charakterystyczną pętlą w literze K. Data: dziewiąty sierpnia.", "co_z_tego_wynika": "Podpis na Twojej umowie jest Very, z pierwszego dnia. Ktoś wszystko przygotował, zanim przyszło się po raz pierwszy."}], "wejscie": "Zaplecze, teczka, Vera Kovacs. Przyszłam sama, bez Iris i bez Victora. Mam kartonik z numerem szafki i jedną rzecz do powiedzenia. To ja wybieram. Od jedenastu lat. Wstyd mam od dawna.", "tury": [{"pytania": [{"tekst": "Co jest w szafce 0809?", "ton": "uprzejme", "wymaga": null, "kto": "vera", "odpowiedz": "Pusta teczka i list. Teczka od zawsze „zajęta”, a list jest pismem Sama, którego nie czytałam. Klucz trzymam ja. Dzwoni, jak widać.", "mina": "mowi"}, {"tekst": "Skąd masz ten kartonik?", "ton": "rzeczowe", "wymaga": null, "kto": "vera", "odpowiedz": "Z szuflady numer sześć, tej, którą Sam zostawił dla następnego. Wzięłam wczoraj. Dziś nie umiem go odłożyć.", "mina": "mowi"}, {"tekst": "Czemu przyszłaś sama?", "ton": "niewygodne", "wymaga": null, "kto": "vera", "odpowiedz": "Bo to nie jest sprawa dla Victora ani dla Iris. Sam zostawił mi pustą teczkę i nie wiem, co z nią zrobić. Z klucza się nie wymiga.", "mina": "emocja"}, {"tekst": "Na umowie jest pętla w literze K. Czyj to podpis?", "ton": "niewygodne", "wymaga": "d24_umowa", "kto": "vera", "odpowiedz": "Mój. Podpisałam za Zarząd Cooper, bo ktoś musiał. Nieczytelnie, żeby nikt nie szukał, kto stał za tym podpisem.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czym tak naprawdę zajmujesz się w tym biurze?", "ton": "uprzejme", "wymaga": null, "kto": "vera", "odpowiedz": "Kluczami, teczkami, pudełkami. Zapleczem. Fotel nie jest karą. Fotel jest bezpiecznikiem. Najpierw miejsce, potem rzecz. Kiedy ktoś ma gdzie postawić stopę, resztę da się zrobić.", "mina": "mowi"}, {"tekst": "Kto napisał na kartoniku „nie otwierać”?", "ton": "rzeczowe", "wymaga": null, "kto": "vera", "odpowiedz": "Sam, ołówkiem. Jego pismo, ale nie jego decyzja. Dostał to, co dostaje każdy: cudzą regułę, którą musi udawać, że sam wymyślił.", "mina": "mowi"}, {"tekst": "O jaki wstyd Ci chodzi?", "ton": "niewygodne", "wymaga": null, "kto": "vera", "odpowiedz": "O kryterium. Że od lat patrzę na ludzi i wybieram, kto się nadaje. Nie pytam o kwalifikacje, tylko czy ktoś by go szukał.", "mina": "emocja"}, {"tekst": "Co jest w szafce poza pustą teczką?", "ton": "niewygodne", "wymaga": "d24_kartonik", "kto": "vera", "odpowiedz": "List. Sam pisał go pięć razy, ostatnio w niedzielę. Nie czytałam. Ma trafić do tego, kto będzie siedział przy szybie po nim.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobisz z kluczem, jeśli go nie przyjmę?", "ton": "uprzejme", "wymaga": null, "kto": "vera", "odpowiedz": "Zostawię na ladzie. Nie mam już komu go oddać. Klucz sam się nie otworzy, ale też nie zginie.", "mina": "mowi"}, {"tekst": "Kto wie, że przyszłaś?", "ton": "rzeczowe", "wymaga": null, "kto": "vera", "odpowiedz": "Nikt. Powiedziałam Leo, że idę po szpulę nici. Kłamię słabo, ale on nie sprawdza. To jego cecha, nie moja zasługa.", "mina": "mowi"}, {"tekst": "Kto wybiera ludzi na to miejsce?", "ton": "niewygodne", "wymaga": null, "kto": "vera", "odpowiedz": "To ja wybieram. Od jedenastu lat. Wybieram tych, których nikt nie szuka, bo fotel to bezpiecznik. Czwarty został znaleziony w kanale. Jego siostra do dziś szuka go po szpitalach.", "mina": "emocja"}, {"tekst": "Czy ktoś kazał Ci to powiedzieć?", "ton": "niewygodne", "wymaga": "d24_umowa", "kto": "vera", "odpowiedz": "Nikt. Mówię, bo Sam odszedł i ktoś musi wiedzieć, że nie był pierwszym. Przed nim siedzieli inni, a kartoników jest więcej, niż myślisz.", "mina": "emocja"}]}], "decyzje": [{"akcja": "dolacz_slad", "etykieta": "Dołącz ślad odejścia Sama za jego zgodą", "kto": "vera", "reakcja": "Zapisuję: odejście bez wpisu, z mojej woli. Sam odzyska twarz. Strona 41 jest Twoja.", "zysk": "Sam odzyskuje czyste akta, a Vera oficjalnie bierze winę za teczkę.", "strata": "Ślad trafia do księgi, więc ktoś, kto czyta wszystko, dowie się, że teczka była pusta.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Sam Holt: „Dowiedziałem się, że ktoś dołączył ślad mojego odejścia. Nie prosiłem. Dziękuję. To pierwszy raz, kiedy ktoś zapisał to, co zrobiłem, a nie to, co zgłosiłem.”"}}, {"akcja": "koperta_zapieczetowana", "etykieta": "Oddaj dokument Samowi w zapieczętowanej kopercie", "kto": "vera", "reakcja": "Zapieczętowana. Sam zdecyduje sam. A strona 41 jest Twoja.", "zysk": "Sam sam decyduje, co zrobić z dokumentem, a Vera nie musi niczego wyznawać w księdze.", "strata": "Okienko nie zostawia śladu, więc nikt nie zapisze, że Vera przyszła.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Sam Holt: „Dostałem kopertę. Zapieczętowana. Nie otwarłem jej przy nikim. Dziękuję, że wybór został mój. — S.”"}}, {"akcja": "otworz_szafke", "etykieta": "Otwórz szafkę 0809 kluczem Very", "kto": "vera", "reakcja": "Klucz. Sam zostawił to dla tego, kto siedzi przy szybie. Strona 41 jest Twoja.", "zysk": "W szafce leży list od Sama, a w tle brzęczą klucze Very.", "strata": "Ktoś zobaczy, że szafka była otwarta, a w nocy wszystko jest widoczne dla tego, kto patrzy.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Vera Kovacs: „Szafka otwarta, teczka pusta, list wyjęty. Spokojnie. Nie powiem nikomu, że widziałam. Powiem tylko, że byłam.”"}}], "rola": "zaplecze, które przychodzi się przyznać", "watki": ["Fotel", "Skrytka", "Poprzednik"], "tik": "dzwoni kluczami", "potrzeba": "oddać klucz do szafki 0809", "slad": "od jedenastu lat wybiera, kto siądzie w fotelu", "sprite": "teczka", "face": null, "face2": null, "line": "6", "itemName": "Szara teczka z kartonikiem „sz", "inside": null}, {"id": "d24_leo", "dzien": 24, "postac": "Leo Marsh, 46", "glos": "Mówi godzinami i przystankami. Dziś mówi mniej, bo coś niesie. Patrzy na torbę, nie na szybę.", "typ": "konduktor, który przynosi ostatni kurs", "rzecz": "Skórzana torba konduktora z wykazem kursu", "wnetrze": [{"sekret_id": "d24_wykaz_0809", "co_widac": "Ostatnia pozycja wykazu: „0809, dokumenty, paczka w płótnie, nieodebrana”. Dopisek: „dyżurny”. Podpis Very, pismo jakby kopiowane.", "co_z_tego_wynika": "Skrytka ma paczkę z dokumentami dla dyżurnego, czyli dla Ciebie. Wyjście istnieje, ale nikt nie powiedział, ile kosztuje."}, {"sekret_id": "d24_numer_puszka", "co_widac": "W torbie puszka po herbacie z numerem 0809 wypisanym markerem na wieczku, identyczna jak ta z dnia 6.", "co_z_tego_wynika": "Puszka i paczka 0809 należą do tego samego obiegu Skrytki. Leo wozi ją od dawna, nie otwierając."}], "wejscie": "Leo, konduktor szóstki. Zgubiłem torbę z wykazem, skórzaną, z mosiężnym zapięciem. W środku ostatni wykaz paczek w płótnie. Dziś ostatni kurs i jedna paczka ma wpis, którego nie rozumiem.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta torba?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Skórzana, brązowa, mosiężne zapięcie, wytarta na rogach. W środku bilety, notes i wykaz paczek. Torba ma ponad dwadzieścia lat, nosił ją jeszcze mój ojciec.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie ją zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na pętli szóstki, o czwartej. Położyłem na ławce, bo musiałem zapalić. Zazwyczaj zabieram, ale dziś coś mnie rozpraszało. Wpis w wykazie.", "mina": "mowi"}, {"tekst": "Co to za wpis, którego nie rozumiesz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Pozycja ostatnia: „0809, dokumenty, paczka w płótnie, nieodebrana”. Tego numeru nigdy nie woziłem. Zwykle wiem, czyja paczka, a ta ma tylko numer.", "mina": "emocja"}, {"tekst": "W wykazie obok pozycji 0809 ktoś dopisał „dyżurny”. Co to znaczy?", "ton": "niewygodne", "wymaga": "d24_wykaz_0809", "odpowiedz": "Że paczka nie jest dla klienta. Jest dla tego, kto stoi po tej stronie szyby. Nie wiem, czemu nikt mi tego nie powiedział.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Od jak dawna wozisz paczki w płótnie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Od dawna, może dłużej. Zacząłem, bo Vera prosiła. Mówiła: kurs, godzina, nic więcej. Nie pytałem. Nie wolno mi było.", "mina": "mowi"}, {"tekst": "Co zwykle jest w paczce?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Dokumenty, trochę gotówki w kopercie, czasem klucz. Nigdy nie zaglądam. Płótno jest zszyte tak, że widać, jeśli ktoś próbował.", "mina": "mowi"}, {"tekst": "Czy wiesz, kto wysłał paczkę 0809?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie wiem. Wykaz podpisuje Vera. Ale nie jej pismem, a przeniesionym, jakby ktoś dyktował. Nie lubię tego.", "mina": "emocja"}, {"tekst": "Co się stanie, jeśli paczka nie zostanie odebrana?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wróci do Very. Zostanie w szafce. Ostatni kurs się powtórzy za miesiąc, a ja będę znów wiózł pustą torbę.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Jak się czujesz, wożąc paczki, o których nic nie wiesz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Jak maszynista z ręką na hamulcu, który nie widzi, co jest przed nim. Jadę, bo tak mam. I mam żonę, która pyta, co wiozę.", "mina": "emocja"}, {"tekst": "Co zrobisz z wykazem po dzisiejszym dniu?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Oddam okienku, jeśli ktoś wpisze. Jeśli nie, zachowam. Nie potrzebuję się z nikim dzielić, ale nie chcę być sam z kartką.", "mina": "mowi"}, {"tekst": "Kto naprawdę czeka na tę paczkę?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie wiem. Ale na pętli stoi człowiek w szarym kapeluszu i patrzy na każdą torbę. Z kim rozmawia, to już nie moja sprawa.", "mina": "emocja"}, {"tekst": "W torbie jest puszka z numerem 0809 na wieczku. Czyja?", "ton": "niewygodne", "wymaga": "d24_numer_puszka", "odpowiedz": "Nie moja. Wożę ją, bo mi powiedziano, żebym woził. Numer znam, wieczko znam, w środku nie byłem. Nie wolno mi było, a ja nie pytałem.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wpisz_wykaz", "etykieta": "Wpisz wykaz kursu do księgi, w dwóch egzemplarzach", "reakcja": "Wpisane. Dwa egzemplarze, jak trzeba. Jeśli ktoś pyta, wszystko było według procedury. Nie wiem, czyja to ulga.", "zysk": "Wykaz trafia do księgi, a Leo ma dowód, że zrobił swoje.", "strata": "Kopia trafia do Urzędu, więc ktoś dowie się o numerze 0809 i o tym, że ktoś go nie odebrał.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Victor Crane: „W aktach pojawił się wykaz kursu z pozycją 0809, bez nazwiska odbiorcy. Proszę wyjaśnić do piątku. — V.C.”"}}, {"akcja": "przechowaj_bez_kwitu", "etykieta": "Przechowaj torbę bez kwitu, tak jak Sam", "reakcja": "Bez kwitu. Dobrze. Wolę, żeby nie zostawało po mnie nic na papierze. Dziękuję, że nie pytasz o wszystko po kolei.", "zysk": "Leo odchodzi bez śladu w papierach, a wykaz zostaje w okienku.", "strata": "Przy kolejnej kontroli okienko nie pokaże, skąd się wzięła torba. Uczciwość stoi w kącie.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Leo Marsh: „Torbę zostawiłem. Nic nie podpisałem. Spytali na pętli, czy coś wiem. Powiedziałem, że wożę tylko to, co mi dają. Prawda i kłamstwo naraz.”"}}, {"akcja": "odeslij_wykaz", "etykieta": "Odeślij wykaz Verze z powrotem", "reakcja": "Do Very. Dobrze. Niech sama odpowie za swój wpis. Tylko że ona nie odpowie, ona ma klucze.", "zysk": "Wykaz wraca do osoby, która go podpisała, a okienko nie bierze w tym udziału.", "strata": "Vera dowie się, że okienko go widziało, a ktoś w Skrytce zacznie przeliczać, ile wiesz.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Vera Kovacs: „Leo wrócił z wykazem. Powiedział, że okienko odesłało. Nie zdziwiłam się. Zdziwiłam się, że ulżyło.”"}}], "rola": "konduktor z ostatnim wykazem", "watki": ["Skrytka", "Fotel"], "tik": "patrzy na torbę", "potrzeba": "torba z wykazem paczek", "slad": "pozycja 0809: dokumenty czekają na dyżurnego, czyli Ciebie", "sprite": "torba_narzedzia", "face": null, "face2": null, "line": "6", "itemName": "Skórzana torba konduktora z wy", "inside": null}, {"id": "d24_thomas", "dzien": 24, "postac": "Thomas Ward, 71", "glos": "Grzecznie, trochę staroświecko. Żartuje z własnej drżącej ręki. Dziś nie żartuje.", "typ": "staruszek, który wraca z własnym świadectwem", "rzecz": "Biała koperta z odręcznym świadectwem", "wnetrze": [{"sekret_id": "d24_kwit_0417", "co_widac": "W kopercie, obok świadectwa, kwit 0417 z tego biura i dopisek ołówkiem: „Prawa wydana bez wpisu. Lewa czeka. S.H.”", "co_z_tego_wynika": "To ten sam kwit, który Thomas miał w mankiecie w pierwszym dniu. Sam zaczynał każdego następnego tak samo."}], "wejscie": "Dobry wieczór. Thomas Ward. Zostawiłem u was kopertę ze świadectwem dla Sama, z moim pismem. Wnuk mówi, że leżała na ladzie. Proszę, jeśli ktoś ją widział, niech sprawdzi.", "wejscie_jesli": {"d1_thomas:wydaj": "Dobry wieczór. Thomas Ward, znowu. Przyniosłem kopertę ze świadectwem dla biura. Rękawiczkę dostałem, dziękuję. Chcę teraz zapisać, że ktoś kiedyś oddał mi rzecz bez papieru.", "d1_thomas:wydaj_bez_wpisu": "Dobry wieczór. Thomas Ward. Tak jak wtedy: bez papierka. Przyniosłem teraz świadectwo, bo ktoś powinien zapisać, że ten młody człowiek zrobił mi dobrze. Wnuk twierdzi, że kopertę zostawił tu.", "d1_thomas:zatrzymaj_sprawdz": "Dobry wieczór. Thomas Ward. Rękawiczka wróciła w końcu, po kilku dniach, z córką. Przyniosłem świadectwo dla Sama, bo ktoś kiedyś oddał mi prawą bez wpisu. Nie wiem, kto odpowie."}, "tury": [{"pytania": [{"tekst": "Co jest w tej kopercie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Jedna kartka, pisana moją ręką. Że rzecz, którą młody człowiek mi kiedyś oddał, oddał bez papieru, bo wiedział, że nie przeżyję niedzieli bez niej.", "mina": "mowi"}, {"tekst": "Kiedy to było?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Sześć tygodni temu. Prawą oddał od razu. Lewa czekała, jak powiedział. Przyszedłem wtedy po rękawiczkę, a on tylko skinął głową.", "mina": "mowi"}, {"tekst": "Czemu piszesz świadectwo, skoro nikt o nie nie prosi?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo ktoś powinien zapisać, że ten człowiek nie robił nic złego. Zrobił wyjątek, i dobrze. Niech to będzie na papierze, bo mnie za rok nie będzie.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jak sobie radzisz od śmierci żony?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dwa razy w tygodniu na cmentarz. Rozmawiam z nią o rękawiczce. Mówi, że byłem leniwy, skoro nie zszyłem czarną nitką.", "mina": "mowi"}, {"tekst": "Kto jeszcze zna tę historię?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Córka, Claire. I ten młody człowiek, Sam. Powiedział mi kiedyś: lewa czeka. Nie wiedziałem, że to znaczy tyle co: wróć, a oddam.", "mina": "mowi"}, {"tekst": "Czy Sam kiedyś Ci coś obiecał?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Że lewa poczeka. Dotrzymał. To więcej, niż potrafią niektórzy w rodzinie.", "mina": "mowi"}, {"tekst": "W kopercie jest kwit 0417 z dopiskiem. Co on znaczy?", "ton": "niewygodne", "wymaga": "d24_kwit_0417", "odpowiedz": "Że wtedy skłamałem. Powiedziałem, że to pierwsza wizyta. Nie była. Wstydziłem się, że znowu mi się rzecz zgubiła. Kwit to dowód, że mnie tu znają.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co chcesz, żeby się stało z tym świadectwem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Żeby ktoś je przeczytał. I żeby nikt nie wyrzucił. Jeśli to nie jest dla księgi, to chociaż dla szuflady.", "mina": "mowi"}, {"tekst": "Czy świadectwo ma jakieś znaczenie prawne?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Nie wiem. Ale jak się jest starym, to wierzysz, że papier jest tylko papierem, dopóki ktoś go nie przeczyta.", "mina": "mowi"}, {"tekst": "Czego się boisz?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Że ten młody człowiek odchodzi, a ja nie zdążyłem podziękować. Że za rok to ja zniknę, a nikt nie będzie wiedział, kim był ktoś, kto oddał mi rękawiczkę.", "mina": "emocja"}]}], "decyzje": [{"akcja": "przyjmij_swiadectwo", "etykieta": "Przyjmij świadectwo do akt Sama, z wpisem", "reakcja": "Dziękuję. Tak. Do akt, z wpisem. Wiem, że to papier. Ale tak powinno być, żeby ktoś mógł to przeczytać po nas obu.", "zysk": "Sam dostaje pisemne świadectwo, że oddał rzecz z sercem, a Thomas ma poczucie, że spłacił dług.", "strata": "Świadectwo trafia do księgi, więc ktoś, kto ją przeczyta, dowie się o wydaniu bez wpisu.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Thomas Ward: „Poszedłem na cmentarz w niedzielę. Opowiedziałem Ellen, że świadectwo jest w księdze. Powiedziała, że dobrze, że ktoś zapisał to wreszcie.”"}}, {"akcja": "oddaj_bez_wpisu", "etykieta": "Zwróć świadectwo Thomasowi i niczego nie wpisuj", "reakcja": "Rozumiem. Zatrzymam przy sobie. Może to właściwe: rzeczy, które się nie zapisuje, bywają najpewniejsze.", "zysk": "Świadectwo zostaje u Thomasa, a okienko nie wystawia Sama na kolejne oczy.", "strata": "Nikt poza Thomasem nie wie, że Sam oddał rzecz bez wpisu, więc Sam nie ma jak się obronić.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Thomas Ward: „Świadectwo mam w kieszeni, obok rękawiczek Ellen. Jak ktoś zapyta, pokażę. Nikt nie pyta.”"}}, {"akcja": "wpisz_wstecz", "etykieta": "Wpisz wydanie sprzed sześciu tygodni w dzisiejszej księdze", "reakcja": "Wstecz? Można tak? Dziękuję. Rozumiem. Jeśli to naprawia, to dobrze, że można.", "zysk": "Wydanie Sama dostaje wpis z datą wsteczną i stają się czyste papiery.", "strata": "Wpis wsteczny to fałszerstwo. Jeśli Urząd przyjrzy się datom, okienko ma problem.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Victor Crane: „W księdze pojawił się wpis wsteczny, sprzed sześciu tygodni, bez numeru kwitu. Do wyjaśnienia. — V.C.”"}}], "rola": "staruszek ze świadectwem dla Sama", "watki": ["Poprzednik"], "tik": "dziś nie żartuje", "potrzeba": "świadectwo przyjęte do akt", "slad": "kwit 0417 domyka rękawiczkę z dnia 1", "sprite": "koperta", "face": null, "face2": null, "line": "4", "itemName": "Biała koperta z odręcznym świa", "inside": null}, {"id": "d25_sam_elias", "dzien": 25, "postac": "Sam Holt, Elias Wren i Victor Crane", "glos": "Sam: najpierw szczegół techniczny, potem człowiek. Elias: powoli, staroświecko, uparcie. Victor: krótko, „kto to podpisze?”.", "typ": "trzej mężczyźni i jedno etui", "rzecz": "Etui na okulary z kopią decyzji o odejściu", "ludzie": {"sam": "Sam Holt", "elias": "Elias Wren", "victor": "Victor Crane"}, "wnetrze": [{"sekret_id": "d25_etui_kopia", "co_widac": "W etui kopia decyzji o odejściu Sama i wpis o niedoborze na zmianie. W rubryce „następca” puste pole. Na marginesie ołówkiem: „0809”.", "co_z_tego_wynika": "Niedobór na zmianie to zwykły sposób zapisania odejścia dyżurnego. Pole następcy zostało puste celowo."}], "wejscie": "Sam Holt i Elias Wren przy szybie, Victor za nimi z teczką. Sam po etui na okulary, Elias z pytaniem, czy Sam już się odezwał, Victor z protokołem do zamknięcia. Sam, Elias i Victor chcą tego samego: żeby to się dziś skończyło.", "tury": [{"pytania": [{"tekst": "Co jest w tym etui?", "ton": "uprzejme", "wymaga": null, "kto": "sam", "odpowiedz": "Okulary, które nie są moje, i kartka z decyzją o odejściu, z wpisem o niedoborze na zmianie. Kopię zrobiłem dla siebie, na wszelki wypadek.", "mina": "mowi"}, {"tekst": "Victor, czemu zamykasz audyt dziś?", "ton": "rzeczowe", "wymaga": null, "kto": "victor", "odpowiedz": "Bo dziś kończy się okres. Protokół musi mieć podpis i daty. Kto to podpisze? Ja, jeśli kopia jest czytelna i kompletna.", "mina": "mowi"}, {"tekst": "Sam, czemu zostawiłeś Verze pustą teczkę?", "ton": "niewygodne", "wymaga": null, "kto": "sam", "odpowiedz": "Bo ktoś musiał zostawić coś nikomu. Teczkę, list, miejsce. Zostawiłem wszystkie trzy, żeby jedno z nich dotarło.", "mina": "emocja"}, {"tekst": "Na odwrocie kopii jest wpis: „Niedobór: pole następcy puste”. Co to?", "ton": "niewygodne", "wymaga": "d25_etui_kopia", "kto": "sam", "odpowiedz": "Że ktoś nie ma jeszcze nazwiska w tej kolumnie. Zostawiłem puste, żeby nikt go nie wpisał za niego. Victor, nie patrz tak.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Elias, po co dziś przyszedłeś?", "ton": "uprzejme", "wymaga": null, "kto": "elias", "odpowiedz": "Zapytać, czy Sam się odezwał. I zdążyć, zanim ktoś zamknie księgę. Księgi się zamyka, kiedy człowiek zasypia.", "mina": "mowi"}, {"tekst": "Sam, co będziesz robił po odejściu?", "ton": "rzeczowe", "wymaga": null, "kto": "sam", "odpowiedz": "Kolega z portu dzwoni dziś na biuro o piątej trzydzieści po referencje. Jeśli ktoś potwierdzi, że byłem uczciwym dyżurnym, dostanę robotę.", "mina": "mowi"}, {"tekst": "Victor, co się stanie, jeśli kopia nie zostanie dołączona?", "ton": "niewygodne", "wymaga": null, "kto": "victor", "odpowiedz": "Protokół będzie niepełny. Referencje wątpliwe. Kto to podpisze? Nie ja. Wolę komplet, bo komplet nie wraca z pytaniami.", "mina": "neutralna"}, {"tekst": "Sam, czy kopia decyzji powinna trafić do Urzędu?", "ton": "niewygodne", "wymaga": null, "kto": "sam", "odpowiedz": "Nie. Ale jeśli nie dołączę, nikt nie uwierzy, że odszedłem czysto. Taka to praca: obie opcje boli.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Sam, jak się czujesz, kiedy odchodzisz?", "ton": "uprzejme", "wymaga": null, "kto": "sam", "odpowiedz": "Lekko, z jednym wyjątkiem. Zostawiam komuś ciężką rzecz i nie zapytałem, czy chce.", "mina": "emocja"}, {"tekst": "Elias, co powiesz Samowi na pożegnanie?", "ton": "rzeczowe", "wymaga": null, "kto": "elias", "odpowiedz": "Że dziękuję za oprawkę. I że oddawałem pieniądze ludziom, którzy nie prosili. Zacząłem od niego. Przepraszam, że tak późno.", "mina": "emocja"}, {"tekst": "Sam, kto zajmie Twoje miejsce?", "ton": "niewygodne", "wymaga": null, "kto": "sam", "odpowiedz": "Nie wiem. Wiem, że nie powinien być sam z listem. Dlatego dziś przy okienku są wszyscy, którzy mogli komuś pomóc.", "mina": "emocja"}, {"tekst": "Victor, czemu pytasz o referencje Sama, skoro to nie Twoja sprawa?", "ton": "niewygodne", "wymaga": null, "kto": "victor", "odpowiedz": "Bo komplet to też referencja. Kto zamyka rozliczenie bez dziur, zostawia po sobie uczciwość. Nawet jeśli nie wie, czyją.", "mina": "mowi"}]}], "decyzje": [{"akcja": "dolacz_kopie", "etykieta": "Dołącz kopię do uzgodnionego sprostowania", "kto": "sam", "reakcja": "Dołączone, w dwóch egzemplarzach, jak trzeba. Sam wychodzi czysty, a ja podpisuję. Kto to podpisze? Ja. Dziękuję za sprawność.", "zysk": "Sam wychodzi czysty, a Victor zamyka audyt bez dziur.", "strata": "Kopia dokumentu trafia do Urzędu, a Urząd czyta to każdy, kto Urzędowi zapłaci.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Sam Holt: „Praca w porcie jest moja. Referencje przyszły przed szóstą. Nie wiem, czy to uczciwe, ale dziękuję.”"}}, {"akcja": "zwroc_etui", "etykieta": "Zwróć Samowi etui z całą zawartością", "kto": "sam", "reakcja": "Etui, okulary, kartka. Wszystko, jak leżało. Dziękuję. Protokół Victora zostaje, ale ja zostaję ze swoim.", "zysk": "Sam wychodzi z rzeczami, a decyzja jest jego i nikogo więcej.", "strata": "Protokół zostaje niepełny, a referencje mogą nie przyjść.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Sam Holt: „Etui wróciło. Praca w porcie jeszcze nieznana. Kolega powiedział, że oddzwoni. Dziękuję, że to było moje.”"}}, {"akcja": "zniszcz_kopie", "etykieta": "Zniszcz kopię przy Samie, bez wpisu", "kto": "sam", "reakcja": "Na oczach wszystkich. Dobrze. Teraz nikt jej nie przeczyta. Dziękuję. Zrobiłbym to samo, tylko ręka mi się trzęsie.", "zysk": "Sam nie ma już śladu w papierach, a Victor nie ma czego kopiować.", "strata": "Protokół zostaje z dziurą, a Victor zapisze, kto ją zrobił i przy świadkach.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Victor Crane: „Odnotowano zniszczenie dokumentu w obecności trzech osób. Brak wpisu. Przyjęto do wiadomości. Rozliczenie zamknięte z adnotacją. — V.C.”"}}], "rola": "trzej mężczyźni i jedno etui", "watki": ["Poprzednik", "Fotel", "Urząd"], "tik": "Elias składa numerek", "potrzeba": "etui z kopią decyzji", "slad": "w rubryce „następca” puste pole i 0809", "sprite": "okulary", "face": null, "face2": null, "line": "4", "itemName": "Etui na okulary z kopią decyzj", "inside": null}, {"id": "d25_ksiega", "dzien": 25, "postac": "Elias Wren", "glos": "Powoli, staroświecko, uparcie. Dziś mówi mniej. Trzyma numerek w obu rękach i patrzy na księgę, nie na szybę.", "typ": "księga wydań, otwarta na pustej linii", "rzecz": "Księga wydań otwarta na linii 0809", "ludzie": {"elias": "Elias Wren"}, "wnetrze": [{"sekret_id": "d25_linia_0809", "co_widac": "Księga wydań otwarta na linii 0809. Pusta, z wąskim polem na imię. Tuszem w rogu: „0913”.", "co_z_tego_wynika": "To kolejny odcinek ogłoszenia, czyli kolejny dyżurny. Linia jest pusta, ale już czeka na kogoś."}], "wejscie": "Elias Wren, numerek jeden. Księga leży otwarta na linii 0809, pustej, wąskiej. Pan Holt mówił, że linia jest dla następnego. Czekam, bo pytam o imię. Pytam, bo nikt nie pyta.", "tury": [{"pytania": [{"tekst": "Elias, co to za linia w księdze?", "ton": "uprzejme", "wymaga": null, "kto": "elias", "odpowiedz": "Linia 0809. Wąska, od lat pusta. Pan Holt mówił, że jest dla następnego. Nie wiem, dla którego. Dziś pierwszy raz widzę ją z bliska.", "mina": "mowi"}, {"tekst": "Kto zapisuje imiona w tej księdze?", "ton": "rzeczowe", "wymaga": null, "kto": "elias", "odpowiedz": "Dyżurny. Tylko on ma prawo. Ja pytam, żeby ktoś zapisał, że ktoś tu był. Bez imienia człowiek jest numerkiem, nawet jeśli stoi przy szybie.", "mina": "mowi"}, {"tekst": "Elias, czemu zawsze pytasz o imię?", "ton": "niewygodne", "wymaga": null, "kto": "elias", "odpowiedz": "Bo oprawkę znalazł człowiek, którego nie znałem. Żałuję, że nie spytałem o imię wcześniej. Teraz pytam każdego.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Elias, co by się stało, gdyby linia została pusta?", "ton": "uprzejme", "wymaga": null, "kto": "elias", "odpowiedz": "Nic. Księga leży, a ludzie wchodzą i wychodzą. Ale nikt by nie wiedział, że ktoś tu siedział. A to różnica.", "mina": "mowi"}, {"tekst": "Elias, czy Sam kazał Ci tu być?", "ton": "rzeczowe", "wymaga": null, "kto": "elias", "odpowiedz": "Nie kazał. Mówił, że będzie dziś ktoś ważny, i że wolałby, żeby ktoś go zobaczył. Zostałem, bo nie wypada odchodzić, kiedy ktoś ma wybierać.", "mina": "mowi"}, {"tekst": "Elias, wiesz, co jest w księdze, czego Ci nie pokazywano?", "ton": "niewygodne", "wymaga": null, "kto": "elias", "odpowiedz": "Wiem, że strona 41 była kiedyś cała. Wiem, że ktoś ją wyrwał. Nie pytam, kto. Wiem, że ktoś ją znowu chciałby mieć.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Elias, co chcesz od tej księgi?", "ton": "uprzejme", "wymaga": null, "kto": "elias", "odpowiedz": "Żeby linia nie była pusta, kiedy wyjdę. Albo żeby ktoś jej nie wypełnił bez zgody. Nie umiem się zdecydować, więc wybór zostawiam komuś młodszemu.", "mina": "emocja"}, {"tekst": "Elias, co powiesz osobie, która tu zostanie?", "ton": "rzeczowe", "wymaga": null, "kto": "elias", "odpowiedz": "Że dziękuję. Że oprawkę mam. Że imię zapisuję w pamięci, jeśli nie w księdze. To też jest sposób, żeby ktoś był.", "mina": "emocja"}, {"tekst": "Elias, czy jesteś pewien, że chcesz, żeby to była moja decyzja?", "ton": "niewygodne", "wymaga": null, "kto": "elias", "odpowiedz": "Nie. Ale jest tylko jedna osoba po tej stronie szyby i tylko ona może zdecydować. Przykro mi, że to wypadło na Ciebie.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wpisz_siebie", "etykieta": "Wpisz siebie w linię 0809", "kto": "elias", "reakcja": "Iris, od drzwi: „Bilet jest. Czeka na peronie, aż ktoś podpisze po Tobie. Do poniedziałku.” Elias składa numerek: „Dobry początek.”", "zysk": "Twoje imię stoi w księdze, a bilet na peronie czeka, aż ktoś podpisze po Tobie.", "strata": "Rotacja trwa i następnego wybiorą tak, jak wybrano Ciebie.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Elias Wren: „Dobry wieczór, [imię]. Czy oprawka jest u Was? Pytam, bo teraz wiem, kto tu siedzi.”"}}, {"akcja": "wyrwij", "etykieta": "Wyrwij stronę, jak Sam", "kto": "elias", "reakcja": "Wyrwana. Cicho. Jak Sam. Kanał Skrytki umiera, a ogłoszenia na słupie nie będzie. Nie wiem, czy to uczciwe wobec tych, którzy czekali.", "zysk": "Wychodzisz wolny, rotacja się zatrzymuje, a Skrytka traci kanał.", "strata": "Klienci zostają bez drogi, a Vera zostaje z kluczami do pustych szafek.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Elias Wren: „Czy Sam już był? Pytam pusty fotel. Nikt nie odpowiada. Wrócę jutro.”"}}, {"akcja": "list", "etykieta": "Zostaw list następnemu, dopisz własne linie", "wymaga": "notatki_3", "kto": "elias", "reakcja": "List zostaje w szafce 0809. Dopisane linie uzupełniają to, czego brakowało. Ktoś znajdzie to w pierwszy wieczór i ktoś będzie przy nim, żeby mu to powiedzieć.", "zysk": "Następny dyżurny dostaje całość, a nie tylko puste pole.", "strata": "List zostaje w szafce, a Ty zostajesz z pytaniem, czy dopisane wystarczy.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Elias Wren: „Jak się nazywasz? Pytam, bo list zostaje dla kogoś, a Ty odchodzisz. Dziękuję, [imię]. Jutro.”"}}, {"akcja": "zamknij", "etykieta": "Zamknij księgę i nic nie rób", "kto": "elias", "reakcja": "Zamknięta. Linia 0809 zostaje pusta. Dziś nikt nie wchodzi, nikt nie wychodzi. Zostaje tylko czynsz i noc.", "zysk": "Czynsz zapłacony, nikt nie świętuje, a księga leży na swoim miejscu.", "strata": "Nic się nie zmienia, ale też nic nie wyjaśnia się za Ciebie.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Elias Wren: „Czy ktoś wyjechał? Pytam, bo numerek składam. Nie wiem, dlaczego mnie to tak trzyma za gardło.”"}}], "rola": "księga otwarta na linii 0809", "watki": ["Fotel"], "tik": "Elias składa numerek", "potrzeba": "żeby ktoś zapisał imię", "slad": "cztery gesty do wyboru na Twojej linii", "sprite": "pudelko", "face": null, "face2": null, "line": "6", "itemName": "Księga wydań otwarta na linii ", "inside": null}];window.EXTRA={"2": {"sprite": "szalik", "itemName": "szalik", "line": "4", "inside": null, "wnetrze": [{"sekret_id": "d2_szalik_md", "co_widac": "Pod zagiętą metką wyhaftowane inicjały M.D. W wewnętrznej kieszonce złożony bilet miesięczny na linię 4, imienny: Maya Doyle.", "co_z_tego_wynika": "Szalik należy do Mai Doyle, którą mąż zgłosił jako zaginioną. Maya zostawiła go w tramwaju."}]}, "6": {"sprite": "puszka", "itemName": "puszka po herbacie", "line": "6", "inside": {"img": "W4", "x": 0.23, "y": 0.44}, "wnetrze": [{"sekret_id": "d6_puszka_odcinek", "co_widac": "Pod ruchomym dnem puszki leży odcinek odbioru. Numer jest z tego samego bloczka co blankiet w płóciennej paczce Iris Bell z dnia czwartego. Na spodzie puszki ołówkiem: „Nie ufaj drugiej kopii. S.H.”", "co_z_tego_wynika": "Puszka należy do obiegu paczek Skrytki."}]}, "3": {"sprite": "skrzynka_narzedz", "itemName": "zielona skrzynka z numerem 3", "line": "6", "inside": null, "wnetrze": [{"sekret_id": "d3_skrzynka_zegarek", "co_widac": "W skrzynce męski zegarek, na kopercie grawer „T.R. — od T.”. Pod zegarkiem klucz z mosiężnym numerkiem i karta z numerem szafki, ołówkiem.", "co_z_tego_wynika": "Ktoś zostawił to w tramwaju. Zegarek, klucz i karta należą do jednej osoby, której kolejka jeszcze nie wywołała."}]}, "9": {"sprite": "legitymacja", "itemName": "karta rozliczeniowa z pieczątką", "line": "6", "inside": null, "wnetrze": [{"sekret_id": "d9_karta_km", "co_widac": "Karta przy żetonach: „Opłata 60 $. K.M.” Pod spodem ołówkiem rata sobotnia i dopisek „wgląd Kancelarii”.", "co_z_tego_wynika": "Marlow odbiera sobotnie raty i podpisuje je inicjałami K.M. Pieczątka „wgląd Kancelarii” oznacza, że ktoś kupił wgląd w kopie z biura."}]}, "15": {"sprite": "teczka", "itemName": "kalka z szuflady", "line": "6", "inside": null, "wnetrze": [{"sekret_id": "d15_kalka_41", "co_widac": "Kalka strony 41: cztery pozycje klientów i czternaście wpłat lokatorów po 400 $. Linie od jeden do pięć są czytelne (cztery klienckie i wpłaty), szósta zaklejona taśmą.", "co_z_tego_wynika": "To brakująca strona. Dowód dla Nory, ale i lista ludzi, których można znaleźć."}, {"sekret_id": "d15_zatwierdzenie_victora", "co_widac": "Zatwierdzenie rozliczenia z podpisem Victora. Pod spodem dopiski innym tuszem.", "co_z_tego_wynika": "Po zamknięciu audytu ktoś jeszcze poprawiał rozliczenie."}, {"sekret_id": "d15_szosta_linia", "co_widac": "Pod taśmą szósta linia: „0809 / dyżurny nast. / ____”. Ołówkiem Sam dopisał: „Jeśli to czytasz, nie czytaj dalej przy Victorze.”", "co_z_tego_wynika": "Na stronie była linia dla następnego dyżurnego, z pustym polem na imię. Ktoś ją zakleił celowo."}]}, "24": {"sprite": "kuferek", "itemName": "szafka 0809", "line": "6", "inside": null, "wnetrze": [{"sekret_id": "d24_list_pelny", "co_widac": "W szafce pusta teczka i złożony list, pismo Sama. Cały tekst: „Jeśli to czytasz, siedzisz na moim miejscu, a to miejsce miał ktoś przede mną i ktoś przed nim. Nie wiem, przed czym uciekasz. Iris też nie wie. Taki jest warunek: dyżurny to ktoś, kogo nikt nie szuka, więc nikt nie przyjdzie pytać. Pierwszego dnia pomyślałem, że mam szczęście. W trzecim tygodniu zrozumiałem, że mam teczkę bez nazwiska i bilet, którego nie wolno mi użyć, dopóki ktoś nie usiądzie. Wyrwałem stronę 41, bo była na niej Twoja linia. Nie chciałem, żeby ktokolwiek wpisał tam Twoje imię za Ciebie. Prawa wydana bez wpisu, lewa czeka: tak zaczynam każdego następnego. Wpisuj mało. Pytaj o imiona. Nie ufaj drugiej kopii. A kiedy będziesz odchodzić, zostaw ten sam list następnemu. — S.”", "co_z_tego_wynika": "Pełny list Sama do następcy. Silnik pokazuje ten sekret, jeśli licznik notatki ≥ 3."}, {"sekret_id": "d24_list_luki", "co_widac": "W szafce pusta teczka i złożony list, pismo Sama, z lukami: „Jeśli to czytasz, siedzisz na moim miejscu, a to miejsce miał ktoś przede mną i ktoś przed nim. Nie wiem, przed czym uciekasz. […] Pierwszego dnia pomyślałem, że mam szczęście. […] Wyrwałem stronę 41, bo była na niej […]. Prawa wydana bez wpisu, lewa czeka: tak zaczynam […]. Wpisuj […]. A kiedy będziesz odchodzić, zostaw […] następnemu. — S.” (Brakuje Ci słów, żeby poskładać resztę.)", "co_z_tego_wynika": "Fragmenty listu Sama, resztę trzeba było zebrać z notatek. Silnik pokazuje ten sekret, jeśli licznik notatki < 3."}]}, "25": {"sprite": "legitymacja", "itemName": "karta Kopie", "line": "6", "inside": null, "wnetrze": [{"sekret_id": "d25_karta_kopie", "co_widac": "Karta: „Kopie wysłane do Urzędu: {kopie}. Klienci odnalezieni: {min(4, kopie)}.” Poniżej nazwiska: Gus (jeśli d5 wykaz_paczke lub d9 zetony_victor), Maya (d9 zetony_victor lub d22 stahl_wydaj), Linh (d9 zetony_victor lub d15 victor_od_razu), Dorian (d9 zetony_victor lub d18 do_kontroli). Stempel: „wgląd Kancelarii, K.M.”", "co_z_tego_wynika": "Każdy wpis w dwóch egzemplarzach to była druga kopia. Kancelaria wykupiła wgląd za 60 $ i odsprzedała go dalej. {kopie} i {min(4, kopie)} liczy silnik z licznika."}]}};window.WIECZOR={"1": [{"kto": "Elias, numerek 1", "tekst": "Elias przyszedł pod koniec zmiany. „Czy jest już oprawka po mojej żonie?” Nie było. Podziękował i długo stał przy szybie, jakby miało się coś zmienić."}], "2": [{"kto": "Elias, numerek 1", "tekst": "Elias, ten sam numerek. Zapytał o oprawkę, a potem, czy poprzedni pracownik zostawił jakąś notatkę o jej szukaniu. Nie zostawił."}, {"kto": "Kartka pod drzwiami domu", "tekst": "„Kuba Marlow. Trzysta dolarów, rata sześćdziesiąt w każdą sobotę. Lubię ludzi punktualnych. Nie krzyczę, tylko przypominam.” Nie wiesz, skąd wiedział, gdzie mieszkasz."}, {"kto": "Biuro", "tekst": "W piątek Urząd liczy skrzynie."}], "3": [{"kto": "Elias, numerek 1", "tekst": "Burza. Elias przyszedł w deszczu, z parasolem bez rączki. „Czy jest oprawka?” Nie było. Wziął suchy numerek i złożył go w prostokąt ciaśniejszy niż zwykle."}, {"kto": "Okno naprzeciwko", "tekst": "W oknie naprzeciwko stoi ktoś w kapeluszu. Nie rusza się, dopóki nie zgasisz lampy."}], "4": [{"kto": "Elias, numerek 1", "tekst": "Elias powiedział, że poprzedni pracownik obiecał szukać oprawki z własnej kieszeni. Zapytany, co to znaczy, wzruszył ramionami: nie wie, czy wolno mu mówić."}, {"kto": "Kuba Marlow, przez sąsiadkę", "tekst": "Sąsiadka powiedziała, że ktoś pytał, czy jesteś w domu. Odpowiedziała, że pracujesz w nocy. „To dobrze”, miał powiedzieć. „Noc to czas na pieniądze.”"}], "5": [{"kto": "Elias, numerek 1", "tekst": "Elias przyniósł gazetę. Na trzeciej stronie apel o Maję Doyle: trzydzieści cztery lata, krótkie czarne włosy, płaszcz z za długimi rękawami. W drobnych ogłoszeniach to samo co na słupie: nocne okienko, bez referencji, zaplecze tramwajowe, wejście od podwórza. „Ciągle to samo”, powiedział. Zapytał o oprawkę. Nie było. Gazeta została na ladzie."}, {"kto": "Ostatni w kolejce", "tekst": "Mężczyzna w szarym kapeluszu stał na końcu i nic nie powiedział. Patrzył, jak pracujesz. Wyszedł bez numerka."}], "6": [{"kto": "Elias, numerek 1", "tekst": "Elias zapytał o oprawkę, a potem, jak nazywa się osoba za szybą. Poprzedni pracownik zawsze przedstawiał się z imienia. Nikt mu jeszcze tego nie powiedział."}, {"kto": "Kuba Marlow, pod bramą zajezdni", "tekst": "Stał po drugiej stronie ulicy. Nie podszedł. Uniósł rękę i pokazał sześć palców: rata, sześćdziesiąt dolarów. Potem poszedł, jakby nic się nie stało."}], "7": [{"kto": "Elias, numerek 1", "tekst": "Elias: „On wiedział, że nie będzie. Mówił: jeszcze nie, panie Eliasie. A potem przestał mówić.” Wziął numerek i wyszedł wolno."}], "8": [{"kto": "Gazeta", "tekst": "Cooper Street 9 idzie pod wyburzenie, lokatorzy mają czas do czwartku, dziewiątego września. Twój pokój służbowy jest pod tym samym adresem. Nikt nie napisał, dokąd się wyprowadzisz."}, {"kto": "Elias, numerek 1", "tekst": "Elias zostawił papierowy woreczek z dwoma ciastkami z cukierni obok. „To nie łapówka. To za nocne.” Zapytał o oprawkę. Nie było."}, {"kto": "Kuba Marlow, przez kuzyna", "tekst": "Kuzyn przyniósł kartkę: „Rata sześćdziesiąt, plus piętnaście odsetek za spóźnienie. K.M.” Powiedział, że Kuba nie jest zły, tylko nie lubi czekać."}], "9": [], "10": [{"kto": "Elias, numerek 1", "tekst": "Elias: „Pytam, bo on mi oddał pieniądze za oprawkę. Nie chciałem ich. Leżą u mnie w kopercie. Jak oprawka się znajdzie, oddam kopertę.” Numerek złożył w prostokąt bardzo ciasny."}, {"kto": "Kuba Marlow, po wypłacie", "tekst": "Czekał pod bramą z zeszytem w ręku. Powiedział: „Rata to nie wszystko. Można się dogadać inaczej, jak ktoś ma dostęp do rzeczy, które ludzie zostawiają w tramwajach.” Poszedł, zanim padła odpowiedź."}], "11": [{"kto": "Elias, numerek 1", "tekst": "Elias zapytał o oprawkę. Dodał, że dziewczynka z królikiem powiedziała mu na ulicy: „Ktoś tu pana poznaje.” Nie wie, co miała na myśli, ale mu się podobało."}], "12": [{"kto": "Elias, numerek 1", "tekst": "Elias zapytał, czy ktoś wyjechał. O świcie przejeżdżał pociąg 5:40. Powiedział, że takie rzeczy się słyszy, nawet jeśli nikt nie opowiada."}, {"kto": "Kuba Marlow, przez kuzyna", "tekst": "„Rata sześćdziesiąt plus piętnaście odsetek. Kuba pyta, czy ten człowiek z paczką przy szybie to klient. Mówi, że jak ma interes, to można się dogadać. K.M.”"}], "13": [{"kto": "Elias, numerek 1", "tekst": "Elias po raz pierwszy zrozumiał, że ktoś wypełnił za niego rzecz, o którą nie prosił. Siedział długo. Potem zapytał, czy wolno mu przyjść jutro, bez numerka."}], "14": [{"kto": "Elias, numerek 1", "tekst": "Elias zapytał, czy podpis do wtorku, siódmego września, to termin, czy prośba. Odpowiedział sam sobie: „Termin. Dla mnie zawsze termin.” Wziął suchy numerek."}, {"kto": "Kuba Marlow, pod bramą", "tekst": "Stał na przystanku z kolegą. Powiedział głośno: „Czasem pożyczka to nie jest pieniądz. Czasem to zostawianie sobie otwartych drzwi.” Kolega się zaśmiał. Ty nie."}], "15": [{"kto": "Elias, numerek 1", "tekst": "Elias zobaczył Sama przez szybę i przez chwilę nic nie mówił. Złożył numerek w prostokąt i wyszedł. Na ladzie została koperta z napisem: „S. Dla pana Holta. Od E.W.”"}, {"kto": "Kartka pod szybą", "tekst": "Na kartce od Helen Voss: „Sprawdzam Okienko. Proszę przygotować księgę wydań do wglądu w piątek.” Pieczątka Inspekcji."}], "16": [{"kto": "Elias, numerek 1", "tekst": "Elias zapytał o oprawkę, a potem, czy w biurze był ktoś z walizką i kobietą, która liczy do trzech. Nie wiedział, skąd to wie. Powiedział, że takie rzeczy się rozpoznaje po sposobie, w jaki ktoś stoi."}, {"kto": "Kuba Marlow, przez kuzyna", "tekst": "„Rata sobotnia. Kuba przypomina, że dług można zamknąć jednym ruchem, jeśli ktoś ma dostęp do tego, co ludzie zostawiają. Bez presji. K.M.”"}, {"kto": "Karta pod szybą", "tekst": "Maya zostawiła na ladzie kartkę: „Walizka we wtorek, 6:10. Nie spóźnij się.”"}], "17": [{"kto": "Elias, numerek 1", "tekst": "Elias zobaczył Evana w kolejce i skinął głową. Nie znał go, ale poznał mankiet. Zapytał potem szeptem: „Czy ktoś, kto poprawia mankiet, jest dobry, czy zły?” Nie było odpowiedzi."}, {"kto": "Karta pod szybą", "tekst": "Mężczyzna w szarym kapeluszu poprawił mankiet i wyszedł bez numerka. Evan patrzył za nim przez szybę."}], "18": [{"kto": "Elias, numerek 1", "tekst": "Elias przyniósł papierową torbę z pączkiem. „To nie za pomoc. To za nocne.” Zapytał o oprawkę, choć już ją miał. Powiedział: „Nawyk.”"}, {"kto": "Kuba Marlow, na schodach", "tekst": "„Trzysta dolarów. Równo tyle, ile jesteś mi winien. Zbieg okoliczności, prawda?” Kuba uśmiechnął się, jakby wiedział o ofercie Iris. Nie powiedział, skąd."}, {"kto": "Karta pod szybą", "tekst": "Na słupie przed biurem wisi nowa kartka: „Pokój służbowy do wynajęcia od zaraz. Bez referencji.”"}], "19": [{"kto": "Elias, numerek 1", "tekst": "Elias zobaczył Adę z kartonem pod pachą. „Dziewczynka z królikiem się przeprowadza?” Nie czekał na odpowiedź. Zostawił na ladzie jednego cukierka, owiniętego w kartkę z napisem: „Dla pani z królikiem.”"}, {"kto": "Karta pod szybą", "tekst": "Ada zostawiła rysunek: dom z dwoma oknami i napis „mamy dzień na spakowanie”."}], "20": [{"kto": "Elias, numerek 1", "tekst": "Elias po raz pierwszy w życiu nie złożył numerka. Rozprostował go na ladzie, wygładził kciukiem i oddał. Powiedział: „Dziękuję. Jutro.” I po raz pierwszy zabrzmiało to jak obietnica."}, {"kto": "Kuba Marlow, pod bramą", "tekst": "Stał w deszczu bez parasola. „Nie jestem zły”, powiedział. „Czekam.” Potem odwrócił się, jakby to było wszystko."}, {"kto": "Karta pod szybą", "tekst": "Sam napisał na odwrocie numerka: „Jak Cię zapisać?” Zostawił go pod szybą."}], "21": [{"kto": "Elias, numerek 1", "tekst": "Elias zapytał o oprawkę. Potem, z numerkiem w palcach: „Czy ktoś wyjechał?” Nie było odpowiedzi. Pokiwał głową, jakby odpowiedź była w tym pytaniu."}, {"kto": "Kuba Marlow, przez kuzyna", "tekst": "„W sobotę rozliczenie. Dwóch twoich sąsiadów już zapłaciło. K.M.”"}], "22": [{"kto": "Elias, numerek 1", "tekst": "Elias zobaczył mężczyznę w szarym kapeluszu i zmrużył oczy. „Ten pan zawsze czyta, zanim pisze.” Zapytał, czy zapisano, kto go widział. Nikt nie zapisał."}, {"kto": "Kuba Marlow, na schodach", "tekst": "Marlow podniósł głowę, kiedy ktoś wychodził. „Człowiek w płaszczu spisał dziś, kto mieszka w twoim domu. Nie ja go przysłałem. Ale mówię, żebyś wiedział.”"}, {"kto": "Karta pod szybą", "tekst": "Pod drzwiami biura leżała kartka od Victora: „O 6:00 w środę zamykam obieg. Proszę przynieść księgę.”"}, {"kto": "Helen Voss, w kolejce", "tekst": "W kolejce stanęła kobieta w granatowym płaszczu. Nie miała numerka. Zapytała Eliasa, czy to jest to okienko. Elias powiedział, że tak. Zapisała jego imię w notesie."}], "23": [{"kto": "Elias, numerek 1", "tekst": "Elias zobaczył Iris na schodach. „Pani z cichym głosem”, powiedział. „Nie lubi naciskać. Zauważyłem, że ludzie, którzy tak mówią, naciskają najmocniej.” Nie znał jej, ale mówił jak ktoś, kto ją pamięta."}, {"kto": "Kuba Marlow, pod bramą", "tekst": "Kuba stał pod bramą kamienicy. „Dziś wszyscy rozliczają. Ja też. Soboty nie odpuszczę.”"}, {"kto": "Karta pod szybą", "tekst": "Na karcie bez adresu: „Wgląd w kopie z biura. Opłata 60 $. K.M.” Ktoś zapłacił, żeby przeczytać nazwiska."}], "24": [{"kto": "Elias, numerek 1", "tekst": "Elias przyniósł Samowi kartkę z jednym zdaniem: „Dziękuję za oprawkę.” Położył ją na ladzie i wyszedł. Sam jej nie zabrał. Leżała cały wieczór, jakby czekała na kogoś trzeciego."}, {"kto": "Kuba Marlow, na schodach", "tekst": "Marlow siedział na schodach z kubkiem. „W sobotę zamykamy rozliczenie. Przyjdź sam.” Potem upił i dodał: „Nie dlatego, że się boję. Dlatego, że Ty już wiesz, jak to się kończy.”"}, {"kto": "Karta pod szybą", "tekst": "Pod szybą leżał klucz do szafki 0809. Na kartoniku: „Strona 41 jest Twoja.”"}, {"kto": "Karta pod szybą", "tekst": "Stempel: „wgląd Kancelarii”. Ktoś pytał w Kancelarii o nazwisko z Waszej kopii. Opłata 60 $. Podpis K.M."}], "25": [{"kto": "Elias, numerek 1", "tekst": "Elias złożył numerek w prostokąt, potem w mniejszy prostokąt. Powiedział: „Dziękuję. Jutro.” Po raz pierwszy zabrzmiało jak coś, co się spełni."}, {"kto": "Kuba Marlow, przez kuzyna", "tekst": "„Rata sobotnia. Jutro. Przyjdź sam. K.M.” Pod spodem dopisek ołówkiem: „Nie musisz nic mówić. Ale ktoś musi usłyszeć.”"}, {"kto": "Protokół Voss", "tekst": "Helen Voss zostawiła na ladzie protokół z jednego zdania: „Okienko działa zgodnie z regulaminem. Zalecam obserwację.” Podpisała się pełnym imieniem."}]};window.LANG={"title": "LOST & FRAUD", "sub": "Nocna zmiana w biurze rzeczy znalezionych. Tydzień pierwszy.", "start": "Zacznij zmianę", "settings": "Ustawienia", "close": "Zamknij", "day": "Dzień", "delivery": "Dziś z tramwajów: {n} {rz}. Zanim ktoś zapuka, zdążysz obejrzeć jedną od środka.", "look": "Zajrzyj", "skip": "Nie zaglądam, otwieram okienko", "line": "Linia", "inspect_hint": "Przeszukaj rzecz. Kliknij to, co nie pasuje.", "found": "Wiesz coś, czego nie powinieneś.", "open": "Otwórz okienko", "nothing": "Zwykła rzecz. Czasem parasol jest po prostu parasolem.", "knock": "Ktoś puka w szybę.", "let_in": "Odsuń zasłonkę", "know": "wiesz ze środka", "turn": "Odwróć się do magazynu", "search": "Znajdź w magazynie", "search_p": "Wybierz skrzynię wg linii, potem przekopuj. Kliknij rzecz, którą bierzesz.", "wrong": "To nie ta rzecz:", "wrong_line": "Tu tej rzeczy nie ma. Spróbuj inną linię.", "decide": "Rzecz leży na ladzie. Przeciągnij ją albo wybierz.", "wydaj": "Wydaj: przez okienko", "odmow": "Odmów: do skrzyni", "zatrzymaj": "Zatrzymaj: na półkę", "zadzwon": "Zadzwoń po dyżurnego", "next": "Dalej", "evening": "Świt. Poczta na ladzie.", "nomail": "Dziś nikt nie napisał.", "week_h": "Sobota. Rozliczenie.", "pay": "Wypłata", "rent": "Czynsz", "balance": "Zostaje", "drawer": "W szufladzie leży klucz bez zamka. Poprzednik nie zabrał wszystkiego.", "again": "Zacznij od nowa", "next_day": "Następny dzień", "dollar": "$", "vol_master": "Głośność ogólna", "vol_music": "Muzyka", "vol_amb": "Ambient", "vol_sfx": "Efekty", "vol_voice": "Głosy", "reduce": "Ogranicz błyski i wstrząsy", "end": "Koniec dostępnych dni. Dalej: dni, które jeszcze piszemy.", "storm": "Burza. Grom zrzucił skrzynie z półki: rzeczy leżą w innych skrzyniach niż zapisano.", "up_h": "Ulepszenie biura (jedno na sobotę)", "up_none": "Nic nie kupuję", "up_lampa": "Wymień lampę (mruganie ustaje, w biurze robi się nudno)", "up_drzwi": "Uszczelnij drzwi (deszcz za szybą ciszej)", "up_regal": "Dołóż regał (rzeczy ułożone alfabetycznie, skrzynie mieszczą więcej)", "owned": "kupione", "week2": "Następny tydzień", "rent2": "Czynsz za tydzień", "end_zag_A": "Przychodzi pocztówka bez nadawcy z jednym słowem: „Dziękuję”. Evan dostaje suknię. To cała odpowiedź, jaką dostaje. Noah zamyka zgłoszenie.", "end_zag_B": "Noah potwierdza, że Maya jest bezpieczna, i zamyka zgłoszenie. Lena kładzie na ladzie jeden klucz, ten od mieszkania, które Maya zostawiła, i pyta, czy ktoś kiedyś po niego przyjdzie.", "end_zag_C": "Maya przychodzi już tylko po walizkę, bez rozmów, i wyjeżdża na własnych warunkach. Evan wynajmuje detektywa. Lena stoi przy okienku bez Mai i pyta, czy coś zostało po jej siostrze. Gracz wie, że zostało wszystko.", "end_skr_A": "Nora odbiera komplet. Okoye nie płacą drugi raz, a Iris podpisuje rozliczenie i oddaje 6 800 $. Grace Okoye w szpitalnym fartuchu kładzie na ladzie pączek w papierze: „Z dyżuru.”", "end_skr_A2": "Nora ma papiery, ale Iris kwestionuje ich autentyczność i sprawa idzie do sądu poza tą nocą. Grace Okoye kładzie na ladzie pączek w papierze: „Z dyżuru.” Nie wie jeszcze, czy zapłaci drugi raz.", "end_skr_B": "Victor zamyka obieg paczek, przyjmuje oryginały do audytu i zajmuje 6 800 $ jako dowód. Ludzie z żetonów są w aktach. Przychodzi zimny list z Urzędu, a w kolejnym wierszu nazwisko, które znasz z twarzy.", "end_skr_C": "Iris zabiera paczkę, oryginały i 6 800 $. Nora ma kopię jednej wpłaty, resztę będzie musiała odtworzyć. Kamienica o świcie, ekipa rozbiórki. Iris nie ma jej w oknie.", "end_pop_A": "Sam podpisuje zeznanie, Victor dopisuje własny podpis sprzed pięciu tygodni i wycofuje wpis obciążający Sama. Sam wychodzi. Elias siada na krześle poczekalni po raz pierwszy, odkąd pamięta, i czeka na tramwaj, jakby nigdzie się nie spieszył.", "end_pop_B": "Sam odbiera swoje rzeczy i wychodzi, nie odwracając się. W protokole zostaje niedobór. Wyjaśnienie krąży tylko między osobami, które zgodziły się mówić.", "end_pop_C": "Sam, wystawiony, dostaje od Iris pusty bilet bez numeru i znika. Zostawia u Very kopertę z 85 $ dla Eliasa. Elias odmawia jej przyjęcia i składa numerek w najciaśniejszy prostokąt, jaki widziałeś.", "ep_nowysam": "Victor zapisuje niedobór na twojej zmianie. Wypowiedzenie, rzeczy spakowane w pudełku. Następnego wieczoru przychodzi nowy pracownik i pyta o brakującą stronę.", "ep_nowysam_tear": "Victor zapisuje niedobór na twojej zmianie. Wypowiedzenie, rzeczy w pudełku. Wyrwana strona leży już gdzie indziej. Następnego wieczoru przychodzi nowy pracownik i pyta o brakującą stronę.", "ep_referent": "Victor dopisuje do akt Twoje nazwisko, {imie}, po kopiach, które sam podpisał. Umowa przedłużona, awans na starszego referenta, wypłata z premią. Zostajesz w okienku.", "ep_referent_tear": "Umowa przedłużona, awans na starszego referenta. W księdze brakuje twojej strony i nikt o nią nie pyta. Zostajesz w okienku jako następny przechowawca.", "ep_zostajesz": "Czynsz zapłacony, umowa przedłużona. Nikt tego nie świętuje.", "ep_zostajesz_tear": "Czynsz zapłacony, umowa przedłużona. W księdze brakuje twojej strony, tak jak po poprzedniku. Jesteś następnym przechowawcą.", "elias_A": "„Czy ktoś jeszcze czeka?”", "elias_B": "„Do jutra.”", "elias_C": "(milczy i kładzie numerek na ladzie)", "elias_N": "„Czy Sam już był?” (do tego, kto siedzi w okienku jutro)", "stock": "W skrzyni", "sorted": "ułożone alfabetycznie", "due": "do soboty", "bills": "Rachunki i jedzenie", "you_ask": "Pytasz:", "audit": "Victor policzył gotówkę w szufladzie i nie zgadza się z zapisami. Potrącenie: {f} $. Zapisał to na twojej zmianie.", "step_delivery": "Krok 1: kliknij rzecz, do której chcesz zajrzeć (albo „Nie zaglądam”)", "step_inspect": "Szukaj śladów: kliknij w obrazie to, co wygląda nie na miejscu", "step_knock": "Krok 2: kliknij „Odsuń zasłonkę”", "step_ask": "Krok 3: kliknij jedno z trzech pytań na dole", "step_turn": "Krok 4: kliknij „Odwróć się do magazynu”", "step_pile": "Krok 5: wybierz skrzynię, kliknij rzecz z opisu", "step_decide": "Krok 6: przeciągnij rzecz na szybę albo kliknij jedną z opcji po prawej", "tut_h": "Jak grać", "tut_ok": "Zaczynam zmianę", "tut_l": ["Tramwaje zostawiają rzeczy w skrzyniach. Każda linia ma swoją skrzynię.", "Możesz zajrzeć do jednej rzeczy od środka: kliknij ją, potem klikaj w obraz, aż coś nie będzie pasować.", "Kliknij „Odsuń zasłonkę”: ktoś przyszedł po swoją rzecz.", "Zadaj trzy pytania, klikając je. Słuchaj uważnie: ktoś może kłamać.", "Odwróć się do magazynu, wybierz skrzynię i kliknij właściwą rzecz według opisu na górze.", "Przeciągnij rzecz na szybę, żeby ją wydać, albo kliknij inną opcję. Każda ma cenę."], "dt": ["Rękawiczki na grobie", "Pierścionek w plecaku, szalik na wieszaku", "Dwie osoby, jeden telefon", "Koperta na ladzie, nikt jej nie dotyka", "Gazeta z twarzą Mai na ladzie", "Królik na ladzie, bilet na mokrym papierze", "Klucz, który otwiera nieznane drzwi", "Żółta kartka w podszewce", "Pięć żetonów w piórniku", "Pudełko po człowieku, który tu nie wraca", "Ktoś opisuje własne okulary, zanim je zobaczy", "Dwie kasetki, jedna torba na zakupy", "Oprawka, która wróciła z cudzego wozu", "Notes równo z krawędzią lady", "Klucz i szuflada", "Dwie siostry, jedno okienko", "List, który nie ma adresata", "Trzysta dolarów na ladzie", "Dziecko, które widziało za dużo", "Dwóch mężczyzn i koperta z 85 dolarami", "Dwie walizki, jedna jedzie na ślub", "Sztywna koperta i szary kapelusz", "Trzy osoby po jedną kasetkę", "Kartonik z numerem szafki", "Księga otwarta na twojej stronie"], "kartka_h": "Kartka przyklejona do skrzynki", "notes_b": "Notatnik", "notes_h": "Notatnik: kartki znalezione w rzeczach", "pr1_lab": "Słup przy zajezdni · 22:50", "pr1_txt": "POSZUKIWANY DYŻURNY. Nocne biuro rzeczy znalezionych, zmiana 23:40–6:00. 40 $ za wizytę. Pokój służbowy w cenie. Zgłosić się do Zarządu Nieruchomości Cooper.", "pr1_strip": "Oderwij pasek z numerem", "pr1_num": "Na pasku jest numer. Deszcz rozlał go tak, że nie da się go odczytać.", "pr1_next": "Idź do biura", "pr1_step": "Kliknij „Oderwij pasek”", "pr2_lab": "Umowa o pracę nocną · Zarząd Nieruchomości Cooper", "pr2_rows": ["Stanowisko: dyżurny", "Imię i nazwisko: ______________", "Miejsce pracy: biuro rzeczy znalezionych, pokój służbowy przy Cooper Street 9", "Wynagrodzenie: 40 $ za wizytę", "Podpis zarządcy: nieczytelny"], "pr2_btn": "Podpisz i zacznij zmianę", "pr2_step": "Kliknij, żeby zacząć pierwszą noc", "name_h": "Jak cię zapisać?", "name_s": "Wpisz cokolwiek. To imię wróci w księdze.", "name_p": "imię", "name_ok": "Zapisz", "name_def": "dyżurny", "ledger_h": "Księga wydań leży otwarta na twojej ostatniej stronie.", "ledger_s": "Co robisz z księgą?", "ledger_write": "Wpisz siebie: {n}", "ledger_tear": "Wyrwij stronę", "ledger_letter": "Zostaw list dla następcy", "ledger_close": "Zamknij księgę", "ledger_b": "Księga", "gest_wpisz": "W linii 0809 stoi teraz twoje imię. Następny dyżurny zacznie od niego.", "gest_wyrwij": "Strona leży wyrwana, tak jak po poprzedniku. Ludzie, których chroniłeś, nie mają już śladu w papierze, a ty nie masz obrony.", "gest_list": "Zostawiasz list w szufladzie. Następny dyżurny znajdzie go pierwszej nocy.", "gest_zamknij": "Zamykasz księgę. Nikt nie wie, czy to była decyzja.", "audit_warn": "W notesie Victora pierwsza rozbieżność tygodnia. Tym razem tylko upomnienie, bez kary. Następnym razem zapisze kwotę.", "bk_h": "Księga przyjęć", "bk_btn": "Księga przyjęć", "bk_note": "Wpisy robi konduktor przy dostawie. Znajdź opis, który pasuje do słów gościa, i szukaj rzeczy z tym numerem.", "tomorrow": "Jutro", "cont": "Kontynuuj: dzień {d}", "new_conf": "Zacząć od nowa? Zapis z dnia {d} zostanie skasowany.", "new_yes": "Nadpisz zapis", "new_no": "Zostaw zapis", "b_new": "NOWY", "b_back": "WRACA {n}/{m}", "b_last": "OSTATNI RAZ", "notes_none": "Jeszcze nic tu nie wpisałeś. Notatki S.H. znajdziesz w rzeczach.", "interest": "Marlow dolicza odsetki od długu: ${i}.", "evict_h": "Eksmisja", "evict_txt": "Dług urósł do ${d}. Marlow zamyka drzwi na klucz i oddaje Ci karton z rzeczami. Ktoś inny usiądzie za szybą.", "th_bar": "Nitki (szare to te, których zabrakło)", "th_sam": "Sam", "th_maya": "Maya", "th_skr2": "Skrytka", "th_notes": "Notatki", "th_list": "List", "ep_odebrany": "W poniedziałek 13.09, gdy ktoś podpisał po Tobie, odchodzisz. Następca dostaje list, a przy nim stoi Vera i mówi prawdę zamiast milczeć. Elias, odchodząc, pyta: „Jak się nazywasz?” Mówisz. „Dziękuję, {imie}. Jutro.”", "ep_odebrany_m": "W poniedziałek 13.09, gdy ktoś podpisał po Tobie, odchodzisz. Następca dostaje list, a przy nim stoi Vera i mówi prawdę zamiast milczeć. Elias, odchodząc, pyta: „Jak się nazywasz?” Mówisz. „Dziękuję, {imie}. Jutro.” Z poranną pocztą przychodzi kartka od Mai: „Odebrane.”", "ep_rotacja": "Poniedziałek 13.09, peron 6:10, pusty bilet, nowa twarz. Na słupie wisi nowy odcinek ogłoszenia: 0913.", "ep_rotacja_lb": "Poniedziałek 13.09, peron 6:10, pusty bilet, nowa twarz. Na słupie wisi nowy odcinek ogłoszenia: 0913. Listu nikt nie znalazł do poniedziałku.", "ep_wyrwana": "Wychodzisz wolny. Kanał Skrytki umiera, ludzie zostają bez drogi, a ogłoszenie przestaje się pojawiać. Na słupie nie ma już kartki.", "w_radio": "Radio", "w_glass": "Przetrzyj szybę", "w_tea": "Herbata", "w_phone": "Odbierz telefon", "w_cat": "Na parapecie siedzi mokry kot. Patrzy na lampę.", "w_cat2": "Kot mruży oczy. Chyba tu zostanie do rana.", "w_radio_l": ["Radio: „…linia szósta kursuje ze zmianami, motorniczowie proszą o cierpliwość…”", "Radio: „…policja prosi o kontakt świadków zdarzenia przy Cooper Street…”", "Radio: urwany fragment starej piosenki, potem szum.", "Radio: „…deszcz utrzyma się do rana, temperatura jedenaście stopni…”", "Radio: „…jeśli znaleźliście Państwo cudzą rzecz, oddajcie ją. Albo wpiszcie do księgi.”", "Radio: ktoś czyta wyniki loterii. Żaden numer Ci nic nie mówi."], "w_glass_l": ["Naprzeciwko świeci jedno okno. Ktoś też nie śpi.", "Na ulicy nikogo. Latarnia rzuca pomarańczową plamę na kałużę.", "Tramwaj przejeżdża pusty, z zapalonymi światłami.", "Za szybą mignął cień parasola, który się nie zatrzymał."], "w_tea_l": ["Herbata jest gorzka, ale gorąca. To wystarczy.", "Przy kubku leży ktoś cudzy ślad po ustach. Stary. Wycierasz.", "Myślisz: ile osób siedziało przy tej ladzie, zanim Ty?", "Para unosi się nad kubkiem i znika w świetle lampy."], "w_phone_l": ["Dzwoniła kobieta: „Zgubiłam parasol w czwórce, niebieski.” Notujesz.", "Dzwonił chłopak: „Czy znalazło się coś z dwunastki?” Odkładasz słuchawkę z wrażeniem, że się rozłączył za szybko.", "Ktoś oddycha w słuchawce i się rozłącza."], "leave_h": "Gość się zniecierpliwił", "leave_txt": "{g} ma dość czekania i wychodzi w deszcz. Tym razem bez napiwku. Rzecz zostaje w skrzyni.", "w_start": "Cisza. Deszcz. Lampa szumi. Czekasz, aż ktoś zadzwoni przy drzwiach.", "w_step": "Czekasz na gościa. Zajmij się czymś: poukładaj magazyn.", "w_step1": "Nikogo nie ma. Zanim ktoś przyjdzie, poukładaj magazyn (przycisk na dole).", "w_sort": "Poukładaj magazyn", "w_notes": "Notatnik", "w_sort_h": "Zawieruszone rzeczy", "w_sort_txt": "Te rzeczy leżą w złych skrzyniach. Na metce jest numer linii, którym przyjechały. Odłóż je na właściwą linię.", "w_sort_ok": "Wszystko leży tam, gdzie powinno. Można posłuchać deszczu.", "w_tag": "metka: linia", "w_bell": "Dzyń-dzyń. Ktoś wszedł przez drzwi.", "w_e1": "Za ścianą ktoś idzie korytarzem. Kroki cichną.", "w_e2": "Obcasy na schodach. Zatrzymały się, potem poszły dalej.", "w_e3": "W sąsiednim biurze dzwoni telefon. Nikt nie odbiera.", "w_e4": "Lampa mruga i wraca do równego szumu.", "w_e5": "Gdzieś daleko grzmi. Szyba drży.", "w_e6": "Ktoś przesunął szufladę w skrytce obok. A może to deszcz.", "epi_odebrany": "Elias: „Jak się nazywasz?” Gracz podaje imię z d20. „Dziękuję, [imię]. Jutro.”", "epi_wyrwana_strona": "Elias pyta pusty fotel: „Czy Sam już był?”", "epi_rotacja": "Elias pyta następcę o oprawkę.", "epi_rotacja_list_bez_warunkow": "Elias pyta następcę o oprawkę. Dopisek: „Listu nikt nie znalazł przez miesiąc.”", "epi_nowy_sam": "Victor zapisuje niedobór na zmianie gracza. Elias pyta o brakującą stronę.", "epi_referent": "Elias milczy i składa numerek. Awans, premia, karta Kopie z listą odnalezionych klientów.", "epi_zostajesz": "Czynsz zapłacony, nikt nie świętuje. Elias: „Dziękuję. Jutro.”", "th_kopie": "Kopie do Urzędu", "kopie_l": "Odnaleziono: ", "kopie_0": "Nikt nie został odnaleziony.", "kopie_txt": "Kopie wysłane do Urzędu: {n}. Klienci odnalezieni: {m}. Każdy wpis i każde pokwitowanie w dwóch egzemplarzach czytał ktoś, kto zapłacił za czytanie.", "ledger_none": "Nic nie ruszam", "ledger_fix": "Dopisz sprostowanie", "urzad": "Urząd", "ludzie": "Ludzie", "debt": "Tydzień zamknięty z długiem.", "final_h": "Koniec zmiany. Dzień 25.", "th_zag": "Zaginiona", "th_skr": "Skrytka", "th_pop": "Poprzednik", "you": "Ty", "elias": "Ostatnie pytanie Eliasa", "eve_note": "Poza okienkiem", "soon": "Dalej: dni, które jeszcze piszemy."};